window.__D("text/zohar-hebrew-translation/c015",{"p":[[9522011637,"<p>עַד כָּאן כָּל אוֹתָם סוֹדוֹת שֶׁל תּוֹלְדוֹת אָדָם, שֶׁהֵם תּוֹלָדוֹת שֶׁנּוֹלְדוּ בוֹ מִזְּמַן לִזְמַן כְּפִי דַרְכֵי הָאָדָם. אַשְׁרֵי חֶלְקָם שֶׁל אֵלּוּ שֶׁיּוֹשְׁבִים לִפְנֵי מוֹרֵנוּ וְזָכוּ לִשְׁמֹעַ מִפִּיו סוֹדוֹת הַתּוֹרָה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם לָעוֹלָם הַבָּא! אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵיכֶם הַחֲבֵרִים שֶׁכָּל הַסּוֹדוֹת לֹא נִסְתְּרוּ מִכֶּם, כַּמָּה מְקוֹמוֹת עֶלְיוֹנִים מְזֻמָּנִים לָכֶם לָעוֹלָם הַבָּא.</p>\n<p>פָּתַח וְאָמַר, וְאַתָּה תֶחֱזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים אַנְשֵׁי אֱמֶת שּנְאֵי בָצַע. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל וְאַתָּה תֶחֱזֶה, לֹא כָתוּב תִּבְחַר אֶלָּא תֶחֱזֶה, לְפִי מַרְאֵה הָעֵינַיִם. בַּמֶּה? בַּדְּיוֹקָן שֶׁל אָדָם בְּשֵׁשֶׁת הַצְּדָדִים הַלָּלוּ שֶׁאֲמַרְתֶּם, וְהַכֹּל בַּפָּסוּק הַזֶּה. וְאַתָּה תֶחֱזֶה - אַחַת, בַּשֵּׂעָר. מִכָּל הָעָם - שְׁתַּיִם, בַּמֵּצַח. אַנְשֵׁי חַיִל - שָׁלֹשׁ, בַּפָּנִים. יִרְאֵי אֱלֹהִים - אַרְבַּע, בָּעֵינַיִם. אַנְשֵׁי אֱמֶת - חָמֵשׁ, בַּשְּׂפָתַיִם. שּנְאֵי בָצַע - שֵׁשׁ, בַּיָּדַיִם, בְּשִׂרְטוּטֵיהֶם.</p>\n<p>שֶׁאֵלּוּ הֵם הַסִּימָנִים לָדַעַת בָּהֶם בְּנֵי אָדָם לְאוֹתָם שֶׁרוּחַ הַחָכְמָה שׁוֹרָה עֲלֵיהֶם. וְעִם כָּל זֶה, מֹשֶׁה לֹא הִצְטָרֵךְ לָזֶה, אֶלָּא מַה כָּתוּב? וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חַיִל מִכָּל יִשְׂרָאֵל, מִשּׁוּם שֶׁרוּחַ הַקֹּדֶשׁ הָיְתָה בָּאָה אֵלָיו וּמוֹדִיעָה לוֹ, וּבָהּ הָיוּ רוֹאִים הַכֹּל.</p>\n<p>מִנַּיִן לָנוּ? שֶׁכָּתוּב כִּי יִהְיֶה לָהֶם דָּבָר בָּא אֵלַי. בָּאִים אֵלַי לֹא כָתוּב, אֶלָּא בָּא אֵלַי. זוֹ רוּחַ הַקֹּדֶשׁ שֶׁהָיְתָה בָּאָה אֵלָיו, וּבָהּ הָיָה יוֹדֵעַ. וְלֹא הִצְטָרֵךְ לְכָל זֶה לְהִתְבּוֹנֵן וּלְעַיֵּן, אֶלָּא לְפִי שָׁעָה הָיָה מֹשֶׁה יוֹדֵעַ.</p>\n<p>כְּמוֹ זֶה יָדַע שְׁלֹמֹה הַמֶּלֶךְ, יָדַע בְּכִסְאוֹ, שֶׁרוּחַ הַקֹּדֶשׁ שָׁרְתָה עָלָיו. שֶׁכָּל מִי שֶׁקָּרַב לְכִסְאוֹ, פַּחַד וְאֵימָה נָפְלוּ עָלָיו, וּבוֹ הָיָה דָּן דִּין בְּלִי עֵדוּת, מִשּׁוּם שֶׁהַדְּיוֹקְנָאוֹת הָיוּ בְּכִסְאוֹ, וְכָל מִי שֶׁקָּרַב בְּשֶׁקֶר, אוֹתוֹ הַדְּיוֹקָן מְכַשְׁכֵּשׁ, וְהָיָה שְׁלֹמֹה הַמֶּלֶךְ יוֹדֵעַ שֶׁבָּא בְשֶׁקֶר. לָכֵן אֵימַת הַכִּסֵּא הָיְתָה נוֹפֶלֶת עַל הַכֹּל, וְכֻלָּם נִמְצְאוּ צַדִּיקִים לְפָנָיו.</p>\n<p>מֶלֶךָ הַמָּשִׁיחַ בְּרֵיחַ, כְּמוֹ שֶׁנֶּאֱמַר (שם יא) וַהֲרִיחוֹ בְּיִרְאַת ה' וְלֹא לְמַרְאֵה עֵינָיו יִשְׁפֹּט וְגוֹ'. וּשְׁלֹשֶׁת אֵלֶּה דָּנוּ אֶת הָעוֹלָם בְּלֹא עֵדִים וְהַתְרָאָה. שְׁאָר בְּנֵי הָעוֹלָם עַל פִּי עֵדִים, עַל מַאֲמַר הַתּוֹרָה. חֲכָמִים שֶׁמַּכִּירִים בְּאוֹתָם דְּיוֹקְנָאוֹת, עֲלֵיהֶם לְהַזְהִיר אֶת בְּנֵי הָעוֹלָם וְלָתֵת רְפוּאָה לִבְנֵי אָדָם וּלְרַפֵּא אֶת נַפְשָׁם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא!</p>"],[9522011638,"<p>וְאַתָּה תֶחֱזֶה מִכָּל הָעָם. זֶה סֵפֶר תּוֹלְדת אָדָם. זֶה סֵפֶר מֵאוֹתָם סְפָרִים נִסְתָּרִים וַעֲמֻקִּים (זה ספר מאותם נסתרים ועמקים). אָמַר רַבִּי שִׁמְעוֹן, הֵרַמְתִּי יָדַי בִּתְפִלָּה לְמִי שֶׁבָּרָא אֶת הָעוֹלָם, שֶׁאַף עַל גַּב שֶׁבַּפָּסוּק הַזֶּה גִּלּוּ הָרִאשׁוֹנִים נִסְתָּרוֹת עֶלְיוֹנִים, יֵשׁ לְהִתְבּוֹנֵן וּלְעַיֵּן בַּסּוֹדוֹת שֶׁל סֵפֶר אָדָם הָרִאשׁוֹן שֶׁמִּשָּׁם נִמְשַׁךְ סִפְרוֹ הַגָּנוּז שֶׁל שְׁלֹמֹה הַמֶּלֶךְ.</p>\n<p>זְהִ - שֶׁהַכֹּל תָּלוּי בּוֹ. זֶה - עֵץ הַחַיִּים. זֶה - וְלֹא אַחֵר שֶׁגִּלָּה. (מהו) זֶה - כְּמוֹ שֶׁנֶּאֱמַר (שמות יב) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים. זֶה נִיסָן וְלֹא אַחֵר.</p>\n<p>זֶה סֵפֶר - לְהִתְבּוֹנֵן וּלְגַלּוֹת תּוֹלְדוֹת אָדָם, עֵץ שֶׁמְּגַלֶּה תּוֹלְדוֹת אָדָם וְעוֹשֶׂה פֵּרוֹת לְהוֹצִיא עוֹלָם. זֶה סֵפֶר - לָדַעַת חָכְמָה נִסְתֶּרֶת וַעֲמֻקָּה, שֶׁנִּמְסְרָה לְאָדָם הָרִאשׁוֹן בִּדְיוֹקָן שֶׁל בְּנֵי אָדָם. חָכְמָה זוֹ נִמְסְרָה לִשְׁלֹמֹה הַמֶּלֶךְ, וְיָרַשׁ אוֹתָהּ וְכָתַב בְּסִפְרוֹ.</p>\n<p>לָמַדְנוּ שֶׁמֹּשֶׁה הִתְקַשָּׁה בָּזֶה, עַד שֶׁבָּאָה שְׁכִינָה וְלִמְּדָה אוֹתוֹ, וְהִיא רָאֲתָה וּבָחֲרָה אֶת כָּל הָאֲנָשִׁים הַלָּלוּ שֶׁנִּרְאִים בְּפַרְצוּף, וְשָׁם מֹשֶׁה לָמַד אֶת הַחָכְמָה הַזּוֹ וְנִכְנַס לְתוֹכָהּ. זֶהוּ שֶׁכָּתוּב וְאַתָּה תֶחֱזֶה מִכָּל הָעָם. הַהוּא שֶׁכָּתוּב בּוֹ (תהלים קב) וְאַתָּה הוּא וּשְׁנוֹתֶיךְ לֹא יִתָּמּוּ. (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. (תהלים ג) וְאַתָּה ה' מָגֵן בַּעֲדִי.</p>\n<p>וְאַתָּה תֶחֱזֶה, וְתִתְבּוֹנֵן בָּזֶה. אַתָּה וְלֹא אַחֵר, לָדָעַת וּלְהִתְבּוֹנֵן בְּשִׁשִּׁים רִבּוֹא. בְּשִׁשָּׁה צְדָדִים יֵשׁ לְהִתְבּוֹנֵן. בַּדְּיוֹקְנָאוֹת שֶׁל בְּנֵי אָדָם, וְלָדַעַת הַחָכְמָה עַל בֻּרְיָהּ. וְאֵלֶּה הֵם בַּשֵּׂעָר, בָּעֵנַיִם, בַּחֹטֶם, בַּשְּׂפָתַיִם, בַּפָּנִים, בַּיָּדַיִם, בְּאוֹתָם שִׂרְטוּטֵי הַיָּדַיִם. וּבְשֵׁשֶׁת הַצְּדָדִים הַלָּלוּ כָּתוּב וְאַתָּה תֶחֱזֶה. ואתה תחזה בשיער,</p>"],[9522011639,"<p>בַּחֹדֶשׁ הַשְּׁלִישִׁי לְצֵאת בְּנֵי יִשְׂרָאֵל וְגוֹ'. שֶׁשּׁוֹלֵט בּוֹ אוֹרִיאֵ\"ל, מְמֻנֶּה גָּדוֹל, וּשְׁלֹשׁ מֵאוֹת וְשִׁשִׁים וְחָמֵשׁ רִבּוֹא מַחֲנוֹת עִמּוֹ כְּחֶשְׁבּוֹן יְמוֹת הַשָּׁנָה, וּלְכֻלָּם יֵשׁ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מַפְתְּחוֹת שֶׁל אוֹרוֹת, מֵאוֹתוֹ הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַחַשְׁמַל הָעֶלְיוֹן הַפְּנִימִי הַגָּנוּז וְהַנִּסְתָּר שֶׁסּוֹדוֹת שֶׁל אוֹתִיּוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ תְּלוּיִים בּוֹ.</p>\n<p>וְהוּא סוֹד שֶׁל אִישׁ תָּם, בַּעַל הַבַּיִת, אִישׁ הָאֱלֹהִים. תָּם - שֶׁשָּׁם סִיּוּם וְקֶשֶׁר שֶׁל תְּפִלִּין. וְיַעֲקֹב הָיָה אִישׁ תָּם, וּבִדְיוֹקְנוֹ עוֹמֵד סוֹד הַחַשְׁמַל הַפְּנִימִי הָעֶלְיוֹן הַטָּמִיר וְהַגָּנוּז. וְכָל הָאוֹרוֹת הַנִּסְתָּרִים הָעֶלְיוֹנִים הוּא לוֹקֵחַ, וְיוֹצְאִים מִמֶּנּוּ, וְכָל הַמַּחֲנוֹת לוֹקְחִים אוֹתָם מַפְתְּחוֹת שֶׁל אוֹתוֹ הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַחַשְׁמַל.</p>\n<p>וְאוֹתוֹ הָאוֹר כָּלוּל בִּשְׁנֵי אוֹרוֹת, וְהֵם אֶחָד. אוֹר רִאשׁוֹן הוּא אוֹר לָבָן שֶׁלֹּא שׁוֹלֶטֶת בּוֹ הָעַיִן, וְזֶהוּ הָאוֹר הַגָּנוּז לַצַּדִּיקִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק וְגוֹ'. אוֹר שֵׁנִי הוּא אוֹר נוֹצֵץ לוֹהֵט כְּצֶבַע אָדם, וְנִכְלְלוּ שְׁנֵי אוֹרוֹת כְּאֶחָד וְהָיוּ אֶחָד.</p>\n<p>וְהָאוֹרִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל הַזֶּה וְכָל אוֹתָם מַחֲנוֹת נוֹטְלִים אוֹתוֹ הָאוֹר, וּמִשּׁוּם שֶׁכָּלוּל בִּשְׁנַיִם נִקְרָא תְּאוֹמִי\"ם. וְעַל זֶה שׁוֹלֵט בּוֹ אוֹתוֹ הַמַּזָּל שֶׁנִּקְרָא בַּסּוֹד שֶׁלּוֹ תְּאוֹמִים, וּבוֹ נִתְּנָה תוֹרָה, וּמִכָּאן נִמְשָׁכוֹת דְּרָגוֹת לְמַטָּה, עַד שֶׁעוֹלִים בְּשֵׁמוֹת (להנהיג) לְהָאִיר אֶת הָעוֹלָם.</p>\n<p>לְכָל שְׁאָר הַמַּזָּלוֹת אֵין לָהֶם פֶּה וְלָשׁוֹן, וְלָזֶה יֵשׁ פֶּה וְלָשׁוֹן כְּלוּלִים כְּאֶחָד, וְעַל זֶה בַּתּוֹרָה, (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה כָּתוּב. יוֹמָם - כְּנֶגֶד לָשׁוֹן. לַיְלָה - כְּנֶגֶד פֶּה. וְהַכֹּל כָּלוּל כְּאֶחָד, וּבַכֹּל עוֹלֶה תְּאוֹמִים.</p>\n<p>תוֹמִים כָּתוּב, וְעַל סוֹד זֶה כָּתוּב תוֹמִים, (בראשית כה) וְהִנֵּה תוֹמִם בְּבִטְנָהּ. אִם תֹּאמַר שֶׁבִּשְׁבִיל שְׁנֵיהֶם הוּא אָמַר - לֹא כָּךְ, שֶׁהֲרֵי עֵשָׂו לֹא עָלָה בְּסוֹד זֶה. אֶלָּא בִּשְׁבִיל יַעֲקֹב הוּא אָמַר, וְשֶׁבַח זֶה שֶׁהָיָה בְּמֵעֶיהָ שֶׁל אוֹתָהּ הַצַּדֶּקֶת מְשַׁבֵּחַ הַכָּתוּב. וּמִשּׁוּם שֶׁהָיָה שָׁם אוֹתוֹ רָשָׁע, הִסְתַּלֵּק מִשָּׁם אָלֶף.</p>\n<p>וְהַסֹל סוֹד אֶחָד. יַעֲקֹב נָטַל בַּסּוֹד שֶׁלּוֹ שְׁנֵי חֳדָשִׁים - נִיסָ\"ן וְאִיָּ\"ר, וְהוּא נִכְלָל בַּסּוֹד שֶׁל סִיוָן שֶׁהוּא תְאוֹמִים. עֵשָׂו נָטַל בַּסּוֹד שֶׁלּוֹ שְׁנֵי חֳדָשִׁים - תַּמּוּ\"ז וְאָ\"ב, וְהוּא לֹא נִמְצָא וְנֶאֱבָד, שֶׁהֲרֵי אֱלוּ\"ל אֵינוֹ שֶׁלּוֹ, וַאֲפִלּוּ בְּאָב תִּשְׁעָה יָמִים הֵם שֶׁלּוֹ וְלֹא יוֹתֵר, וְנֶאֱבָד וְלֹא נִמְצָא, וְאֵינוֹ בַּסּוֹד שֶׁל תְּאוֹמִים, אֶלָּא נִפְרַד לְבַדּוֹ וְסָטָה לְצַד אַחֵר בְּאֶפֶס וּשְׁמָמָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ט) הָאוֹיֵב תַּמּוּ חֳרָבוֹת לָנֶצַח.</p>\n<p>וּמִשּׁוּם שֶׁיַּעֲקֹב הוּא תְאוֹמִים, נִתְּנָה תוֹרָה לְבָנָיו בְּחֹדֶשׁ תְּאוֹמִים, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, בַּחֹדֶשׁ הַשְּׁלִישִׁי, לָעָם הַשְּׁלִישִׁי, בִּדְרָגוֹת שְׁלִישִׁיּוֹת, תּוֹרָה מְשֻׁלֶּשֶׁת - תּוֹרָה נְבִיאִים וּכְתוּבִים. וְהַכֹּל אֶחָד.</p>\n<p>בַּחֹדֶשׁ הַשְּׁלִישִׁי וְגוֹ'. פָּרָשָׁה זוֹ בְּפָסוּק זֶה פֵּרְשׁוּ אוֹתָהּ לְמַעְלָה. שָׁנָה רַבִּי חִיָּיא, בְּאוֹתוֹ זְמַן שֶׁהִגִּיעוּ יִשְׂרָאֵל לְהַר סִינַי, כִּנֵּס אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת זֶרַע יִשְׂרָאֵל וְהִשְׁגִּיחַ בָּהֶם בְּכֻלָּם, וְלֹא מָצָא בְּכָל זֶרַע יִשְׂרָאֵל פְּסוּל, אֶלָּא כֻּלָּם זֶרַע קֹדֶשׁ, כֻּלָּם בְּנֵי אֱמֶת.</p>\n<p>בְּאוֹתוֹ זְמַן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: עַכְשָׁו אֲנִי רוֹצֶה לָתֵת תּוֹרָה לְיִשְׂרָאֵל, מְשֹׁךְ אוֹתָם בְּאַהֲבָה שֶׁל אָבוֹת, בָּאַהֲבָה שֶׁאֲנִי אוֹהֵב אוֹתָם וּבָאוֹתוֹת שֶׁעָשִׂיתִי לָהֶם, וְאַתָּה תִּהְיֶה לִי שָׁלִיחַ וְהָשֵׁב הַדְּבָרִים הַלָּלוּ. אָמַר רַבִּי יוֹסֵי אָמַר רַבִּי יְהוּדָה, כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: בְּדָבָר זֶה תִּהְיֶה לִי שָׁלִיחַ נֶאֱמָן לִמְשֹׁךְ אֶת יִשְׂרָאֵל אַחֲרַי.</p>"],[9522011640,"<p>וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים וַיִּקְרָא אֵלָיו ה' מִן הָהָר וְגוֹ'. וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים - לַמָּקוֹם שֶׁפְּרוּשׂוֹת כַּנְפֵי הַשְּׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר (שם יח) וַיֵּט שָׁמַיִם וַיֵּרַד וְגוֹ'.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה, כָּל זְמַן שֶׁחֲקִיקוֹת הַמֶּלֶךְ הָעֶלְיוֹן מִתְיַשְּׁרוֹת בִּמְקוֹמָן, כָּל הָעוֹלָמוֹת בְּשִׂמְחָה וְכָל הַמַּעֲשִׂים מִתְיַשְּׁרִים עַל קִיּוּמָם, (מי כל המעשים המתישרים על קיומם) כְּמוֹ שֶׁנֶּאֱמַר (שמות לד) אֶת מַעֲשֵׂה ה' כִּי נוֹרָא הוּא. מַה זֶּה כִּי נוֹרָא הוּא? אָמַר רַבִּי אֶלְעָזָר, שְׁלֵמוּת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברים י) הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא. מַה זֶּה וְהַנּוֹרָא? זֶה יַעֲקֹב. וְכָתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם, כְּתַרְגּוּמוֹ - אָדָם שָׁלֵם. שָׁלֵם בַּכֹּל. כָּךְ כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלֵמִים בִּשְׁלֵמוּת בְּקִיּוּם שָׁלֵם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, יוֹם אֶחָד הָיִיתִי עוֹמֵד לִפְנֵי רַבִּי יְהוּדָה הַזָּקֵן וְשָׁאַלְתִּי אוֹתוֹ עַל מַה שֶּׁכָּתוּב (שם כח) וַיִּירָא וַיֹּאמַר מַה נּוֹרָא וְגוֹ'. מָה רָאָה שֶׁאָמַר שֶׁהוּא נוֹרָא? אָמַר לִי, רָאָה שְׁלֵמוּת הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהָיְתָה מְצוּיָה בְּאוֹתוֹ מָקוֹם כְּמוֹ שֶׁלְּמַעְלָה, וּבְכָל מָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת נִקְרָא נוֹרָא.</p>\n<p>אָמַרְתִּי לוֹ, אִם כָּךְ, לָמָּה תַּרְגּוּמוֹ פַּחַד וְלֹא שָׁלֵם? אָמַר לִי, אֵין פַּחַד אֶלָּא בְּמָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת, וּבְכָל מָקוֹם שֶׁמְּצוּיָה שְׁלֵמוּת נִקְרָא נוֹרָא, שֶׁכָּתוּב (תהליםלד) יְראוּ אֶת ה' קְדשָׁיו כִּי אֵין מַחְסוֹר לִירֵאָיו. מִמַּשְׁמָע שֶׁאָמַר כִּי אֵין מַחְסוֹר - בְּמָקוֹם שֶׁאֵין מַחְסוֹר מְצוּיָה שְׁלֵמוּת.</p>\n<p>שָׁנִינוּ, מִי עָלָה שָׁמַיִם וַיֵּרַד - אָמַר רַבִּי יוֹסֵי, זֶהוּ מֹשֶׁה, שֶׁכָּתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. מִי אָסַף רוּחַ בְּחָפְנָיו - זֶהוּ אַהֲרֹן, שֶׁכָּתוּב (ויקרא טז) וּמְלֹא חָפְנָיו קְטֹרֶת סַמִּים דַּקָּה. מִי צָרַר מַיִם בַּשִּׂמְלָה - זֶה אֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְבָרִי. מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶהוּ אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. אַל תִּקְרֵי בְּהִבָּרְאָם, אֶלָּא בְּאַבְרָהָם.</p>\n<p>הוּא שָׁנָה אֶת זֶה, וְהוּא אָמַר. מִי עָלָה שָׁמַיִם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (תהלים מז) עָלָה אֱלֹהִים בִּתְרוּעָה. (מיעלה, תקוןבסודאת האור. אמנם בתרועה. וירד, בסוד ויבדל. הבדילו לו אלהים בתרועה) מִי אָסַף רוּחַ בְּחָפְנָיו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (איוב יב) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְגוֹ'. מִי צָרַר מַיִם בַּשִּׂמְלָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (שם כו) צוֹרֵר מַיִם בְּעָבָיו. מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמַיִם. עוֹד אָמַר, מִי עָלָה שָׁמַיִם וַיֵּרַד וְגוֹ' - אֵלֶּה אוֹתָם אַרְבָּעָה קִשְׁרֵי הָעוֹלָם - אֵשׁ, רוּחַ, מַיִם וְעָפָר.</p>\n<p>אָמַר רַבִּי יֵיסָא, נִרְאִים דִּבְרֵי רַבִּי יוֹסֵי שֶׁלֹּא מִתְקַיְּמִים. כְּשֶׁהִגִּיעוּ הַדְּבָרִים הַלָּלוּ אֶל רַבִּי שִׁמְעוֹן, הִנִּיחַ יָדוֹ בְּרֹאשׁוֹ שֶׁל רַבִּי יוֹסֵי וּבֵרְכוֹ, וְאָמַר, יָפֶה אָמַרְתָּ וְכָךְ זֶה. אָמַר לוֹ, מִנַּיִן לְךְ? אָמַר לוֹ, כָּךְ לָמַדְתִּי מֵאָבִי שֶׁהָיָה אוֹמֵר מִשְּׁמוֹ שֶׁל רַב הַמְנוּנָא סָבָא.</p>\n<p>יוֹם אֶחָד הָיָה יוֹשֵׁב רַבִּי שִׁמְעוֹן בַּשַּׁעַר שֶׁל צִפּוֹרִי. אָמַר לוֹ רַבִּי יֵיסָא, זֶה שֶׁאָמַר רַבִּי יוֹסֵי מִי עָלָה שָׁמַיִם וַיֵּרַד - פַּעַם אַחַת אָמַר זֶה מֹשֶׁה, אַחַר כָּךְ אָמַר זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, אַחַר כָּךְ אָמַר אֵלּוּ אַרְבָּעָה קְשָׁרִים, אֵשׁ רוּחַ מַיִם וְעָפָר, וְרָאִיתִי שֶׁמּוֹרֵנוּ בֵּרְכוֹ?</p>\n<p>אָמַר לוֹ, וַדַּאי שֶׁיָּפֶה אָמַר, וְכָךְ הוּא, וְהַכֹּל דָּבָר אֶחָד, וְכָל הַדְּבָרִים הִתְקַיְּמוּ בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, וְכֻלָּם עוֹלִים בְּמִשְׁקָל אֶחָד. הִתְרַגֵּשׁ רַבִּי יֵיסָא בְּדִבְרֵי רַבִּי שִׁמְעוֹן וְאָמַר, וַדַּאי כָּךְ זֶה, וְכָךְ לָמַדְנוּ מִשֵּׁם מוֹרֵנוּ בְּפַעַם אַחֶרֶת. וְהַכֹּל יָפֶה. (אלה תולדות השמים והארץ בהבראם, אל תקרי בהבראם אלא באברהם, שכתוב (תהלים פט) כי אמרתי עולם חסד יבנה. אבל)</p>\n<p>אֲבָל סוֹף הַכָּתוּב מַהוּ אוֹמֵר? שֶׁכָּתוּב מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. מַה שְּׁמוֹ מֵילָא, מַה זֶה מַה שֶּׁם בְּנוֹ? אָמַר לוֹ, סוֹד הַדָּבָר הֲרֵי לִמַּדְתִּי לְרַבִּי אֶלְעָזָר בְּנִי. אָמַר לוֹ, יֹאמַר לוֹ מוֹרִי, שֶׁהֲרֵי בַּחֲלוֹמִי שָׁאַלְתִּי לִפְנֵי מוֹרִי דָּבָר זֶה, וְאָמַר לִי וְשָׁכַחְתִּי אוֹתוֹ. אָמַר לוֹ, אִם אֹמַר - תִּזְכֹּר? אָמַר לוֹ, וַדַּאי, שֶׁהֲרֵי מַה שֶּׁלָּמַדְתִּי לִפְנֵי מוֹרִי, יוֹם זֶה נִזְכַּרְתִּי.</p>\n<p>אָמַר לוֹ, סוֹד הַדָּבָר - הַיְנוּ שֶׁכָּתוּב (שמות ו) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. וּבְסוֹד עֶלְיוֹן, וְזֶה נִקְרָא בְנוֹ. אָמַר, תָּנוּחַ דַּעְתוֹ שֶׁל מוֹרִי, שֶׁהֲרֵי סוֹד זֶה יָדַעְתִי. בֵּין כָּךְ לֹא נִזְכַּר רַבִּי יֵיסָא, חָלְשָׁה דַעְתּוֹ וְהָלַךְ לְבֵיתוֹ. נִרְדַּם. הֶרְאוּ לוֹ בַּחֲלוֹם סֵפֶר אַגָּדָה אֶחָד שֶׁהָיָה כָּתוּב בּוֹ חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ.</p>\n<p>הִתְעוֹרֵר וְהָלַךְ אֶל רַבִּי שִׁמְעוֹן. נָשַׁק יָדוֹ וְאָמַר, כָּךְ רָאִיתִי בַּחֲלוֹם. פַּעַם אַחֶרֶת רָאִיתִי בַּחֲלוֹם סֵפֶר אַגָּדָה אֶחָד שֶׁהֶרְאוּ לְפָנַי, וְהָיָה כָּתוּב בּוֹ חָכְמָה וְתִפְאֶרֶת בְּמִקְדָּשׁוֹ, חָכְמָה לְמַעְלָה, תִּפְאֶרֶת לְמַטָּה, בְּמִקְדָּשׁוֹ אֲלֵיהֶם. וְכָךְ רָאִיתִי בַּחֲלוֹם פַּעַם אַחַת וְכָךְ מָצָאתִי בְּפִי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, עַד עַכְשָׁו אַתָּה תִינוֹק לְהִכָּנֵס בֵּין קוֹצְרֵי הַשָּׂדֶה, וַהֲרֵי הַכֹּל הֶרְאוּ לְךְ. וְזֶהוּ שֶׁכָּתוּב מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. חָכְמָה שְׁמוֹ, תִּפְאֶרֶת בְּנוֹ.</p>\n<p>וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁזָּכָה לְכָבוֹד זֶה שֶׁהַתּוֹרָה הֵעִידָה בִּשְׁבִילוֹ כָּךְ. (שנה רבי יהודה) בֹּא וּרְאֵה מַה בֵּין מֹשֶׁה לִשְׁאָר בְּנֵי הָעוֹלָם. שְׁאָר בְּנֵי הָעוֹלָם, כְּשֶׁעוֹלִים - עוֹלִים לְעֹשֶׁר, עוֹלִים לִגְדֻלָּה, עוֹלִים לְמַלְכוּת. אֲבָל בְּמֹשֶׁה, כְּשֶׁעוֹלֶה, מַה כָּתוּב? וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. אַשְׁרֵי חֶלְקוֹ!</p>\n<p>רַבִּי יוֹסֵי אָמַר, מִכָּאן אָמְרוּ הַחֲבֵרִים, הַבָּא לִטָּהֵר מְסַיְּעִין אוֹתוֹ, שֶׁכָּתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים. מַה כָּתוּב אַחֲרָיו? וַיִּקְרָא אֵלָיו ה'. שֶׁמִּי שֶׁרוֹצֶה לְהִתְקָרֵב, מְקָרְבִים אוֹתוֹ.</p>"],[9522011641,"<p>וַיִּקְרָא אֵלָיו מַלְאַךְ ה' מִן הָהָר לֵאמֹר כֹּה תֹאמַר לְבֵית יַעֲקֹב וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בּוֹ וְקֵרַב אוֹתוֹ לִשְׁרוֹת בְּתוֹךְ הַהֵיכָל הַקָּדוֹשׁ, שֶׁכָּל מִי שֶׁהוּא הִתְרַצָּה בּוֹ לַעֲבוֹדָתוֹ, רָשׁוּם הוּא מֵרִשּׁוּמִים שֶׁלְּמַעְלָה לָדַעַת, שֶׁהֲרֵי הוּא נִבְחָר מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן לִשְׁרוֹת בִּמְדוֹרוֹ, וְכָל מִי שֶׁנִּמְצָא בּוֹ אוֹתוֹ הָרֹשֶׁם, עוֹבֵר בְּכָל הַשְּׁעָרִים שֶׁלְּמַעְלָה וְאֵין מוֹחֶה בְּיָדוֹ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁעָלָיו כָּתוּב אַשְׁרֵי תִּבְחַר וּתְקָרֵב, וְכָתוּב (שמותב) וּמֹשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל, (שם כד) וְנִגַּשׁ מֹשֶׁה לְבַדּוֹ אֶל ה' וְהֵם לֹא יִגָּשׁוּ. כֹּה תֹאמַר לְבֵית יַעֲקֹב - אֵלּוּ הַנְּקֵבוֹת. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל - אֵלּוּ הַזְּכָרִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כֹּה תֹאמַר, כְּמוֹ שֶׁנֶּאֱמַר כֹּה תְבָרֲכוּ. וְכָתוּב וַחֲסִידֶיךְ יְבָרֲכוּכָה, כְּלוֹמַר יְבָרְכוּ כֹה. כֹּה תֹאמַר לְבֵית יַעֲקֹב - בַּאֲמִירָה, וְהַיְנוּ מִצַּד הַדִּין. וְתַגֵּיד לְבֵית יִשְׂרָאֵל - כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ. וְכָתוּב (שם כו) הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ. לִבְנֵי יִשְׂרָאֵל - הַזְּכָרִים, שֶׁבָּאוּ מִצַּד הָרַחֲמִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, הוֹאִיל וּבָאנוּ לָזֶה, מַה זֶּה הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ? לַה' אֱלֹהֵינוּ הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ רַבִּי שִׁמְעוֹן, וְכִי רַק בִּלְבַדּוֹ הוּא, וַהֲרֵי כָּתוּב (שם ח) כִּי ה' אֱלֹהֶיךְ מְבִיאֲךְ אֶל אֶרֶץ טוֹבָה וְגוֹ', (שם) אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ, (שם ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא, וְכֻלָּם כָּךְ?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַדָּר בְּאֶרֶץ יִשְׂרָאֵל דּוֹמֶה כְּמִי שֶׁיֵּשׁ לוֹ אֱלוֹהַּ, וְכָל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַזֶּרַע הַקָּדוֹשׁ עוֹלֶה לָאָרֶץ הַקְּדוֹשָׁה, וּשְׁכִינָה יוֹשֶׁבֶת בִּמְקוֹמָהּ, וְזֶה בָּזֶה תָּלוּי. וּמֹשֶׁה לֹא אָמַר אֱלֹהֶיךְ אֶלָּא לְאוֹתָם שֶׁהָיוּ עֲתִידִים לְהִכָּנֵס לָאָרֶץ הַקְּדוֹשָּׁה וּלְקַבֵּל פְּנֵי שְׁכִינָה. וּמַה שֶּׁלֹּא אָמַר אֱלֹהֵינוּ, מִשּׁוּם שֶׁהֲרֵי מֹשֶׁה לֹא זָכָה לְהִכָּנֵס לָאָרֶץ, וְלָכֵן אֱלֹהֶיךְ וַדַּאי בְּכָל מָקוֹם, מִשּׁוּם שֶׁהֵם הָיוּ עֲתִידִים לְהִכָּנֵס לְשָׁם.</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ הוּא. אֲבָל כָּאן כָּתוּב (שם כו) וּבָאתָ אֶל הַכֹּהֵן אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם וְאָמַרְתָּ אֵלָיו הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ, וַהֲרֵי הֵם בָּאָרֶץ שׁוֹרִים. מָה הַטַּעַם אֱלֹהֶיךְ וְלֹא אֱלֹהֵינוּ? אֶלָּא הֵם רָצוּ לְהַרְאוֹת וּלְהוֹדוֹת שֶׁבִּגְלַל הַחֶסֶד הָעֶלְיוֹן זָכוּ לְכָל זֶה וְשָׁרוּ בָאָרֶץ וְנִכְנָסִים לְאוֹתָהּ אֶרֶץ וְעָשָׂה עִמָּהֶם כָּל אוֹתָן טוֹבוֹת, וּמִשּׁוּם כָּךְ הָיוּ אוֹמְרִים דְּבָרִים אֵלֶּה לַכֹּהֵן (ולא לאדם אחר), שֶׁכָּתוּב הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךְ, (וכך הוא ודאי) מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד.</p>\n<p>כֹּה תֹאמַר לְבֵית יַעֲקֹב - לְאוֹתוֹ מָקוֹם שֶׁרָאוּי לָהֶם. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל - בְּאוֹתוֹ מָקוֹם שָׁלֵם שֶׁרָאוּי לָהֶם, שֶׁהֲרֵי יַעֲקֹב וְיִשְׂרָאֵל שְׁתֵּי דְרָגוֹת עָלוּ, וּבְדַרְגָּה אַחַת עוֹלִים. אֶלָּא יִשְׂרָאֵל שְׁלֵמוּת הַכֹּל נִקְרָא. וְתַגֵּיד לִבְנֵי יִשְׂרָאֵל, לְהַרְאוֹת חָכְמָה וּלְדַבֵּר בְּרוּחַ חָכְמָה טוֹב וֶאֱמֶת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וַיַּגֵּד לָכֶם אֶת בְּרִיתוֹ.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, פַּעַם אַחַת הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וְהָיָה עִמִּי רַבִּי חִיָּיא בְּנִי. עַד שֶׁהָיִינוּ הוֹלְכִים, מָצָאתִי אִישׁ אֶחָד שֶׁהָיָה לוֹקֵט בַּשָּׂדֶה עֲשָׂבִים לִרְפוּאָה. קָרַבְתִּי אֵלָיו וְאָמַרְתִּי לוֹ: בֶּן אָדָם, כָּל הָאֲגֻדּוֹת הַקְּשׁוּרוֹת הַלָּלוּ שֶׁל הָעֲשָׂבִים לָמָּה? לֹא הֵרִים רֹאשׁוֹ וְלֹא אָמַר דָּבָר. חָזַרְתִּי פַּעַם נוֹסֶפֶת וְאָמַרְתִּי אֶת זֶה - וְלֹא אָמַר דָּבָר. אָמַרְתִּי לְרַבִּי חִיָּיא בְּנִי: אוֹ שֶׁהָאִישׁ הַזֶּה אָזְנָיו אֲטוּמוֹת, אוֹ שׁוֹטֶה, אוֹ חָכָם. יָשַׁבְתִּי אֶצְלוֹ. אַחַר כָּךְ לִקֵּט אוֹתָם עֲשָׂבִים, וְאָחַז אוֹתָם וְכִסָּה עֲלֵיהֶם בַּעֲלֵי גֶפֶן.</p>\n<p>אֲנִי רָאִיתִי שֶׁאַתֶּם יְהוּדִים, וְעַל הַיְּהוּדִים אוֹמְרִים שֶׁהֵם חֲכָמִים. אִם לֹא הָיִיתִי חָס עֲלֵיכֶם, עַכְשָׁו תִּהִיוּ מְרֻחָקִים מִבְּנֵי אָדָם כְּמוֹ הַמְּצֹרָע הַזֶּה שֶׁמַּרְחִיקִים אוֹתוֹ מֵהַכֹּל, שֶׁהֲרֵי אֲנִי רוֹאֶה שֶׁרֵיחַ שֶׁל עֵשֶׂב אֶחָד שֶׁהָיָה קָרוֹב אֲלֵיכֶם נִכְנַס בְּגוּפְכֶם, וְתִהְיוּ מְרֻחָקִים שְׁלֹשָׁה יָמִים, אֶלָּא אִכְלוּ שׁוּמֵי הַבָּר הַלָּלוּ וְתִתְרַפְּאוּ.</p>\n<p>אָכַלְנוּ מֵהֶם, שֶׁהָיוּ מְצוּיִים שָׁם, וְנִרְדַּמְנוּ וְנִקְשַׁרְנוּ בְּזֵעָה עַד זְמַן רַב. אַחַר כָּךְ הִתְעוֹרַרְנוּ. אָמַר לָנוּ אוֹתוֹ הָאִישׁ: עַכְשָׁו אֱלֹהֵיכֶם עִמָּכֶם שֶׁמְּצָאתֶם אוֹתִי, שֶׁהֲרֵי רְפוּאַת גּוּפְכֶם עַל יָדִי נִשְׁלְמָה.</p>\n<p>עַד שֶׁהָיִינוּ הוֹלְכִים, אָמַר לָנוּ: כָּל אָדָם צָרִיךְ לְדַבֵּר עִם אָדָם אַחֵר כְּפִי דְרָכָיו. שֶׁהֲרֵי לַנְּקֵבָה כְּפִי דַרְכָּהּ, לָאִישׁ כְּפִי דְרָכָיו, וְלַגֶּבֶר שֶׁבַּגְּבָרִים כְּפִי דְרָכָיו. אָמַרְתִּי לְרַבִּי חִיָּיא בְּנִי, זֶהוּ שֶׁכָּתוּב כֹּה תֹאמַר לְבֵית יַעֲקֹב וְתַגֵּיד לְבֵית יִשְׂרָאֵל. (כה תאמר לבית יעקב, באותו מקום שראוי להם. ותגיד ותגיד לבני ישראל, באותו מקוםשלםשראוילהם, שהרייעקבוישראלשתי דרגות הם ובדרגה אחת עולים, אלא ישראל שלמות הכל נקרא).</p>\n<p>רְאִיתֶם שֶׁלֹּא הֵרַמְתִּי רֹאשִׁי וְלֹא דִבַּרְתִּי עִמָּכֶם, מִשּׁוּם שֶׁאָבִי הָיָה חֲכַם הָעֲשָׂבִים מִכָּל בְּנֵי דוֹרוֹ, וְלָמַדְתִּי מֵאָבִי דַּרְכֵי כָּל הָעֲשָׂבִים שֶׁבָּהֶם אֱמֶת, וַאֲנִי בְּכָל הַשָּׁנָה מְדוֹרִי בֵּינֵיהֶם.</p>\n<p>וְהָעֵשֶׂב הַזֶּה שֶׁרְאִיתֶם שֶׁכִּסִּיתִי אוֹתוֹ בַּעֲלֵי הַגֶּפֶן הַלָּלוּ - בְּבֵיתִי יֵשׁ מָקוֹם אֶחָד, וְהוּא לְצַד צָפוֹן, וּבְאוֹתוֹ מָקוֹם נָעוּץ רֵחַיִם אֶחָד, וּמֵהָעַיִן שֶׁל אוֹתוֹ רֵחַיִם יוֹצֵא אִישׁ אֶחָד עִם שְׁנֵי רָאשִׁים וְחֶרֶב שְׁנוּנָה בְיָדוֹ, וּבְכָל יוֹם הוּא מְצַעֵר אוֹתָנוּ, וַאֲנִי לִקַּטְתִּי אֶת הָעֵשֶׂב הַזֶּה, וּלְכוּ אַחֲרַי וְתִרְאוּ אֶת כֹּחוֹ שֶׁל הָעֵשֶׂב הַזֶּה וּמַה שֶּׁאֱלוֹהַּ הָעֶלְיוֹן גִּלָּה בָּעוֹלָם, וְאֵין מִי שֶׁיּוֹדֵעַ דְּרָכָיו בַּכֹּל.</p>\n<p>הָלַכְנוּ אַחֲרָיו. עַד שֶׁהָיִינוּ הוֹלְכִים בַּדֶּרֶךְ, הִתְכּוֹפֵף לְנֶקֶב אֶחָד בֶּעָפָר, וְשָׂם מֵאוֹתוֹ הָעֵשֶׂב בַּנֶּקֶב. יָצָא נָחָשׁ אֶחָד וְרֹאשׁוֹ גָּדוֹל. לָקַח חֶבֶל (סודר) אֶחָד וְקָשַׁר אוֹתוֹ כְּמוֹ גְדִי אֶחָד. פָּחַדְנוּ. אָמַר לָנוּ: לְכוּ אַחֲרַי.</p>\n<p>עֵד שֶׁהִגַּעְנוּ לְבֵיתוֹ, רָאִינוּ אוֹתוֹ מָקוֹם בַּחֲשֵׁכָה אַחַר כֹּתֶל אֶחָד. לָקַח נֵר אֶחָד וְהִדְלִיק אֵשׁ סְבִיב אוֹתוֹ מְקוֹם הָרֵחַיִם. אָמַר לָנוּ: מִמַּה שֶּׁתִּרְאוּ - לֹא תִפְחֲדוּ וְלֹא תְדַבְּרוּ דָבָר.</p>\n<p>בֵּין כָּךְ הִתִּיר אֶת הַנָּחָשׁ מִקְּשָׁרָיו, וְכָתַשׁ בְּמַכְתֶּשֶׁת מֵאוֹתוֹ הָעֵשֶׂב וְשָׂם בְּרֹאשׁ הַנָּחָשׁ. נִכְנַס הַנָּחָשׁ בְּאוֹתוֹ עֵין הָרֵחַיִם, וְשָׁמַעְנוּ קוֹל שֶׁכָּל הַמָּקוֹם הִזְדַּעֲזַע. רָצִינוּ לָצֵאת, אָחַז בְּיָדֵינוּ אוֹתוֹ הָאִישׁ וְאָמַר: אַל תִּפְחֲדוּ, קִרְבוּ אֵלַי.</p>\n<p>בֵּין כָּךְ יָצָא הַנָּחָשׁ שׁוֹתֵת דָּם. לָקַח אוֹתוֹ הָאִישׁ מֵאוֹתוֹ הָעֵשֶׂב וְשָׂם בְּרֹאשׁוֹ כְּבַתְּחִלָּה. נִכְנַס לְאוֹתוֹ עֵין הָרֵחַיִם. לְשָׁעָה קְטַנָּה רָאִינוּ שֶׁיָּצָא מֵאוֹתוֹ הָעַיִן אִישׁ אֶחָד עִם שְׁנֵי רָאשִׁים וְנָחָשׁ שָׁרוּי סְבִיב צַוָּארוֹ. נִכְנַס לְאוֹתוֹ עֵין הָרֵחַיִם וְיָצָא שָׁלֹשׁ פְּעָמִים. וְהוּא אָמַר: זְקִיטָא זְקִיטָא (מין שרץ) ! אוֹי לְאִמּוֹ שֶׁהוֹבִילָה אוֹתוֹ לְאוֹתוֹ מָקוֹם!</p>\n<p>בֵּין כָּךְ נֶעֱקַר הָרֵחַיִם מִמְּקוֹמוֹ, וְיָצְאוּ הָאִישׁ וְהַנָּחָשׁ, וְנָפְלוּ וּמֵתוּ שְׁנֵיהֶם. וְאָנוּ פָּחַדְנוּ מְאֹד. אָמַר לָנוּ אוֹתוֹ הָאִישׁ: זֶהוּ כֹּחוֹ שֶׁל אוֹתוֹ עֵשֶׂב שֶׁאֲנִי לָקַטְתִּי לִפְנֵיכֶם, וְלָכֵן לֹא דִבַּרְתִּי עִמָּכֶם וְלֹא הֵרַמְתִּי רֹאשִׁי בְּשָׁעָה שֶׁקְּרַבְתֶּם אֵלַי.</p>\n<p>אִלּוּ יָדְעוּ בְּנֵי אָדָם חָכְמָה, שֶׁכָּל מַה שֶּׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ וְכֹחַ כָּל מַה שֶּׁנִּמְצָא בָּעוֹלָם, יָדְעוּ אֶת כֹּחַ רִבּוֹנָם בְּחָכְמָתוֹ הָרַבָּה. אֲבָל לֹא הִסְתִּיר הַקָּדוֹשׁ בָּרוּךְ הוּא חָכְמָה זוֹ מִבְּנֵי אָדָם, אֶלָּא כְּדֵי שֶׁלֹּא יִסְטוּ מִדְּרָכָיו וְלֹא יִבְטְחוּ בְּאוֹתָהּ חָכְמָה וְיִשְׁכְּחוּ אוֹתוֹ.</p>\n<p>כְּשֶׁבָּאתִי וְאָמַרְתִּי אֶת הַדְּבָרִים הַלָּלוּ לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר, וַדַּאי שֶׁחָכָם הָיָה. וּבֹא רְאֵה, אֵין עֵשֶׂב וְעֵשֶׂב שֶׁנּוֹלַד בָּאָרֶץ שֶׁלֹּא הָיְתָה בּוֹ חָכְמָה רַבָּה וְכֹחוֹ בַּשָּׁמַיִם רַב. בּא וּרְאֵה מִן הָאֵזוֹב, שֶׁבְּכָל מָקוֹם שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת הָאָדָם, הוּא נִטְהָר בְּאֵזוֹב. מָה הַטַּעַם? מִשּׁוּם שֶׁיִּתְעוֹרֵר כֹּחוֹ שֶׁלְּמַעְלָה שֶׁנִּפְקָד עָלָיו, שֶׁהֲרֵי כְּשֶׁמִּתְעוֹרֵר אוֹתוֹ הַכֹּחַ שֶׁנִּפְקָד עָלָיו, הוּא מְבַעֵר רוּחַ הַטֻּמְאָה וְנִטְהָר הָאָדָם. וְעָלֶיךְ אֲנִי אוֹמֵר, בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילְךְ!</p>"],[9522011642,"<p>אַתֶּם רְאִיתֶם אֲשֶׁר עָשִׂיתִי לְמִצְרָיִם וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים. מַה זֶּה כַּנְפֵי יְשָׁרִים? אָמַר רַבִּי יְהוּדָה, בְּרַחֲמִים, שֶׁכָּתוּב (דבריםלב) כְּנֶשֶׁר יָעִיר קִנּוֹ וְגוֹ'. וְהַיְנוּ סוֹד הַכָּתוּב שֶׁאָמַר רַבִּי שִׁמְעוֹן, דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. מַה זֶּה בַּשָּׁמַיִם? בְּרַחֲמִים. מָה הַנֶּשֶׁר נִמְצָא בְרַחֲמִים עַל בָּנָיו וְדִין לַאֲחֵרִים - כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְרַחֲמִים לְיִשְׂרָאֵל, וּבְדִין אֶל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ מִקַּפּוּטְקִיָּא לְלוֹד, וְהָיוּ הוֹלְכִים עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. קָמוּ בָאוֹר, כְּשֶׁהֵאִיר הַיּוֹם, וְהָיוּ הוֹלְכִים. אָמַר רַבִּי חִיָּיא, רָאִיתִי אֶת הַפָּסוּק הַזֶּה שֶׁכָּתוּב (יחזקאל א) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. הֲרֵי אַרְיֵה בְּיָמִין, שׁוֹר מִשְּׂמֹאל. נֶשֶׁר בְּאֵיזֶה מָקוֹם מְקוֹמוֹ?</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, בַּמָּקוֹם (שיעקב) שֶׁהַיּוֹנֵק שָׁרוּי. מָה הַטַּעַם? מִשּׁוּם שֶׁנֶּשֶׁר נִמְצָא בַּכֹּל - רַחֲמִים לְבָנָיו, וְדִין אֶל אֲחֵרִים. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא - מוֹבִיל אֶת יִשְׂרָאֵל בְּרַחֲמִים, וּבְדִין אֶל אֲחֵרִים, שֶׁכָּתוּב וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, וְכָתוּב כְּנֶשֶׁר יָעִיר קִנּוֹ.</p>\n<p>מִנַּיִן לָנוּ שֶׁנֶּשֶׁר נִקְרָא רַחֲמִים? שֶׁכָּתוּב (משלי ל) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בַּשָּׁמַיִם מַמָּשׁ. וְלָכֵן אַרְיֵה לְיָמִין, שׁוֹר לִשְׂמֹאל, נֶשֶׁר בֵּינֵיהֶם, וְאוֹחֵז אוֹתָם. אָדָם כּוֹלֵל אֶת כֻּלָּם, וְהַכֹּל נִכְלְלוּ בוֹ, שֶׁכָּתוּב וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה.</p>"],[9522011643,"<p>וַיְהִי בַיּוֹם הַשְּׁלִישִׁי וְגוֹ'. רַבִּי אַבָּא פָּתַח, (שיר ח) אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ בַּיּוֹם שֶׁיְּדֻבַּר בָּהּ. אָחוֹת לָנוּ קְטַנָּה - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת אָחוֹת לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְשָׁדַיִם אֵין לָהּ - הַיְנוּ שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לְהַר סִינַי, לֹא הָיָה בָּהֶם זְכֻיּוֹת וּמַעֲשִׂים טוֹבִים לְהָגֵן עֲלֵיהֶם, שֶׁכָּתוּב וְשָׁדַיִם אֵין לָהּ, שֶׁהֲרֵי הֵם הַתִּקּוּן וְהַיֹּפִי שֶׁל הָאִשָּׁה, וְאֵין יֹפִי שֶׁל אִשָּׁה אֶלָּא הֵם. מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ - מַה יַּעֲשֶׂה מִמֶּנָּה בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְגַּלֶּה בְּהַר סִינַי לְדַבֵּר אֶת דִּבְרֵי הַתּוֹרָה וְתִפְרַח מֵהֶם נִשְׁמָתָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בְּאוֹתָהּ שָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לְהַר סִינַי בְּאוֹתוֹ לַיְלָה וְנִשְׁלְמוּ, שְׁלֹשָׁה יָמִים שֶׁלֹּא הִזְדַּוְּגוּ לִנְשׁוֹתֵיהֶם, בָּאוּ מַלְאָכִים עֶלְיוֹנִים וְקִבְּלוּ אֶת יִשְׂרָאֵל בְּאַחֲוָה. אוֹתָם מַלְאָכִים לְמַעְלָה, וְיִשְׂרָאֵל מַלְאָכִים מִלְּמַטָּה. הֵם מְקַדְּשִׁים אֶת הַשֵּׁם הָעֶלְיוֹן לְמַעְלָה, וְיִשְׂרָאֵל מְקַדְּשִׁים אֶת הַשֵּׁם הָעֶלְיוֹן לְמַטָּה.</p>\n<p>וְהִתְעַטְרוּ יִשְׂרָאֵל בְּשִׁבְעִים כְּתָרִים בְּאוֹתוֹ לַיְלָה, וּמַלְאָכִים עֶלְיוֹנִים הָיוּ אוֹמְרִים, אָחוֹת לָנוּ קְטַנָּה וְשָׁדַיִם אֵין לָהּ, שֶׁאֵין בָּהֶם זְכֻיּוֹת וּמַעֲשִׂים טוֹבִים, מַה נַּעֲשֶׂה לַאֲחוֹתֵנוּ? כְּלוֹמַר, מַה כָּבוֹד וּגְדֻלָּה נַעֲשֶׂה לַאֲחוֹתֵנוּ זוֹ בַּיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְגַּלֶּה בְּהַר סִינַי לָתֵת לָהֶם תּוֹרָה?</p>\n<p>(ויהי ביום השלישי). כָּתוּב הֱיוּ נְכֹנִים לִשְׁלֹשֶׁת יָמִים אַל תִּגְּשׁוּ אֶל אִשָּׁה, וְהַיְנוּ בַיּוֹם הַשְּׁלִישִׁי. רַבִּי שִׁמְעוֹן אָמַר, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִגָּלוֹת בְּהַר סִינַי, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַפָּמַלְיָה שֶׁלּוֹ וְאָמַר לָהֶם: עַכְשָׁו יִשְׂרָאֵל תִּינוֹקוֹת שֶׁאֵינָם יוֹדְעִים אֶת הַנְהָגוֹתַי, וַאֲנִי רוֹצֶה לְהִתְגַּלּוֹת עֲלֵיהֶם. אִם אֶתְגַּלֶּה אֲלֵיהֶם בְּכֹחַ הַגְּבוּרָה - לֹא יוּכְלוּ לִסְבֹּל. אֲבָל אֶתְגַּלֶּה עֲלֵיהֶם בְּרַחֲמִים וִיקַבְּלוּ אֶת הַנְהָגוֹתַי. זֶהוּ שֶׁכָּתוּב וַיְהִי בַיּוֹם הַשְּׁלִישִׁי. בַּיּוֹם הַשְּׁלִישִׁי וַדַּאי, שֶׁהוּא רַחֲמִים. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד.</p>\n<p>וּבָזְהִ הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. הִקְדִּים לָהֶם רַחֲמִים בַּתְּחִלָּה, וְאַחַר נִתְּנָה לָהֶם תּוֹרָה מִצַּד הַגְּבוּרָה. בַיּוֹם הַשְּׁלִישִׁי, שֶׁכָּךְ רָאוּי לָהֶם, שֶׁבִּגְלַל כָּךְ נִקְרְאוּ יִשְׂרָאֵל.</p>\n<p>בִּהְיוֹת הַבֹּקֶר, שֶׁכָּתוּב (שם כג) בֹּקֶר לֹא עָבוֹת. הֲרֵי אִם הָיָה עָבוֹת, אָז נִמְצֵאת קַדְרוּת וְלֹא הִתְגַּלָּה חֶסֶ\"ד. וּמָתַי מִתְגַּלֶּה חֶסֶ\"ד? בַּבֹּקֶר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מד) הַבֹּקֶר אוֹר. שֶׁכְּשֶׁמֵּאִיר הַבֹּקֶר, נִמְצָא חֶסֶ\"ד בָּעוֹלָם וְהַדִּינִים עוֹבְרִים. וּבִזְמַן שֶׁלֹּא מֵאִיר הַבֹּקֶר, הַדִּינִים עַד אָז לֹא עוֹבְרִים, שֶׁכָּתוּב (איובלח) בְּרָן יַחַד כֹּכְבֵי בֹּקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. כֵּיוָן שֶׁעָבְרוּ אוֹתָם כּוֹכָבִים וּמֵאִיר הַשֶּׁמֶשׁ, בְּאוֹתָהּ שָׁעָה כָּתוּב בֹּקֶר לֹא עָבוֹת, וְחֶסֶ\"ד מִתְעוֹרֵר בָּעוֹלָם הַתַּחְתּוֹן. בְּאוֹתָהּ שָׁעָה כָּתוּב בִּהְיוֹת הַבֹּקֶר. וְכֵיוָן שֶׁעָבְרוּ הַכּוֹכָבִים, נִמְצָא הַבּקֶר. (כשהתעורר הבקר, דינים לא נמצאו).</p>\n<p>אָמַר רַבִּי יוֹסֵי, בִּהְיוֹת הַבֹּקֶר הִתְחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְגַּלּוֹת בְּהַר סִינַי. שָׁנִינוּ בִּהְיוֹת הַבֹּקֶר - כְּשֶׁהִתְעוֹרְרָה זְכוּתוֹ שֶׁל אַבְרָהָם שֶׁכָּתוּב בּוֹ (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר.</p>"],[9522011644,"<p>וַיְהִי קֹלֹת וּבְרָקִים. אָמַר רַבִּי אַבָּא, קֹלֹת כָּתוּב חָסֵר. שְׁנֵי קוֹלוֹת שֶׁחָזְרוּ לִהְיוֹת אֶחָד. זֶה יוֹצֵא מִזֶּה. רוּחַ מִמַּיִם, וּמַיִם מֵרוּחַ. שְׁנַיִם שֶׁהֵם אֶחָד, וְאֶחָד שֶׁהוּא שְׁנַיִם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, קֹלֹת אֶחָד, וְהוּא קוֹל גָּדוֹל חָזָק שֶׁאֵינוֹ פוֹסֵק לְעוֹלָמִים, הוּא שֶׁכָּתוּב בּוֹ קוֹל גָּדוֹל וְלֹא יָסָף, שֶׁהֲרֵי שְׁאָר הַקּוֹלוֹת פּוֹסְקִים, שֶׁשָּׁנִינוּ, בְּאַרְבַּע תְּקוּפוֹת בַּשָּׁנָה הַקּוֹל נִפְסָק, וְאָז הַדִּינִים מִתְעוֹרְרִים בָּעוֹלָם, וְקוֹל זֶה שֶׁכּוֹלֵל בּוֹ אֶת שְׁאָר הַקּוֹלוֹת, לֹא נִפְסָק לְעוֹלָמִים וְלֹא עוֹבֵר מִקִּיּוּם שָׁלֵם וְהַחֹזֶק שֶׁלּוֹ. שָׁנִינוּ, קוֹל זֶה קוֹל שֶׁל הַקּוֹלוֹת, קוֹל שֶׁכּוֹלֵל אֶת כָּל שְׁאָר הַקּוֹלוֹת.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אֵין קוֹל אֶלָּא מִצַּד רוּחַ וּמַיִם וְאֵשׁ, וּבַקּוֹל (והכל) עוֹשֶׂה קוֹל, וְנִכְלָל זֶה בָּזֶה, וְעַל זֶה כָּתוּב קֹלֹת וּבְרָקִים. אָמַר רַבִי יוֹסֵי, הַיְנוּ מַה שֶּׁכָּתוּב (תהלים קלה) בְּרָקִים לַמָּטָר עָשָׂה. שַׁלְהֶבֶת בַּעֲטָרוֹת, קֶשֶׁר שֶׁל רַחֲמִים בְּחִבָּה, שֶׁלֹּא (שוקעת) מְצוּיִים.</p>\n<p>שָׁנִינוּ, רַבִּי יְהוּדָה אוֹמֵר, בְּצַד הַגְּבוּרָה נִתְּנָה הַתּוֹרָה. אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, הִיא הָיְתָה בְּצַד שְׂמֹאל? אָמַר לוֹ, הָחְזְרָה לְיָמִין, שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וְכָתוּב יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ וְגוֹ'. מָצָאנוּ שְׂמֹאל שֶׁהָחְזַר לְיָמִין, וְיָמִין לִשְׂמֹאל. הֲרֵי גְּבוּרָה לִשְּׂמֹאל (לימין).</p>\n<p>וְעָנָן כָּבֵד עַל הָהָר וְגוֹ' - עָנָן חָזָק שֶׁשָּׁקוּעַ בִּמְקוֹמוֹ, שֶׁלֹּא לוֹקֵחַ. וְקֹל שֹׁפָר חָזָק מְאֹד - מִתּוֹךְ הֶעָנָן הֶחָזָק הָיָה יוֹצֵא אוֹתוֹ הַקּוֹל, כְּמוֹ שֶׁנֶּאֱמַר (דבריםה) וַיְהִי כְּשָׁמְעֲכֶם אֶת הַקּוֹל מִתּוֹךְ הַחֹשֶׁךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, שָׁלֹשׁ חֲשֵׁכִים הָיוּ, שֶׁכָּתוּב חֹשֶׁךְ עָנָן וַעֲרָפֶל. וְאוֹתוֹ קוֹל הָיָה יוֹצֵא פְּנִימִי מִכֻּלָּם. אָמַר רַבִּי יוֹסֵי, הַפְּנִימִי שֶׁל הַכֹּל הָיָה, שֶׁבּוֹ כָּתוּב קוֹל גָּדוֹל וְלֹא יָסָף.</p>"],[9522011645,"<p>אָמַר רַבִּי אַבָּא, כָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. רֹאִים? שׁוֹמְעִים הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּךְ שָׁנִינוּ, אוֹתָם קוֹלוֹת הָיוּ נֶחְקָקִים בְּאוֹתוֹ חֹשֶׁךְ וְעָנָן וַעֲרָפֶל וְנִרְאִים בָּהֶם כְּמוֹ שֶׁנִּרְאֶה גוּף, וְרוֹאִים מַה שֶּׁרוֹאִים, וְשׁוֹמְעִים מַה שֶּׁשּׁוֹמְעִים מִתּוֹךְ אוֹתוֹ חֹשֶׁךְ וַעֲרָפֶל וְעָנָן, וּמִתּוֹךְ אוֹתוֹ מַרְאֶה שֶׁהָיוּ רוֹאִים, הָיוּ מְאִירִים בְּאוֹר עֶלְיוֹן, וְיוֹדְעִים מַה שֶּׁלֹּא יָדְעוּ דּוֹרוֹת אַחֲרוֹנִים שֶׁבָּאוּ אַחֲרֵיהֶם.</p>\n<p>וְכֻלָּם הָיוּ רוֹאִים פָּנִים בְּפָנִים, זֶהוּ שֶׁכָּתוּב פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם. וּמֶה הָיוּ רוֹאִים? שָׁנָה רַבִּי יוֹסֵי, מֵהָאוֹר שֶׁל אוֹתָם הַקּוֹלוֹת, שֶׁלֹּא הָיָה קוֹל, שֶׁלֹּא הָיָה מֵאִיר בְּאוֹר, שֶׁמִּסְתַּכְּלִים בּוֹ כָּל הַגְּנָזִים, וְכָל הַנִּסְתָּרִים, וְכָל הַדּוֹרוֹת שֶׁיָּבאוּ עַד מֶלֶךְ הַמָּשִׁיחַ. וּמִשּׁוּם כָּךְ כָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. רֹאִים - רְאִיָּה מַמָּשׁ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וְכָל הָעָם רֹאִים, רֹאִים - כְּמוֹ שֶׁאָמַרְנוּ, שֶׁרָאוּ מֵהָאוֹר שֶׁל אוֹתָם הַקּוֹלוֹת מַה שֶּׁלֹּא רָאוּ דוֹרוֹת אַחֲרוֹנִים אֲחֵרִים. אֶת הַקּוֹלֹת - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) וָאֵרֶא אֶת ה'. וָאֵרֶא ה' לֹא כָתוּב, אֶלָּא אֶת ה'. אַף כָּאן, וְכָל הָעָם רֹאִים הַקּוֹלֹת לֹא נֶאֱמַר, אֶלָּא אֶת הַקּ וֹלֹת.</p>\n<p>כְּמוֹ זֶה אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. שֶׁהֲרֵי הָאֶתִים שֶׁבַּתּוֹרָה נִתְּנוּ כְּדֵי לְהִסְתַּכֵּל בַּתּוֹרָה (בחכמה). כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. (משלי ג) כַּבֵּד אֶת ה' מֵהוֹנֶךְ. וְכֻלָּם לְהַכְלִיל בָּהֶם דָּבָר אַחֵר. אַף כָּאן אֶת הַקּוֹלֹת - לְרַבּוֹת אוֹתוֹ קוֹל אַחֵר לְמַטָּה, שֶׁכּוֹנֵס אוֹתָם אֵלָיו מַה שֶּׁיּוֹצֵא מֵהֶם, שֶׁבּוֹ רוֹאִים וּמִסְתַּכְּלִים בְּחָכְמָה עֶלְיוֹנָה כָּל הַגְּנָזִים הָעֶלְיוֹנִים וְכָל הַסּוֹדוֹת הַטְּמִירִים וְנִסְתָּרִים, מַה שֶּׁלֹּא הִתְגַּלָּה לְדוֹרוֹת אַחֲרוֹנִים שֶׁבָּאוּ אַחֲרֵיהֶם וְלֹא לַדּוֹרוֹת שֶׁיָּבאוּ לְעוֹלָמִים עַד הַזְּמַן שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. וְאֶת הַלַּפִּידִם - בַּתְּחִלָּה בְּרָקִים, וְעַכְשָׁו לַפִּידִים. הַכֹּל אֶחָד. אֲבָל מִשֶּׁהִתְתַּקְּנוּ בְתִקּוּנִים לְהֵרָאוֹת, נִקְרְאוּ כָּךְ.</p>\n<p>וְאֵת קוֹל הַשֹּׁפָר - שָׁנָה רַבִּי יִצְחָק, כָּתוּב (תהלים סב) אַחַת דִּבֶּר אֱלֹהִים שְׁתַּיִם זוּ שָׁמַעְתִּי, כְּמוֹ שֶׁנֶּאֱמַר אָנֹכִי, וְלֹא יִהְיֶה לְךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, קוֹל בַּשּׁוֹפָר הָיָה צָרִיךְ לִהְיוֹת! לָמָּה הַשֹּׁפָר? אֶלָּא אוֹתוֹ קוֹל שֶׁנִּקְרָא שׁוֹפָר, שֶׁכָּתוּב (ויקראכה) וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה בַּחֹדֶשׁ הַשְּׁבִעִי בֶּעָשׂוֹר לַחֹדֶשׁ בְּיוֹם הַכִּפֻּרִים. בָּזֶה נִבְרָא (נקרא) שׁוֹפָר.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה שּׁוֹפָר מוֹצִיא קוֹל, אֵשׁ רוּחַ וּמַיִם (דין חסד ורחמים), אַף כָּאן הַכֹּל נִכְלָל בָּזֶה, וּמִזֶּה יוֹצְאִים הַקּוֹלוֹת הָאֲחֵ רִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, קוֹל שֶׁיּוֹצֵא מִשּׁוֹפָר, שֶׁמַּשְׁמָע שֶׁשּׁוֹפָר אֶחָד, וְקוֹל יוֹצֵא מִמֶּנּוּ, וְשׁוֹפָר בְּקִיּוּמוֹ מָצוּי, וּמִשּׁוּם כָּךְ כָּתוּב קוֹל הַשֹּׁפָר.</p>\n<p>רַבִּי יְהוּדָה אָמַר כָּךְ, קוֹל הַשֹּׁפָר - הַשֹּׁפָר כָּתוּב חָסֵר, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ו) שְׁפַר קֳדָם דָּרְיָוֶשׁ. (שם ד) מִלְכִּי יִשְׁפַּר עֲלָךְ. (שם ג) שְׁפַר קָדָמַי לְהַחֲוָיָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, קוֹל הַשֹּׁפָר - מָקוֹם שֶׁקּוֹל יוֹצֵא מִמֶּנּוּ נִקְרָא שׁוֹפָר. עוֹד אָמַר רַבִּי שִׁמְעוֹן, בֹּא וּרְאֵה, קוֹל הַשֹּׁפָר - מָקוֹם שֶׁל קוֹל, הַיְנוּ שֶׁכָּתוּב (דברים ח) כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. מַה זֶּה מוֹצָא פִּי ה'? זֶה קוֹל (ס\"ר שיוצא משופר, וזה קול) הַשּׁוֹפָר, הוּא גָּדוֹל מִכָּל שְׁאָר הַקּוֹלוֹת הַתַּחְתּוֹנִים וְחָזָק מִכֻּלָּם, שֶׁכָּתוּב וְקֹל שֹׁפָר חָזָק מְאֹד, וְעַל כָּל שְׁאָר הַקּוֹלוֹת לֹא נֶאֱמַר חָזָק מְאֹד. (אמר רבי שמעון) בְּקוֹל הַשּׁוֹפָר הַזֶּה הַכֹּל תָּלוּי, וְזֶהוּ שֶׁנִּקְרָא קוֹל גָּדוֹל, שֶׁכָּתוּב קוֹל גָּדוֹל וְלֹא יָסָף. וְנִקְרָא קוֹל דְּמָמָה דַקָּה, אוֹר הַמְּנוֹרוֹת, שֶׁהוּא זַךְ וְדַקִּיק וּמְזֻכָּךְ וּמֵאִיר לַכֹּל.</p>\n<p>דְּמָמָה, מַה זֶּה דְּמָמָה? אָמַר רַבִּי שִׁמְעוֹן, שֶׁצָּרִיךְ אָדָם לִשְׁתֹּק מִמֶּנּוּ וְלַחְסֹם אֶת פִּיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לט) אָמַרְתִּי אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי אֶשְׁמְרָה לְפִי מַחְסוֹם. דְּמָמָה הִיא שְׁתִיקָה שֶׁלֹּא נִשְׁמַעַת הַחוּצָה. וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק, שֶׁרָאוּ מַה שֶּׁרָאוּ. וַיָּנֻעוּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) וַיָּנֻעוּ אַמּוֹת הַסִּפִּים מִקּוֹל הַקּוֹרֵא.</p>\n<p>שָׁנִינוּ, מַה כָּתוּב בִּיחֶזְקֵאל כְּשֶׁרָאָה גְבוּרוֹת הַנְהָגוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה וְגוֹ'. לָמָּה רוּחַ סְעָרָה? אָמַר רַבִּי יוֹסֵי, כְּדֵי לִשְׁבֹּר אַרְבַּע מַלְכֻיּוֹת. אָמַר רַבִּי יְהוּדָה, שָׁנִינוּ, רוּחַ גְּדוֹלָה שֶׁמִּתְעוֹרֶרֶת בְּהַנְהָגוֹת הַגְּבוּרָה שֶׁלְּמַעְלָה בָּאָה מִן הַצָּפוֹן. לֹא כָתוּב מִצָּפוֹן אֶלָּא מִן הַצָּפוֹן, מִן אוֹתוֹ הַצָּפוֹן, אוֹתוֹ שֶׁנּוֹדָע לְמַעְלָה, אוֹתוֹ שֶׁטָּמִיר וְגָנוּז לְמַעְלָה.</p>\n<p>עָנָן גָּדוֹל וְאֵשׁ מִתְלַקַּחַת, שֶׁהָיָה אָחוּז בּוֹ (ולא אחוז, אחוז בצדדיו) וְלֹא הָיָה אָחוּז בְּצִדּוֹ לְעוֹרֵר הַדִּין, שֶׁשָּׁנִינוּ, שָׁלֹשׁ פְּעָמִים בְּיוֹם יוֹנֵק אוֹתוֹ דִין הַקָּשֶׁה בַּמְמֻנִּים חֲקוּקִים מִצַּד הַגְּבוּרָה. זֶהוּ שֶׁכָּתוּב וְאֵשׁ מִתְלַקַּחַת, כְּדֵי לְעוֹרֵר בָּעוֹלָם.</p>\n<p>וּמַה מְבַסֵּם אוֹתוֹ? אוֹתוֹ שֶׁכָּתוּב בּוֹ וְנֹגַהּ לוֹ סָבִיב. שֶׁאוֹתוֹ זֹהַר שֶׁמַּקִּיף אוֹתוֹ מִכָּל צְדָדָיו מְבַסֵּם אוֹתוֹ וּמְתַקֵּן אוֹתוֹ כְּדֵי שֶׁלֹּא יִהְיֶה דִין קָשֶׁה וְיוּכְלוּ בְנֵי אָדָם לִסְבֹּל אוֹתוֹ.</p>\n<p>וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל. שָׁנִינוּ, וּמִתּוֹכָהּ - וּמִתּוֹכָהּ. כְּעֵין הַחַשְׁמַל - מַה זֶּה חַשְׁמַל? אָמַר רַבִּי יְהוּדָה, חַיּוֹת אֵשׁ מְדַבְּרוֹת.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, חַשְׁמַל - מַה שֶּׁהָיָה לֵב לָאֵשׁ, שֶׁכָּתוּב מִתּוֹךְ הָאֵשׁ כְּעֵין הַחַשְׁמַל. וְלֹא הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, מִתּוֹךְ אֵשׁ שֶׁהִיא לְתוֹךְ אֵשׁ. כְּעֵין הַחַשְׁמַל, שֶׁהִיא אַחַר אַרְבַּע דְּרָגוֹת, שֶׁכָּתוּב רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב. וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ, אוֹתוֹ שֶׁכָּתוּב בּוֹ וְאֵשׁ מִתְלַקַּחַת.</p>\n<p>שָׁנִינוּ, רַבִּי יוֹסֵי בַּר רַבִּי יְהוּדָה אָמַר, רָאוּ יִשְׂרָאֵל כָּאן מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל בֶּן בּוּזִי, וְכֻלָּם נִדְבְּקוּ בְחָכְמָה עֶלְיוֹנָה נִכְבָּדָה. חָמֵשׁ דְּרָגוֹת שֶׁל קוֹלוֹת רָאוּ יִשְׂרָאֵל בְּהַר סִינַי, וּבַחֲמֵשׁ הַדְּרָגוֹת הַלָּלוּ נִתְּנָה תוֹרָה. דַּרְגָּה חֲמִישִׁית הוּא, שֶׁכָּתוּב קוֹל הַשֹּׁפָר. כְּנֶגְדָּם רָאָה יְחֶזְקֵאל חָמֵשׁ דְּרָגוֹת שֶׁהֵן חוּץ לְאֵלֶּה, שֶׁהֵם: רוּחַ סְעָרָה, עָנָן גָּדוֹל, וְאֵשׁ מִתְלַקַּחַת, וְנֹגַהּ לוֹ סָבִיב, כְּעֵין הַחַשְׁמַל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בְּיִשְׂרָאֵל כָּתוּב (דברים ה) פָּנִים בְּפָנִים דִּבֶּר ה' וְגוֹ'. בִּיחֶזְקֵאל כָּתוּב כְּעֵין, וּדְמוּת, כְּמִי שֶׁרוֹאֶה אַחַר כְּתָלִים רַבִּים, כְּמִי שֶׁרוֹאֶה אָדָם אַחַר כֹּתֶל. אָמַר רַבִּי יְהוּדָה, מַה שֶּׁרָאוּ יִשְׂרָאֵל - לֹא רָאָה נָבִיא אַחֵר. כָּל שֶׁכֵּן מַה שֶּׁרָאָה מֹשֶׁה שֶׁלֹּא רָאָה נָבִיא אַחֵר (כל שכן אדם אחר). אַשְׁרֵי חֶלְקוֹ, שֶׁכָּתוּב בּוֹ (שמות לד) וַיְהִי שָׁם עִם ה', וְלֹא בְמַרְאֶה אַחֵר, כַּכָּתוּב (במדבר לד) וּמַרְאֶה וְלֹא בְחִידוֹת.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בֹּא וּרְאֵה, כָּתוּב הָיֹה הָיָה דְבַר ה'. נְבוּאָה לִשְׁעָתָהּ הָיְתָה. רַבִּי יְהוּדָה אוֹמֵר, לְקִיּוּם הוּא בָּא, שֶׁהִצְטָרֵךְ לִהְיוֹת בִּשְׁבִיל יִשְׂרָאֵל, לְהוֹדִיעַ שֶׁהֲרֵי לֹא עָזַב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל מִתְפַּזְּרִים בַּגָּלוּת, הוּא שָׁרוּי עִמָּהֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הָיֹה הָיָה - שֶׁרָאָה וְלֹא רָאָה, שֶׁעוֹמֵד בְּאוֹתָם דְּבָרִים וְלֹא עוֹמֵד. זֶהוּ שֶׁכָּתוּב וָאֵרֶא כְּעֵין הַחַשְׁמַל, וְלֹא חַשְׁמַל. אֲבָל יִשְׂרָאֵל מַה כָּתוּב בָּהֶם? וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. כָּל אֶחָד וְאֶחָד רָאָה כָּרָאוּי לוֹ.</p>\n<p>שֶׁשָּׁנִינוּ, כָּל אֶחָד וְאֶחָד הָיוּ עוֹמְדִים שׁוּרוֹת שׁוּרוֹת, תְּחוּמִים תְּחוּמִים, וּכְמוֹ שֶׁרָאוּי לָהֶם רָאוּ כָּל אֶחָד וְאֶחָד. אָמַר רַבִּי שִׁמְעוֹן, רָאשֵׁי הָעָם לְבַדָּם, רָאשֵׁי הַשְּׁבָטִים לְבַדָּם. הַנְּקֵבוֹת לְבַדָּן. חָמֵשׁ דְּרָגוֹת לְיָמִין, וְחָמֵשׁ דְּרָגוֹת לִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (דבריםכט) אַתֶּם נִצָּבִים הַיּוֹם כֻּלְּכֶם לִפְנֵי ה' אֱלֹהֵיכֶם רָאשֵׁיכֶם שִׁבְטֵיכֶם זִקְנֵיכֶם וְשֹׁטְרֵיכֶם כֹּל אִישׁ וְגוֹ'. הֲרֵי חָמֵשׁ דְּרָגוֹת לְיָמִין. וְחָמֵשׁ דְּרָגוֹת לִשְׂמֹאל מַה הֵן? הַיְנוּ שֶׁכָּתוּב טַפְּכֶם, נְשֵׁיכֶם, וְגֵרְךְ אֲשֶׁר בְּקֶרֶב מַחֲנֶיךְ, מֵחֹטֵב עֵצֶיךְ, עַד שֹׁאֵב מֵימֶיךְ. הֲרֵי חָמֵשׁ דְּרָגוֹת לִשְׂמֹאל.</p>\n<p>כָּל הַדְּרָגוֹת הִתְתַּקְּנוּ כְּמוֹ שֶׁלְּמַעְלָה. כְּנֶגְדָּם יָרְשׁוּ יִשְׂרָאֵל יְרֻשַּׁת עוֹלָמִים, עֶשֶׂר אֲמִירוֹת, שֶׁבָּהֶן תְּלוּיוֹת כָּל הַמִּצְווֹת וְכָל הַזְּכֻיּוֹת וְכָל יְרֻשַּׁת נַחֲלָה, שֶׁהֵם הַחֵלֶק הַטּוֹב שֶׁל יִשְׂרָאֵל.</p>\n<p>שָׁנִינוּ, בְּאוֹתָהּ הַשָּׁעָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בְּהַר סִינַי, הָיוּ רוֹאִים כָּל יִשְׂרָאֵל כְּמִי שֶׁרוֹאֶה אוֹר בַּעֲשָׁשִׁית, וּמֵאוֹתוֹ אוֹר הָיָה רוֹאֶה כָּל אֶחָד וְאֶחָד מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָם קוֹלוֹת עֶלְיוֹנִים הִתְגַּלּוּ (נחקקו) בְאֶחָד, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. אֲבָל בִּיחֶזְקֵאל, הַשְּׁכִינָה נִגְלְתָה בְּמַרְכְּבוֹתֶיהָ וְלֹא יוֹתֵר, וְהָיָה רוֹאֶה כְּמִי שֶׁרוֹאֶה אַחַר כְּתָלִים רַבִּים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁכָּתוּב בּוֹ וַיֵּרֶד ה' עַל הַר סִינַי וַיִּקְרָא ה' לְמֹשֶׁה. אַשְׁרֵי דּוֹרוֹ, שֶׁכָּתוּב בּוֹ יֵרֵד ה' לְעֵינֵי כָל הָעָם עַל הַר סִינָי.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ, שֶׁהֲרֵי מִיָּמִין הִתְגַּלָּה מַה שֶּׁהִתְגַּלָּה. מַה בֵּין זֶה לָזֶה? אָמַר רַבִּי יוֹסֵי, כָּאן בְּסִינַי - רֹאשׁ וְגוּף הַמֶּלֶךְ, שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד. וּבְמָקוֹם שֶׁיֵּשׁ רֹאשׁ יֵשׁ גּוּף. אֲבָל בִּיחֶזְקֵאל כָּתוּב וַתְּהִי עָלָיו שָׁם יַד ה', שֶׁהִתְגַּלְּתָה הַיָּד וְלֹא הַגּוּף. וְשָׁנִינוּ, אֲפִלּוּ בַּיָּד, יַד ה' עֶלְיוֹנָה, יַד ה' תַּחְתּוֹנָה.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאֹת אֱלֹהִים. מַרְאֹת כָּתוּב חָסֵר, לְהַרְאוֹת שֶׁבִּשְׁבִיל הַשְּׁכִינָה זֶה נֶאֱמַר, שֶׁהֲרֵי וָאֶרְאֶה מַרְאֹת חָסֵר, מַרְאֶה אֶחָד. אָמַר רַבִּי יֵיסָא, וְכִי שְׁכִינָה לֹא הַכֹּל? אָמַר רַבִּי יוֹסֵי, לֹא דוֹמֶה רֹאשׁ הַמֶּלֶךְ לְרַגְלֵי הַמֶּלֶךְ, אַף עַל גַּב שֶׁהַכֹּל נִמְצָא בְּגוּף הַמֶּלֶךְ.</p>\n<p>בֹּא וּרְאֵה, בִּישַׁעְיָהוּ כָּתוּב (ישעיה ו) וָאֵרֶא אֶת ה'. בִּיחֶזְקֵאל כָּתוּב וָאֶרְאֶה מַרְאֹת אֱלֹהִים. כָּאן אֶת, שָׁם מַרְאֹת. מַה שֶּׁרָאָה זֶה - רָאָה זֶה. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁלֹּא הָיָה נָבִיא נֶאֱמָן שָׁלֵם כְּמוֹתוֹ.</p>\n<p>וָאֵרֶא אֶת ה', אֶת דַּוְקָא. וָאֶרְאֶה מַרְאֹת אֱלֹהִים, מַרְאֹת דַּוְקָא. וּבְדַרְגָּה אַחַת הָיוּ. אִם כָּךְ, אָז לָמָּה לֹא פֵרַשׁ יְשַׁעְיָה כָּל זֶה? אָמַר רַבִּי יוֹסֵי, זֶה כָּלַל וְזֶה פֵּרַשׁ. מָה הַטַּעַם יְחֶזְקֵאל פֵּרַשׁ אֶת כָּל זֶה? אֶלָּא הַכֹּל הִצְטָרֵךְ בִּשְׁבִיל יִשְׂרָאֵל, שֶׁיֵּדְעוּ אֶת הַחִבָּה שֶׁחִבֵּב אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁשְּׁכִינָתוֹ וּמַרְכְּבוֹתָיו בָּאוּ לָדוּר בֵּינֵיהֶם בַּגָּלוּת.</p>\n<p>אָמַר רַבִּי חִיָּיא, בְּאֶרֶץ כַּשְׂדִּים? וַהֲרֵי כָּתוּב (ישעיה כג) הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה. לָמָּה הִתְגַּלְּתָה שָׁם שְׁכִינָה? אִם תֹּאמַר בִּשְׁבִיל יִשְׂרָאֵל - הָיָה טוֹב שֶׁתִּשְׁרֶה שְׁכִינָה בְתוֹכָם וְלֹא תִתְגַּלֶּה. אֶלָּא כָּךְ שָׁנִינוּ, אִם לֹא הָיָה נִגְלֵית, לֹא הָיוּ יוֹדְעִים.</p>\n<p>וְזְהִ שֶׁהִתְגַּלְּתָה, מַה כָּתוּב? עַל נְהַר כְּבָר. עַל הַמַּיִם. בְּמָקוֹם שֶׁלֹּא נִטְמָא וְלֹא שׁוֹרָה טֻמְאָה. וְאוֹתוֹ נָהָר הָיָה אֶחָד מֵאַרְבָּעָה נְהָרוֹת שֶׁיּוֹצְאִים מִגַּן עֵדֶן, שֶׁכָּתוּב עַל נְהַר כְּבָר. מַה זֶּה כְּבָר? שֶׁכְּבָר הָיָה מִמָּקוֹם שֶׁשְּׁכִינָה שׁוֹרָה עָלָיו, וְכָתוּב וַתְּהִי עָלָיו שָׁם יַד ה', שָׁם וְלֹא בְמָקוֹם אַחֵר.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּתוּב וּמִתּוֹכָהּ דְּמוּת אַרְבַּע חַיּוֹת וְזֶה מַרְאֵיהֶן דְּמוּת אָדָם לָהֵנָּה. שָׁנִינוּ, בְּסוֹד עֶלְיוֹן אַרְבַּע חַיּוֹת יֵשׁ שֶׁהֵן לִפְנַי וְלִפְנִים הַהֵיכָל הַקָּדוֹשׁ, וְהֵן רִאשׁוֹנוֹת, הָעַתִּיקִים מֵהָעַתִּיק הַקָּדוֹשׁ, כְּלַל הַשֵּׁם הָעֶלְיוֹן. וִיחֶזְקֵאל רָאָה דְמוּת הַמֶּרְכָּבוֹת הָעֶלְיוֹנוֹת, שֶׁהֲרֵי הוּא רָאָה מִמָּקוֹם שֶׁלֹּא הָיָה מֵאִיר כָּל כָּךְ. שָׁנִינוּ, כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה מֵהֶם, וְכֵן בְּכָל הָעוֹלָמוֹת כֻּלָּם אֲחוּזִים זֶה בָּזֶה וְזֶה בָּזֶה.</p>\n<p>וְאִם תֹּאמַר שֶׁהוּא רָאָה יוֹתֵר לְמַעְלָה - שָׁנִינוּ, מֹשֶׁה רָאָה בְּאַסְפַּקְלַרְיָה שֶׁמְּאִירָה, וְכָל הַנְּבִיאִים לֹא רָאוּ אֶלָּא מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, שֶׁכָּתוּב וָאֶרְאֶה מַרְאֹת אֱלֹהִים. וְכָתוּב (במדבר יב) אִם יִהְיֶה נְבִיאֲכֶם ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע וְגוֹ' לֹא כֵן עַבְדִּי מֹשֶׁה וְגוֹ', וְכָתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.</p>"],[9522011646,"<p>אָמַר רַבִּי יוֹסֵי, בֹּא וּרְאֵה שֶׁכָּל הַנְּבִיאִים כֻּלָּם לְגַבָּיו כִּנְקֵבָה לְגַבֵּי הַזָּכָר, שֶׁכָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה. וְלִשְׁאָר הַנְּבִיאִים (כתוב במראות, ולמשה ה') בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, בַּמַּרְאָה וְלֹא מַרְאוֹת. כָּל שֶׁכֵּן יְחֶזְקֵאל, שֶׁאֲפִלּוּ מַרְאָה לֹא כָתוּב בּוֹ, אֶלָּא מַרְאֹת חָסֵר, וְכָל שֶׁכֵּן שֶׁכָּתוּב בְּמֹשֶׁה וְלֹא בְחִידוֹת, אֶלָּא כָּל דָּבָר עַל בֻּרְיוֹ. אַשְׁרֵי הַדּוֹר שֶׁהַנָּבִיא הַזֶּה שָׁרוּי בְּתוֹכָם.</p>\n<p>אָמַר רַבִּי יוֹסֵי בְּרַבִּי יְהוּדָה, פָּנִים בְּפָנִים רָאוּ יִשְׂרָאֵל אֶת זִיו כְּבוֹד מַלְכָּם, (של רבונם) וְלֹא הָיוּ בָהֶם סוּמִים וְחִגְּרִים וְקִטְּעִים וְחֵרְשִׁים. סוּמִים - מַשְׁמָע שֶׁכָּתוּב וְכָל הָעָם רֹאִים. חִגְּרִים - שֶׁכָּתוּב וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. קִטְּעִים וְחֵרְשִׁים - נַעֲשֶׂה וְנִשְׁמָע. וְלֶעָתִיד לָבֹא כָּתוּב (ישעיה לה) אָז יְדַלֵּג כְּאַיָּל פִּסֵּחַ וְתָרֹן לְשׁוֹן אִלֵּם.</p>\n<p>וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. רַבִּי יְהוּדָה פָּתַח, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. בְּכַמָּה דְרָכִים הֵעִידָה הַתּוֹרָה בָּאָדָם שֶׁלֹּא יֶחֱטָא לִפְנֵי רִבּוֹנוֹ. בְּכַמָּה דְרָכִים נָתְנָה לוֹ עֵצָה שֶׁלֹּא יִסְטֶה מִדְּרָכָיו יָמִין וּשְּׂמֹאל. בְּכַמָּה דְרָכִים נָתְנָה לוֹ עֵצָה אֵיךְ יָשׁוּב לִפְנֵי רִבּוֹנוֹ וְיִמְחֹל לוֹ.</p>\n<p>שֶׁשָּׁנִינוּ, שֵׁשׁ מֵאוֹת וּשְׁלֹשָׁה עָשָׂר מִינֵי עֵצָה נָתְנָה תוֹרָה לָאָדָם לִהְיוֹת שָׁלֵם בְּרִבּוֹנוֹ, מִשּׁוּם שֶׁרִבּוֹנוֹ רוֹצֶה לְהֵיטִיב לוֹ בָּעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא, וְיוֹתֵר לָעוֹלָם הַבָּא, שֶׁהֲרֵי שָׁנִינוּ, כָּל מַה שֶּׁהִשְׁלִים הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם - מֵאוֹתָן טוֹבוֹת שֶׁזּוֹכֶה בָּהֶם לָעוֹלָם הַבָּא הִשְׁתַּלֵּם בָּהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהָעוֹלָם הַבָּא הוּא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. (ואם תאמר שהעולם הזה אינו שלו אלא)</p>\n<p>וְכָךָ שָׁנִינוּ, הָעוֹלָם הַזֶּה כְּנֶגֶד הָעוֹלָם הַבָּא אֵינוֹ אֶלָּא כִּפְרוֹזְדוֹר לִטְרַקְלִין. (משום כך העולם הבא הוא של הקדוש ברוך הוא) וּכְשֶׁזּוֹכֶה אוֹתוֹ הַצַּדִּיק - בְּשֶׁלּוֹ הוּא זוֹכֶה. שֶׁשָּׁנִינוּ, כָּתוּב (דברים ב) וְנַחֲלָה לֹא יִהְיֶה לּוֹ בְּקֶרֶב אֶחָיו. מָה הַטַּעַם? מִשּׁוּם שֶׁה' הוּא נַחֲלָתוֹ. אַשְׁרֵי חֶלְקוֹ מִי שֶׁזּוֹכֶה לְחֵלֶק יְרֻשָּׁה עֶלְיוֹן זֶה. זוֹכֶה בָּהּ בָּעוֹלָם הַזֶּה, וּבַבַּיִת שֶׁל הָעוֹלָם הַזֶּה. כָּךְ בָּעוֹלָם הַבָּא וּבַבַּיִת הָעֶלְיוֹן הַקָּדוֹשׁ, שֶׁכָּתוּב (ישעיהנו) וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ צַדִּיק שֶׁמְּדוֹרוֹ עִם הַמֶּלֶךְ בְּבֵיתוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ צַדִּיק שֶׁזּוֹכֶה לָזֶה, שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. לֹא כָתוּב עִם ה', אֶלָּא עַל ה'. מַה זֶּה עַל ה'? מָקוֹם שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים נִמְשָׁכִים מִמֶּנּוּ וּתְאֵבִים לְאוֹתוֹ מָקוֹם, שֶׁכָּתוּב (תהלים קכא) מֵאַיִן יָבא עֶזְרִי. וְכָתוּב (דניאלז) וְעַד עַתִּיק הַיָּמִים מַגִּיעַ וּלְפָנָיו הִקְרִיבוּהוּ. וּתְשׁוּקַת וְעֹנֶג הַצַּדִּיקִים לְהִסְתַּכֵּל לְאוֹתוֹ זִיו, שֶׁכָּל זִיו יוֹצֵא מִמֶּנּוּ, וּמִמֶּנּוּ נִמְשָׁכִים כָּל אוֹתָם הַכְּתָרִים.</p>\n<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ בְּפָסוּק זֶה אָז תִּתְעַנַּג עַל ה', בְּסוֹף הַפָּסוּק מַה כָּתוּב? וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ, עַל אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּמֳתֵי אָרֶץ, הוּא לְמַעְלָה מֵהָאָרֶץ הַזּוֹ. וְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּמֳתֵי אָרֶץ, הַיְנוּ שָׁמַיִם, וְהַיְנוּ שֶׁכָּתוּב עַל בָּמֳתֵי אָרֶץ.</p>\n<p>עַל ה' - אָמַר רַבִּי אַבָּא, לֹא כָתוּב אָז תֵּשֵׁב, אֶלָּא אָז תִּתְעַנַּג עַל ה', הַיְנוּ שָׁמַיִם, שֶׁכָּתוּב (תהליםנז) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים. וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ, הַיְנוּ אֶרֶץ הַחַיִּים, מִמַּשְׁמָע שֶׁכָּתוּב עַל בָּמֳתֵי, לְהַכְלִיל צִיּוֹן וִירוּשָׁלַיִם שֶׁנִּקְרְאוּ בָּמֳתֵי אָרֶץ, וְהַיְנוּ שָׁמַיִם שֶׁלְּמַעְלָה וְאֶרֶץ שֶׁלְּמַעְלָה. וְהַדָּבָר שֶׁאָמַר רַבִּי שִׁמְעוֹן כָּךְ הוּא, וְהַכֹּל אֶחָד, שֶׁכָּתוּב וְעַד עַתִּיק הַיָּמִים מַגִּיעַ וְגוֹ', וְכָל הַדְּבָרִים הַלָּלוּ עוֹלִים לְמָקוֹם אֶחָד.</p>\n<p>אָמַר רַבִּי אַבָּא לְרַבִּי שִׁמְעוֹן, יֹאמַר לִי מוֹרִי, פָּסוּק זֶה כֻּלּוֹ בַּמֶּה בֵּאַרְנוּ אוֹתוֹ, שֶׁכָּתוּב אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ? אָמַר לוֹ, הֲרֵי הַכֹּל נֶאֱמַר כְּבָר, שֶׁתַּפְנוּק וְעִדּוּן עַל ה' כָּתוּב, מָקוֹם שֶׁהוּא לְמַעְלָה, וְכָתוּב וְעַד עַתִּיק הַיָּמִים מַגִּיעַ. עַל בָּמֳתֵי אָרֶץ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְהַאֲכַלְתִּיךָ נַחֲלַת יַעֲקֹב אָבִיךְ, כְּמוֹ שֶׁכָּתוּב (בראשית כז) וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וְגוֹ', וְהַיְנוּ נַחֲלַת יַעֲקֹב. וְהַבְּרָכָה שִּבּרַךָ יּצּחָק אִת יַּעַקב, עַל הַשָּמַיּם הַלָּלוּ הוּא אָמַר, וּברכו בּברָכָה, שִּעַתיּדיּם בּניּ יַּעַקב, להחָיּות בּאותו טַל לִעָתיּד לָבא, שִּכָּתוּב ויּתִן לךְ הָאִלהיּם, לךְ ולא לאַחר, מטַל הַשָּמַיּם, שִּבּו עַתיּדיּם הַמּתיּם להחָיּות לִעָתיּד לָבא, שִּיּוצּא מֵהָעַתִּיק לִזְעֵיר אַנְפִּין וְשׁוֹרֶה בַשָּׁמַיִם הַלָּלוּ. הִתְבּוֹנֵן רַבִּי אַבָּא וְאָמַר, עַכְשָׁו נִשְׁמָע הַכֹּל, וְנִמְצֵאת בִּרְכַּת יִצְחָק עֶלְיוֹנָה מִמַּה שֶּׁחָשַׁבְתִּי.</p>\n<p>שָׁנִינוּ, מִי יְמַלֵּל גְּבוּרֹת ה'. מִי יְמַלֵּל? מִי יְדַבֵּר הָיָה צָרִיךְ לִהְיוֹת! אָמַר רַבִּי חִיָּיא, כְּמוֹ שֶׁנֶּאֱמַר (דברים כג) וְקָטַפְתָּ מְלִילֹת בְּיָדֶךְ. גְּבוּרֹת ה', שֶׁרַבִּים הֵם וְיוֹצְאִים מִגְּבוּרָה אַחַת. וְשָׁנִינוּ, גְּבוּרָה עֶלְיוֹנָה אַחַת, עֲטֶרֶת הָעֲטָרוֹת, מִתְעַטֶּרֶת, וְיוֹצְאִים מִמֶּנָּה חֲמִשִּׁים שְׁעָרִים, מֵהֶם יָמִינָה וּמֵהֶם שְׂמֹאלָה, וְכָל אַחַת נִקְרֵאת גְּבוּרָה, וְכָל אַחַת וְאַחַת מִתְעַטֶּרֶת בָּאוֹרוֹת שֶׁל חֲקִיקוֹת גְּבוֹהוֹת, וְכֻלָּם נִקְרָאוֹת גְּבוּרוֹת ה'.</p>\n<p>אָמַר רַבִּי חִיָּיא, גְּבוּרֹת ה' חָסֵר כָּתוּב, שֶׁהֲרֵי כֻּלָּם כְּלוּלִים בָּזֶה. יַשְׁמִיעַ כָּל תְּהִלָּתוֹ - זוֹהִי שְׁכִינַת זִיו כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב וּתְהִלָּתוֹ מָלְאָה הָאָרֶץ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', שֵׁם הָאֶחָד פִּישׁוֹן וְגוֹ'. הֲרֵי אֵלֶּה נִקְרָאִים בְּשֵׁמוֹת, וְאַרְבָּעָה הַלָּלוּ מֵאוֹתוֹ נָהָר שֶׁיּוֹצֵא הֵם נִמְשָׁכִים. מַה שֵּׁם אוֹתוֹ הַנָּהָר שֶׁיּוֹצֵא? אָמַר רַבִּי שִׁמְעוֹן, שְׁמוֹ יוּבַל, שֶׁכָּתוּב (ירמיה יז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו, וְכָתוּב וְלֹא יָמִישׁ מֵעֲשׂוֹת פֶּרִי. מָה הַטַּעַם לֹא יָמִישׁ? מִשּׁוּם שֶׁעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וְעַל זֶה כָּתוּב (ישעיה נח) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו. וּמִשּׁוּם כָּךְ כָּתוּב יֹצֵא, יוֹצֵא וְאֵינוֹ פוֹסֵק.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים וְגוֹ'. וַיְדַבֵּר, כְּדֵי לְהַכְרִיז דְּבָרִים. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְחִיל לְדַבֵּר, עֶלְיוֹנִים וְתַחְתּוֹנִים הִתְחַלְחֲלוּ, וְיָצְאוּ נִשְׁמוֹתֵיהֶם שֶׁל יִשְׂרָאֵל.</p>\n<p>וְשָׁנִינוּ, אוֹתוֹ דִבּוּר הָיָה טָס מִלְמַעְלָה לְמַטָּה, וְנֶחְקָק בְּאַרְבַּע רוּחוֹת הָעוֹלָם וְעוֹלֶה וְיוֹרֵד. כְּשֶׁעוֹלֶה, נִשְׁאָב מֵהָרֵי אֲפַרְסְמוֹן זַךְ, וְנִשְׁאָב בְּאוֹתוֹ טַל שֶׁלְּמַעְלָה וְסוֹבֵב סְבִיב יִשְׂרָאֵל, וְשָׁבָה בָּהֶם נִשְׁמָתָם, וְסוֹבֵב וְנֶחְקָק בִּמְקוֹמוֹ בְּלוּחוֹת אֶבֶן. וְכֵן כָּל מִלָּה וּמִלָּה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּל מִלָּה וּמִלָּה הָיְתָה מְלֵאָה בְּכָל אוֹתָם טְעָמִים, בְּכָל אוֹתָם דִּבְרֵי גְזֵרוֹת, שָׂכָר וָעֳנָשִׁים, סוֹדוֹת וּסְתָרִים כְּאוֹצָר (כצנצנת) זֶה שֶׁמָּלֵא מִן הַכֹּל.</p>\n<p>וּבְשָׁעָה שֶׁהָיָה יוֹצֵא אוֹתוֹ הַדִּבּוּר, נִרְאָה אֶחָד. וּכְשֶׁהָיָה נֶחְקָק בִּמְקוֹמוֹ, נִרְאוּ בְּאוֹתוֹ הַדִּבּוּר שִׁבְעִים עֲנָפִים שֶׁנִּכְנָסִים לְתוֹכָהּ, וַחֲמִשִּׁים כְּתָרִים חָסֵר אֶחָד מִצַּד זֶה, וַחֲמִשִּׁים חָסֵר אֶחָד מִצַּד הָאַחֵר, כְּמוֹ הַפַּטִּישׁ הַזֶּה בִּזְמַן שֶׁהוּא מַכֶּה בְּסֶלַע, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהכג) וּכְפַטִּישׁ יְפוֹצֵץ סָלַע. וְהָיוּ כָּל יִשְׂרָאֵל רוֹאִים עַיִן בְּעַיִן וְהָיוּ שְׂמֵחִים.</p>\n<p>וְכָל הַדּוֹרוֹת הָאַחֲרוֹנִים הִזְדַּמְּנוּ לְשָׁם, וְכֻלָּם קִבְּלוּ תוֹרָה בְּהַר סִינַי, שֶׁכָּתוּב (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ' וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם. וְכֻלָּם כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכֻלָּם רוֹאִים וּמְקַבְּלִים דְּבָרִים.</p>\n<p>אֱלֹהִים - זוֹ גְבוּרָה. אֵת - שֶׁנִּכְלָל בַּיָּמִין, כְּמוֹ שֶׁשָּׁנִינוּ אֵת הַשָּׁמַיִם שֶׁהוּא יָמִין, וְאֵת הָאָרֶץ שֶׁהוּא שְׂמֹאל, שֶׁכָּתוּב (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם. וְיָמִין זֶה הוּא אֵת. כָּל - לִכְלֹל אֶת כָּל שְׁאָר הַכְּתָרִים. הַדְּבָרִים - מִתְקַשְּׁרִים זֶה בָּזֶה. הָאֵלֶּה - כָּל אוֹתָם טְעָמִים, כָּל אוֹתָם סוֹדוֹת, כָּל אוֹתָם סְתָרִים, גְּזֵרוֹת וָעֳנָשִׁים.</p>\n<p>לֵאמֹר - לִהְיוֹת יְרֻשָּׁה לַכֹּל, שֶׁכָּתוּב (דברים לג) תּוֹרָה צִוָּה לָנוּ מֹשֶׁה מוֹרָשָׁה וְגוֹ'. שֶׁאִם תֹּאמַר, לְגַלּוֹת מַה שֶּׁלֹּא הִצְטָרֵךְ לְגַלּוֹת לְכָל אָדָם - כָּתוּב אָנֹכִי ה' אֱלֹהֶיךְ. כְּמוֹ שֶׁאֲנִי טָמִיר וְנִסְתָּר, כָּךְ יִהְיוּ הַדְּבָרִים הַלָּלוּ טְמִירִים וְנִסְתָּרִים בְּלִבְּךְ.</p>\n<p>דָּבָר אַחֵר וַיְדַבֵּר אֱלֹהִים - אֶחָד. אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר - הֲרֵי חָמֵשׁ דְּרָגוֹת אֲחֵרוֹת. רַבִּי יְהוּדָה אָמַר, וַיְדַבֵּר אֱלֹהִים - גְּבוּרָה. אֵת - יָמִין. כָּל - זֶה וָזֶה (האלה אותם שגתגלו, שכתוב וכל העם ראים את הקולת. דבר אחר, כל). אָמַר רַבִּי יִצְחָק, לִכְלֹל אֶת אַבְרָהָם, שֶׁכָּתוּב וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל.</p>\n<p>הַדְּבָרִים - לִכְלֹל שְׁאָר הַכְּתָרִים הַמְכֻסִּים. הָאֵלֶּה - אֵלּוּ שֶׁהִתְגַּלּוּ, וְכָתוּב וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. לֵאמֹר - זֶהוּ שֶׁכָּתוּב (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ. וְכָתוּב (ירמיה ג) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, לָמָּה נִתְּנָה תוֹרָה בְּאֵשׁ וַחֲשֵׁכָה, שֶׁכָּתוּב וְהָהָר בֹּעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם חֹשֶׁךְ עָנָן וַעֲרָפֶל. שֶׁכָּל מִי שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה, יִנָּצֵל מֵאֵשׁ אַחֶרֶת שֶׁל הַגֵּיהִנָּם וּמֵהַחֹשֶׁךְ שֶׁמַּחְשִׁיכִים כָּל שְׁאָר הָעַמִּים לְיִשְׂרָאֵל, שֶׁבִּזְכוּת אַבְרָהָם נִצְּלוּ יִשְׂרָאֵל מֵאֵשׁ הַגֵּיהִנָּם.</p>\n<p>שֶׁשָּׁנִינוּ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, כָּל זְמַן שֶׁבָּנֶיךְ יִשְׁתַּדְּלוּ בַתּוֹרָה, הֵם יִנָּצְלוּ מֵאֵלֶּה, וְאִם לֹא - הֲרֵי אֵשׁ הַגֵּיהִנָּם תִּשְׁלֹט בָּהֶם וְיִשְׁתַּעְבְּדוּ בֵּין הָעַמִּים. אָמַר לוֹ, בִּשְׁנֵי קְשָׁרִים לֹא יָקוּמוּ הַדְּבָרִים, אֶלָּא אִם נוֹחַ לְפָנֶיךְ - שֶׁיִּנָּצְלוּ מֵאֵשׁ הַגֵּיהִנָּם, וְיִשְׁתַּעְבְּדוּ בֵּין הָעַמִּים עַד שֶׁיָּשׁוּבוּ אֵלֶיךְ. אָמַר לוֹ, יָפֶה זֶה וַדַּאי. זֶהוּ שֶׁכָּתוּב (דברים לב) אִם לֹא כִּי צוּרָם מְכָרָם. מִיהוּ צוּרָם? זֶהוּ אַבְרָהָם, שֶׁכָּתוּב (ירמיה ג) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם. וַה' הִסְגִּירָם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִסְכִּים עַל יָדוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם עַד הַיּוֹם שֶׁנִּתְּנָה בּוֹ תּוֹרָה הָיוּ חֲמִשִּׁים יוֹם, מָה הַטַּעַם? אָמַר רַבִּי יְהוּדָה, מִשּׁוּם אוֹתָן שְׁנוֹת הַיּוֹבֵל, שֶׁכָּתוּב (ויקרא כה) וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, אוֹתוֹ הַיּוֹבֵל הוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם. וְאִם תֹּאמַר שֶׁיּוֹבֵל מַמָּשׁ, אֶלָּא מִצַּד הַיּוֹבֵל זֶה הָיָה, וּמִצַּד הַיּוֹבֵל הִתְעוֹרֵר דִּין עַל הַמִּצְרִים, וְלָכֵן חֲמִשִּׁים אֵלֶּה הָיוּ שֶׁל הַיּוֹבֵל.</p>\n<p>שָׁנִינוּ, כְּנֶגֶד זֶה חֲמִשִּׁים פְּעָמִים נֶאֱמַר וְנִזְכַּר בַּתּוֹרָה הַנְהָגוֹת מִצְרַיִם, וְכֻלָּם הֵם שְׁבָחִים: אֲשֶׁר הוֹצֵאתִיךְ. וַיֹּצִאֲךְ. כִּי בְּיָד חֲזָקָה הוֹצִיאֲךְ. וְכָל הַפְּעָמִים הֵם חֲמִשִּׁים, וְלֹא יוֹתֵר. מִשּׁוּם שֶׁהַכֹּל הִתְעַטֵּר בַּיּוֹבֵל. וּמִצַּד הַיּוֹבֵל הַכֹּל בָּא. וְלָכֵן תּוֹרָה שֶׁבָּאָה מִגְּבוּרָה הִתְעַטְּרָה בַּיָּמִין, שֶׁכָּתוּב (דברים לג) כִּי מִימִינוֹ אֵשׁ דָּת לָמוֹ. וְשָׁנִינוּ, חֲמִשָּׁה קוֹלוֹת הָיוּ, וְכֻלָּם נִרְאוּ בָהֶם וְנִכְלְלוּ בָהֶם וְהִתְעַטְּרוּ בָזֶה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתוֹ זְמַן שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, הַיּוֹבֵל הַזֶּה עִטֵּר בְּעַטְרוֹתָיו אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמֶלֶךְ שֶׁהִתְעַטֵּר בְּתוֹךְ חֵילוֹ, שֶׁכָּתוּב (שירג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. מִי זוֹ אִמּוֹ? זֶה הַיּוֹבֵל, וְהַיּוֹבֵל הִתְעַטֵּר בְּשִׂמְחָה בְּאַהֲבָה בִּשְׁלֵמוּת, שֶׁכָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה. מִי זוֹ אֵם הַבָּנִים? אָמַר רַבִּי שִׁמְעוֹן, זֶה הַיּוֹבֵל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, עַל זֶה כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ. מִי זֶה אָבִיךְ וְאִמֶּךְ? אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁבֵּאֲרוּהָ בְּסִפְרָא דִצְנִיעוּתָא, שֶׁכָּתוּב עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. אוֹי לְמִי שֶׁמְּגַלֶּה עֶרְוָתָם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה בְּהַר סִינַי, הִזְדַּעֲזַע הָהָר, וּבְשָׁעָה שֶׁסִּינַי הִזְדַּעֲזַע, כָּל שְׁאָר הָרֵי הָעוֹלָם הִזְדַּעְזְעוּ וְהָיוּ עוֹלִים וְיוֹרְדִים, עַד שֶׁהוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא יָדוֹ עֲלֵיהֶם וְהִתְיַשְּׁבוּ, וְקוֹל יוֹצֵא וּמַכְרִיז, (תהלים קיד) מַה לְּךְ הַיָּם כִּי תָנוּס הַיַּרְדֵּן תִּסֹּב לְאָחוֹר, הֶהָרִים תִּרְקְדוּ כְאֵילִים וְגוֹ'.</p>\n<p>וְהֵם שָׁבִים וְאוֹמְרִים, מִלִּפְנֵי אָדוֹן חוּלִי אָרֶץ. אָמַר רַבִּי יִצְחָק, מִלִּפְנֵי אָדוֹן - זוֹ הָאֵם, שֶׁכָּתוּב אֵם הַבָּנִים שְׂמֵחָה. חוּלִי אָרֶץ - זוֹ הָאֵם הַתַּחְתּוֹנָה. מִלִּפְנֵי אֱלוֹהַּ יַעֲקֹב - זֶהוּ הָאָב, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. וְעַל זֶה כָּתוּב בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ.</p>\n<p>מַה זֶּה בָּעֲטָרָה? אָמַר רַבִּי יִצְחָק, כַּכָּתוּב (שמואל א כג) וְשָׁאוּל וַאֲנָשָׁיו עֹטְרִים אֶל דָּוִד. מִשּׁוּם שֶׁמִּתְעַטֵּר בְּלָבָן וּבְאָדם וּבְיָרֹק, בְּכָל הַגְּוָנִים שֶׁכֻּלָּם כְּלוּלִים בּוֹ וּמֻקָּפִים בּוֹ. אָמַר רַבִּי יְהוּדָה, בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ, מִי זוֹ הָעֲטָרָה? שֶׁכָּתוּב (ישעיהמט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, וְכָתוּב (שםס) וּבֵית תִּפְאַרְתִּי אֲפָאֵר.</p>\n<p>אָמַר רַבִּי יִצְחָק, תּוֹרָה נִתְּנָה בְּאֵשׁ שְׁחֹרָה עַל גַּבֵּי אֵשׁ לְבָנָה, לִכְלֹל יָמִין בִּשְׂמֹאל, וּשְׂמֹאל שֶׁחוֹזֵר לִהְיוֹת יָמִין, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, בְּשָׁעָה שֶׁעָשָׁן שֶׁל סִינַי הָיָה יוֹצֵא, עוֹלֶה אֵשׁ, וּמִתְעַטֵּר בְּאוֹתוֹ עָשָׁן בְּגָלוּי כְּאֶשְׁכּוֹל הַזֶּה, וְעוֹלֶה וְיוֹרֵד, וְכָל הָרֵיחוֹת וְהַבְּשָׂמִים שֶׁל גַּן עֵדֶן הָיָה מַעֲלֶה אוֹתוֹ עָשָׁן בְּמַרְאֶה שֶׁל לָבָן וְאָדם וְשָׁחֹר. זֶהוּ שֶׁכָּתוּב (שיר ג) מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל.</p>\n<p>אוֹתוֹ עָשָׁן מֶה הָיָה? אָמַר רַבִּי יִצְחָק, שְׁכִינָה שֶׁנִּגְלְתָה לְשָׁם, שֶׁנֶּאֱמַר מִי זאת עֹלָה מִן הַמִּדְבָּר כְּתִמְרוֹת עָשָׁן. אָמַר רַבִּי יְהוּדָה, לָמָּה לָךְ כָּל זֶה, הֲרֵי פָּסוּק שָׁלֵם הוּא, שֶׁכָּתוּב וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ וַיַּעַל עֲשָׁנוֹ כְּעֶשֶׁן הַכִּבְשָׁן. אַשְׁרֵי הָעָם שֶׁרָאוּ אֶת זֶה וְיָדְעוּ אֶת זֶה.</p>"],[9522011647,"<p>אָמַר רַבִּי חִיָּיא, כְּשֶׁנֶּחְקְקוּ הָאוֹתִיּוֹת בְּלוּחוֹת הָאֶבֶן, הָיוּ נִרְאִים מִשְּׁנֵי צְדָדִים - מִצַּד זֶה וּמִצַּד זֶה, וְהַלּוּחוֹת הָיוּ מֵאֶבֶן סַנְפִּירִינוֹן, וְנֶחְקְקוּ וְנִתְכַּסּוּ בְּאֵשׁ לְבָנָה, וְהָאוֹתִיּוֹת הָיוּ מֵאֵשׁ שְׁחֹרָה, וַחֲקוּקִים בִּשְׁנֵי צְדָדִים - מִצַּד זֶה וּמִצַּד זֶה.</p>\n<p>אָמַר רַבִּי אַבָּא, הַלּוּחוֹת הָיוּ בְּעֵינֵיהֶם, וְהָאוֹתִיּוֹת הָיוּ טָסוֹת וְנִרְאוֹת בִּשְׁנֵי סוּגֵי אֵשׁ - אֵשׁ לְבָנָה וְאֵשׁ שְׁחֹרָה, לְהֵרָאוֹת כְּאֶחָד יָמִין וּשְׂמֹאל, שֶׁכָּתוּב (משליג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וְגוֹ'. וַהֲרֵי כָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ. אֶלָּא מִצַּד הַגְּבוּרָה זֶה הָיָה, וְנִכְלֶלֶת בַּיָּמִין. וְלָכֵן אֵשׁ לְבָנָה וְאֵשׁ שְׁחֹרָה.</p>\n<p>שָׁנִינוּ, כָּתוּב (שמות לב) וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְגוֹ'. (מעשה אלהים ודאי) אָמַר רַבִּי יְהוּדָה, כָּתוּב וְהַלֻּחֹת, אֶחָד. שְׁנַיִם הָיוּ וְנִרְאִים אֶחָד. וְעֶשֶׂר אֲמִירוֹת חֲקוּקוֹת בָּהֶם, חָמֵשׁ כְּלוּלוֹת בְּחָמֵשׁ, לִהְיוֹת הַכֹּל יָמִין. מַעֲשֵׂה אֱלֹהִים הֵמָּה וַדַּאי.</p>\n<p>רַבִּי יִצְחָק אָמַר, שֶׁל סַנְפִּירִינוֹן הָיוּ, וּשְׁתֵּי אֲבָנִים הָיוּ, וְהָאֲבָנִים הָיוּ סְתוּמוֹת. נָשַׁב הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרוּחַ, וְהִתְפַּשְּׁטוּ וְנֶחְקְקוּ שְׁנֵי לוּחוֹת. רַבִּי יְהוּדָה אָמַר, כְּעֵין סַנְפִּירִינוֹן הָיוּ, (שהיתה אבן טובה) מַשְׁמָע שֶׁכָּתוּב מַעֲשֵׂה אֱלֹהִים הֵמָּה.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, סַנְפִּירִינוֹן זֶה, שֶׁהִיא אֶבֶן טוֹבָה וּכְבֵדָה מִשְּׁאָר הָאֲבָנִים, אֵינָם מַעֲשֵׂה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? אָמַר לוֹ, בַּמֶּה בֵּאַרְנוּ מַעֲשֵׂה אֱלֹהִים הֵמָּה? הֵמָּה דַּוְקָא. אֶלָּא בֹּא וּרְאֵה, כָּתוּב וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים. הַלֻּחֹת כָּתוּב, וְלֹא כָתוּב וְהָאֲבָנִים מַעֲשֵׂה אֱלֹהִים הֵמָּה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל אֶחָד הוּא, אֲבָל שְׁנֵי הַלּוּחוֹת הַלָּלוּ, עַד שֶׁלֹּא נִבְרָא הָעוֹלָם הָיוּ, וְנִתְעַלּוּ מֵעֶרֶב שַׁבָּת, וְעָשָׂה אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַעֲשָׂיו הָיוּ.</p>\n<p>מִמָּה הֵם נַעֲשׂוּ? שָׁנִינוּ, מֵאוֹתוֹ הַטַּל הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ מִן הָעַתִּיק הַקָּדוֹשׁ. וּכְשֶׁשּׁוֹפֵעַ וְנִמְשָׁךְ לִשְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁתֵּי טִפּוֹת כְּפוֹר מֵהֶם וְנִגְלְדוּ, וְנַעֲשׂוּ שְׁתֵּי אֲבָנִים יְקָרוֹת. נָשַׁב בָּהֶן, וְהִתְפַּשְּׁטוּ לִשְׁנֵי לוּחוֹת. זֶהוּ שֶׁכָּתוּב מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא, כְּמוֹ שֶׁכָּתוּב (שמות לב) כְּתוּבִים בְּאֶצְבַּע אֱלֹהִים.</p>\n<p>שָׁנִינוּ, אֶצְבַּע אֱלֹהִים - אוֹתָהּ אֶצְבַּע עוֹלָה לַעֲשָׂרָה, כְּמוֹ שֶׁנֶּאֱמַר אֶצְבַּע אֱלֹהִים הִיא. וְכָל אֶצְבַּע וְאֶצְבַּע עוֹלָה לַעֲשָׂרָה, עַד שֶׁנַּעֲשֵׂית יָד שְׁלֵמָה, שֶׁכָּתוּב (שמות יד) וירא ישראל את היד הגדלה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, חָרוּת עַל הַלֻּחֹת - נְקוּבִים הָיוּ הָאֲבָנִים וְנִרְאוּ מִשְּׁנֵי צְדָדִים, חָרוּת חֲקִיקָה שֶׁל חֲקִיקוֹת. אָמַר רַבִּי אַבָּא, מִצַּד זֶה נִרְאֶה הַצַּד הָאַחֵר, וְנִקְרָא מִכָּאן מַה שֶּׁכָּתוּב בַּצַּד הָאַחֵר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, בְּנֵס הָיוּ כְתוּבִים, שֶׁכָּל בְּנֵי הָאָדָם הָיוּ אוֹמְרִים וּמְעִידִים שֶׁהֲרֵי מִכְתַּב אֱלֹהִים הוּא וַדַּאי, שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם לֹא יָכְלוּ לָדַעַת אוֹתָם כְּמוֹ שֶׁהָיוּ.</p>\n<p>לְדַעִִתָּם שֶׁל הָאוֹמְרִים נְקוּבִים הָיוּ, הַאִם כָּתוּב חָרוּת בַּלֻּחֹת? עַל הַלֻּחֹת כָּתוּב. אֶלָּא כָּךְ שָׁנִינוּ, חֲמִשָּׁה קוֹלוֹת הֵם לְיָמִין וַחֲמִשָּׁה לִשְׂמֹאל, וְאוֹתָם שֶׁל הַשְּׂמֹאל כְּלוּלִים בַּיָּמִין. וּמֵהַיָּמִין נִרְאוּ אוֹתָם שֶׁבַּשְּׂמֹאל, וְכָאן הַכֹּל הוּא יָמִין, וְנִכְלְלוּ אֵלֶּה בְּאֵלֶּה, מַה שֶּׁהָיָה בְּצַד זֶה נִרְאֶה לַצַּד הָאַחֵר, וְקוֹרְאִים אֶת אוֹתָם הָאוֹתִיּוֹת. שֶׁהֲרֵי שָׁנִינוּ, הַשְּׂמֹאל הָפַךְ לִהְיוֹת יָמִין, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ, וּמִשּׁוּם כָּךְ מִכְתַּב אֱלֹהִים הוּא וַדַּאי.</p>\n<p>הָכֵיצַד, ? מַה שֶּׁהָיָה בַּצַּד הַזֶּה הָיָה קוֹרֵא בָּזֶה, אָנֹכִי ה' אֱלֹהֶיךְ. וּמֵהָאוֹתִיּוֹת הַלָּלוּ הָיָה רוֹאֶה וְקוֹרֵא לֹא תִרְצַח. הָיָה קוֹרֵא לֹא יִהְיֶה לְךְ, וְהָיָה רוֹאֶה וְקוֹרֵא לֹא תִנְאָף. וְהָיָה קוֹרֵא לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא. וְהָיָה רוֹאֶה וְקוֹרֵא לֹא תִגְנֹב. וְהַכֹּל מִצַּד זֶה. וְכָךְ לְכֻלָּם, וְאָז מִצַּד הָאַחֵר, וְכֻלָּם כְּלוּלִים זֶה בָּזֶה כְּגוֹן זֶה. זֶהוּ שֶׁכָּתוּב (שםלג) מִכְתַּב אֱלֹהִים הוּא. מִכְתַּב אֱלֹהִים הוּא וַדַּאי.</p>\n<p>וַיֵּרֶד מֹשֶׁה אֶל הָעָם וַיֹּאמֶר אֲלֵהֶם. רַבִּי יוֹסֵי אָמַר, מַהִי הָאֲמִירָה הַזּוֹ שֶׁכָּתוּב וַיֹּאמֶר אֲלֵהֶם, וְלֹא כָתוּב מָה אָמַר? אָמַר רַבִּי יִצְחָק, בֹּא וּרְאֵה, דֶּרֶךְ הָעוֹלָם הוּא, כְּשֶׁבָּאָה שִׂמְחָה לָאָדָם אוֹ כְּשֶׁבָּא צַעַר - כְּשֶׁעֲדַיִן לֹא יוֹדֵעַ מִמֶּנּוּ, לֹא יָכוֹל לִסְבֹּל, שֶׁהֲרֵי לִבּוֹ פּוֹרֵחַ לְשָׁעָה. וּכְשֶׁיּוֹדֵעַ מִמֶּנּוּ, עוֹמֵד בְּקִיּוּמוֹ וְיָכוֹל לִסְבּל. כָּל שֶׁכֵּן כָּאן, (וכאן אינו כך) שֶׁהֲרֵי מֹשֶׁה אָמַר לָהֶם כָּל מַה שֶּׁהָיָה אַחַר כָּךְ וְחִזֵּק לִבָּם בִּדְבָרִים, וְלֹא יָכְלוּ לִסְבֹּל. כָּל שֶׁכֵּן אִם לֹא הָיָה אוֹמֵר לָהֶם דָּבָר. וּמִשּׁוּם כָּךְ וַיֹּאמֶר אֲלֵהֶם בַּתְּחִלָּה, וְחִזֵּק לִבָּם, וְאַחַר כָּךְ וַיְדַבֵּר אֱלֹהִים.</p>\n<p>וְעִם כָּל זֶה לֹא יָכְלוּ לִסְבֹּל, שֶׁהֲרֵי שָׁנִינוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, כְּשֶׁשָּׁמְעוּ דְבָרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, פָּרְחָה נִשְׁמָתָם, וְעָלְתָה נִשְׁמָתָם שֶׁל יִשְׂרָאֵל עַד כִּסֵּא כְבוֹדוֹ לְהִדָּבֵק שָׁם.</p>\n<p>אָמְרָה תוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי לְחִנָּם הָיִיתִי מֵאַלְפַּיִם שָׁנִים טֶרֶם שֶׁנִּבְרָא הָעוֹלָם?! לְחִנָּם כָּתוּב בָּהּ (ויקראיז) וְאִישׁ אִישׁ מִבְּנֵי יִשְׂרָאֵל וּמִן הַגֵּר הַגָּר בְּתוֹכָם, (שמות ל) וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר, (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים?! אֵיפֹה הֵם בְּנֵי יִשְׂרָאֵל? בְּאוֹתָהּ שָׁעָה הֶחֱזִירָה הַתּוֹרָה אֶת נִשְׁמוֹת יִשְׂרָאֵל כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. הַתּוֹרָה חִזְּקָה וְאָחֲזָה בְּנִשְׁמוֹתֵיהֶם לְהַחֲזִיר אוֹתָן לְיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (תהלים יט) תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ. מְשִׁיבַת נֶפֶשׁ מַמָּשׁ.</p>\n<p>שָׁנִינוּ, כָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ, כְּמוֹ שֶׁכָּתוּב (מלכים א י) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. רַבִּי אַבָּא אָמַר, שֶׁהַלְּבָנָה עָמְדָה בִּשְׁלֵמוּת, שֶׁשָּׁנִינוּ שֶׁבִּימֵי שְׁלֹמֹה עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת.</p>\n<p>אֵימָתַי בִּשְׁלֵמוּת? (שנינו, כתוב ותרב חכמת שלמה וגו'. מהו ותרב, ' אמר רבי אבא, שעמדה הלבנה בשלמותה. מהו בשלמותה, ') שֶׁעָמְדָה בַּחֲמִשָּׁה עָשָׂר, כְּמוֹ שֶׁשָּׁנִינוּ, אַבְרָהָם. יִצְחָק. יַעֲקֹב. יְהוּדָה. פֶּרֶץ. חֶצְרוֹן. רָם. עַמִּינָדָב. נַחְשׁוֹן. שַׂלְמוֹן. בּעַז. עוֹבֵד. יִשַׁי. דָּוִד. שְׁלֹמֹה. כְּשֶׁבָּא שְׁלֹמֹה עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ. וְכָתוּב שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בִּימֵי צִדְקִיָּה עָמְדָה הַלְּבָנָה בִּפְגָם וְנִפְגְּמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יג) וְיָרֵחַ לֹא יַגִּיהַּ אוֹרוֹ. שֶׁשָּׁנִינוּ, בִּימֵי צִדְקִיָּה נִפְגְּמָה הַלְּבָנָה וְחָשְׁכוּ פְנֵיהֶם שֶׁל יִשְׂרָאֵל.</p>\n<p>צֵא וַחֲשֹׁב, רְחַבְעָם. אֲבִיָּה. אָסָא. יְהוֹשָׁפָט. יְהוֹרָם. אֲחַזְיָהוּ. יוֹאָשׁ. אֲמַצְיָהוּ. עֻזִּיָּהוּ. יוֹתָם. אָחָז. יְחִזְקִיָּהוּ. מְנַשֶּׁה. אָמוֹן. יֹאשִׁיָּהוּ. צִדְקִיָּהוּ. וּכְשֶׁבָּא צִדְקִיָּהוּ, נִפְגְּמָה הַלְּבָנָה וְעָמְדָה עַל פְּגָם, שֶׁכָּתוּב (ירמיה נב) וְאֶת עֵינֵי צִדְקִיָּה עִוֵּר. בְּאוֹתוֹ זְמַן (איכהב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. אֶרֶץ זוֹ הָעָבְרָה מִלִּפְנֵי שָׁמַיִם וְהִתְרַחֲקָה מִמֶּנּוּ, וְנֶחְשְׁכָה הָאָרֶץ הַזּוֹ. (כלומר, שעמדה הלבנה בפגימותה).</p>\n<p>שָׁנִינוּ, בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, הִתְחִילָה הַלְּבָנָה לְהָאִיר, שֶׁכָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד. מַה זֶּה וַיֵּרַד? שֶׁקֵּרַב הַשֶּׁמֶשׁ לַלְּבָנָה, וְהִתְחִילָה לְהָאִיר הַלְּבָנָה, שֶׁכָּתוּב (במדבר כ) דֶּגֶל מַחֲנֵה יְהוּדָה מִזְרָחָה.</p>\n<p>בְּהַר סִינַי הִתְמַנָּה יְהוּדָה כְּשַׁלִּיט בַּמַּלְכוּת, שֶׁכָּתוּב (הושע יב) וִיהוּדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. (רבי יצחק אמר מכאן, ויהודה עד רד עם אל, השלטון היה בשעה שהאל הזה שולטת מלכותו על הר סיני, באותה שעה מלכותו של יהודה) מַה זֶּה וְעִם קְדוֹשִׁים נֶאֱמָן? כְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ, נֶאֱמָן הָיָה יְהוּדָה לְקַבֵּל מַלְכוּת, וְהִתְחִילָה הַלְּבָנָה לְהָאִיר.</p>"],[9522011648,"<p>אָנֹכִי ה' אֱלֹהֶיךְ אֲשֶׁר הוֹצֵאתִיךְ וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (משלי א) שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ. שְׁמַע בְּנִי מוּסַר אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִי זוֹ כְּנֶסֶת יִשְׂרָאֵל? זוֹ בִּינָה, כְּמוֹ שֶׁכָּתוּב לְהָבִין אִמְרֵי בִינָה.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מוּסַר אָבִיךְ - זוֹ הִיא חָכְמָה. וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ - זוֹ הִיא בִּינָה. רַבִּי יִצְחָק אָמַר, זֶה וָזֶה דָּבָר אֶחָד הִתְפָּרְשׁוּ. שֶׁשָּׁנִינוּ, תּוֹרָה יָצְאָה מֵחָכְמָה שֶׁל מַעְלָה. רַבִּי יוֹסֵי אָמַר, מִבִּינָה יָצְאָה, שֶׁכָּתוּב לְהָבִין אִמְרֵי בִינָה, וְכָתוּב וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, תּוֹרָה נִכְלְלָה מֵחָכְמָה וּבִינָה, שֶׁכָּתוּב שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ. רַבִּי אַבָּא אָמַר, בַּכֹּל הִיא נִכְלֶלֶת. שֶׁכֵּיוָן שֶׁנִּכְלֶלֶת בִּשְׁנֵי אֵלֶּה, הִיא נִכְלֶלֶת בַּכֹּל - בְּחֶסֶד, בְּדִין וּבְרַחֲמִים. בְּכֻלָּם הַשְּׁלֵמוּת שֶׁהַדָּבָר צָרִיךְ. אִם הַמֶּלֶךְ וְהַגְּבִירָה מַסְכִּימִים - הַכֹּל מַסְכִימִים. בְּמָקוֹם שֶׁאֵלֶּה נִמְצָאִים - כֻּלָּם נִמְצָאִים.</p>\n<p>רַבִּי יוֹסֵי אָמַר, אָנֹכִי - זוֹ הַשְּׁכִינָה, כְּמוֹ שֶׁכָּתוּב (בראשית מו) אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה. ה' אֱלֹהֶיךְ. (הכלעולה למעלה להיות הכל אחד) (זו כנסת ישראל, שכתוב ואל תטש תורת אמך) רַבִּי יִצְחָק אָמַר, אָנֹכִי - זוֹ הַשְּׁכִינָה, וּמַפְסִיק הַטַּעַם, כְּמוֹ שֶׁנֶּאֱמַר אָנֹכִי עֵשָׂו בְּכוֹרֶךְ. ה' אֱלֹהֶיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁכָּתוּב (דברים ד) מִן הַשָּׁמַיִם הִשְׁמִיעֲךְ אֶת קֹלוֹ. וְכָתוּב אַתֶּם רְאִיתֶם כִּי מִן הַשָּׁמַיִם דִּבַּרְתִּי עִמָּכֶם. מִן הַשָּׁמַיִם (מןהשמים ממש, זה הקדוש ברוך הוא).</p>\n<p>אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם. אֲשֶׁר - מָקוֹם שֶׁהַכֹּל מְאַשְּׁרִים אוֹתוֹ. הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם - זֶה יוֹבֵל, כְּמוֹ שֶׁשָּׁנִינוּ, מִצַּד הַיּוֹבֵל יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וּמִשּׁוּם כָּךְ חֲמִשִּׁים פְּעָמִים נִזְכְּרָה יְצִיאַת מִצְרַיִם בַּתּוֹרָה. חֲמִשִּׁים יָמִים לְקַבָּלַת הַתּוֹרָה. חֲמִשִּׁים יָמִים לְחֵרוּת הָעֲבָדִים.</p>\n<p>מִבֵּית עֲבָדִים - כְּמוֹ שֶׁכָּתוּב (שמות יב) הִכָּה כָל בְּכוֹר בְּאֶרֶץ מִצְרַיִם. וְשָׁנִינוּ, הַכְּתָרִים הַתַּחְתּוֹנִים הַלָּלוּ שֶׁהַמִּצְרִים בָּטְחוּ בָהֶם. כְּמוֹ שֶׁיֵּשׁ בַּיִת לְמַעְלָה - יֵשׁ בַּיִת לְמַטָּה. בַּיִת קָדוֹשׁ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת - בַּיִת תַּחְתּוֹן לְמַטָּה שֶׁאֵינוֹ קָדוֹשׁ, כְּמוֹ שֶׁכָּתוּב מִבֵּית עֲבָדִים.</p>\n<p>שָׁנִינוּ, בְּשָׁעָה שֶׁנֶּאֱמַר אָנֹכִי, כָּל אוֹתָן מִצְווֹת הַתּוֹרָה שֶׁנֶּאֶחְזוּ בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן בְּצַד (זה), כֻּלָּם הָיוּ כְּלוּלוֹת בַּדָּבָר הַזֶּה.</p>\n<p>כְּמוֹ שֶׁשָּׁנִינוּ, כָּל מִצְווֹת הַתּוֹרָה אֲחוּזוֹת בְּגוּף הַמֶּלֶךְ, (במלך הקדוש העליון) מֵהֶן בְּרֹאשׁ הַמֶּלֶךְ, וּמֵהֶן בַּגּוּף, וּמֵהֶן בִּידֵי הַמֶּלֶךְ, וּמֵהֶן בְּרַגְלָיו, וְאֵין מִי שֶׁיּוֹצֵא מִגּוּף הַמֶּלֶךְ הַחוּצָה. וְלָכֵן מִי שֶׁפָּשַׁע בְּמִצְוָה אַחַת שֶׁל הַתּוֹרָה, כְּמִי שֶׁפָּשַׁע בְּגוּף הַמֶּלֶךְ, כְּמוֹ שֶׁכָּתוּב (ישעיה ס) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי, בִּי מַמָּשׁ. אוֹי לָרְשָׁעִים שֶׁעוֹבְרִים עַל מִצְווֹת הַתּוֹרָה וְלֹא יוֹדְעִים מַה הֵם עוֹשִׂים.</p>\n<p>שֶׁאָמַר רַבִּי שִׁמְעוֹן, אוֹתוֹ מָקוֹם שֶׁהוּא חָטָא אֵלָיו, אוֹתוֹ מָקוֹם מַמָּשׁ מְגַלֶּה חֶטְאוֹ. (ואמר רבי שמעון, הקדוש ברוך הוא ממש מגלה חטאו) חָטָא בַּקָּדוֹשׁ-בָּרוּךְ-הוּא - הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה חֶטְאוֹ, שֶׁכָּתוּב (איוב כ) יְגַלּוּ שָׁמַיִם עֲונוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. יְגַלּוּ שָׁמַיִם עֲונוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶרֶץ מִתְקוֹמָמָה לוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (זו כנסת ישראל).</p>\n<p>שָׁנִינוּ, שָׁמַיִם מְגַלִּים חֶטְאוֹ שֶׁל אָדָם, וּבְשָׁעָה שֶׁהוּא מְגַלֶּה חֶטְאוֹ, אֶרֶץ עוֹשָׂה דִּין הָאָדָם, שֶׁכָּתוּב וְאֶרֶץ מִתְקוֹמָמָה לוֹ, לַעֲשׂוֹת בּוֹ דִּין. אָמַר רַבִּי יוֹסֵי, שָׁנִינוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה, הָאֵם וְהַבָּנִים נִמְצְאוּ בִשְׁלֵמוּת, שֶׁכָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה.</p>\n<p>אָנֹכִי ה' אֱלֹהֶיךְ. אָנֹכִי, כְּמוֹ שֶׁשָּׁנִינוּ, בַּת הָיְתָה לוֹ לְאַבְרָהָם אָבִינוּ. הִיא שְׁכִינָה, וְזוֹ בַּת. ה' אֱלֹהֶיךְ, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. וְכָתוּב (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. הִנֵּה בֵּן.</p>\n<p>אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם, שֶׁכָּתוּב (ויקרא כה) יוֹבֵל הִוא קֹדֶשׁ תִּהְיֶה לָכֶם. וְכָתוּב אֵם הַבָּנִים שְׂמֵחָה. וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר. הֲרֵי אֵם וּבָנִים. יוֹשֶׁבֶת הָאֵם, יוֹשְׁבִים הַבָּנִים. (והעולמות) כֻּלָּם בְּשִׂמְחָה בִּשְׁלֵמוּת, וְעַל זֶה כָּתוּב אֵם הַבָּנִים שְׂמֵחָה. נֶעֶבְרָה הָאֵם - כֻּלָּם נֶעֱבָרִים מִמְּקוֹמָם. וְכָתוּב (דבריםכב) לֹא תִקַּח הָאֵם עַל הַבָּנִים. וְשָׁנִינוּ, לֹא יַעֲשֶׂה אָדָם חֲטָאִים לְמַטָּה, כְּדֵי שֶׁתַּעֲבֹר הָאֵם מֵעַל הַבָּנִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, הַכֹּל הַקָּדוֹשׁ בָּרוּךְ הוּא. הַכֹּל הוּא. הַכֹּל אֶחָד. וְהַדְּבָרִים הַלָּלוּ הִתְגַּלּוּ לְקוֹצְרֵי הַשָּׂדֶה. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, כָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וְכָתוּב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. בַּמֶּה בֵּאַרְנוּ פְּסוּקִים אֵלּוּ, הֲרֵי שָׁנִינוּ שֶׁשְּׁנֵיהֶם נִבְרְאוּ כְאֶחָד? מְלַמֵּד שֶׁנָּטָה הַקָּדוֹשׁ בָּרוּךְ הוּא קַו יְמִינוֹ וּבָרָא הַשָּׁמַיִם, וְנָטָה קַו שְׂמֹאלוֹ וּבָרָא אֶת הָאָרֶץ. בַּתְּחִלָּה אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וְאַחַר כָּךְ אֶרֶץ וְשָׁמָיִם.</p>\n<p>שָׁנִינוּ, כָּתוּב (הושע ב) בַּיּוֹם הַהוּא אֶעֱנֶה נְאֻם ה' אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. אֶעֱנֶה אֶת הַשָּׁמָיִם - שָׁמַיִם מַמָּשׁ, שֶׁכָּתוּב (ישעיה סו) הַשָּׁמַיִם כִּסְאִי. וְהֵם יַעֲנוּ אֶת הָאָרֶץ - הָאָרֶץ מַמָּשׁ, שֶׁכָּתוּב וְהָאָרֶץ הֲדם רַגְלָי. שָׁמַיִם - שָׁמַיִם הָעֶלְיוֹנִים. וְאֶרֶץ - הָאָרֶץ הָעֶלְיוֹנָה. שֶׁשָּׁנִינוּ, כְּשֶׁהִתְתַּקֵּן שָׁמַיִם זֶה בְּתִקּוּנָיו, (התתקן) כְּנֶגֶד אֶרֶץ זוֹ, וּתְשׁוּקָתוֹ כְּנֶגְדָּהּ בְּדַרְגָּה אַחַת שֶׁנִּקְרֵאת צַדִּיק, כְּמוֹ שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, וְנִדְבָּק בָּאָרֶץ הַזּוֹ.</p>\n<p>וּמֵרֹאשׁ הַמֶּלֶךְ עַד אוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה הַצַּדִּיק הַזֶּה, בָּא נָהָר אֶחָד קָדוֹשׁ, שֶׁמֶן מִשְׁחָה, וּמַטִּיל בְּרֹב תְּשׁוּקָה בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, וְהָאָרֶץ הַזּוֹ נוֹטֶלֶת הַכֹּל, וְאַחַר כָּךְ מֵהָאָרֶץ הַזּוֹ הַכֹּל נִזּוֹנִים, עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ הַזָּכָר הַזֶּה כְּשֶׁתְּשׁוּקָתוֹ לְהִדָּבֵק בִּנְקֵבָה, שֶׁמּוֹצִיא זֶרַע שֶׁל רְבִיָּה מֵרֹאשׁ הַמֹּחַ בְּאוֹתָהּ אַמָּה וּמַטִּיל בַּנְּקֵבָה וּמִמֶּנּוּ הַנְּקֵבָה מִתְעַבֶּרֶת. נִמְצָא שֶׁכָּל אֵיבְרֵי הַגּוּף כֻּלָּם נִדְבָּקִים בַּנְּקֵבָה, וְהַנְּקֵבָה אוֹחֶזֶת הַכֹּל. כְּדֻגְמָה זוֹ שָׁנִינוּ, כָּל הַמַּשְׁלִים לַעֲשָׂרָה רִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת, נוֹטֵל שְׂכַר כֻּלָּם. רַבִּי יוֹסֵי אָמַר, כְּנֶגֶד כֻּלָּם.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּתוּב (שמואל ב כב) וַיֵּט שָׁמַיִם וַיֵּרַד, וְכָתוּב יֵרֵד ה' לְעֵינֵי כָל הָעָם עַל הַר סִינָי. (לא גורסים תנא) וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן יָרַד? אִם תֹּאמַר שֶׁיָּרַד לְסִינַי, הֲרֵי כָּתוּב עַל הַר סִינָי, וְלֹא כָתוּב בְּהַר סִינַי?</p>\n<p>אֶלָּא וַיֵּט שָׁמַיִם וַיֵּרַד, לְאָן יָרַד? אָמַר רַבִּי יוֹסֵי (אמר רבי יהודה אמר רבי חייא), יָרַד בְּדַרְגוֹתָיו מִדַּרְגָּה לְדַרְגָּה וּמִכֶּתֶר לְכֶתֶר עַד שֶׁנִּדְבַּק בָּאָרֶץ הַזּוֹ, וְאָז הֵאִירָה הַלְּבָנָה וְעָמְדָה בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב וַיֵּט שָׁמַיִם וַיֵּרַד, לָאָרֶץ הַזּוֹ. וְאָז כָּתוּב עַל הַר סִינָי. מֶה עָמַד עַל הַר סִינַי? הֱוֵה אוֹמֵר זוֹ שְׁכִינָה.</p>\n<p>רַבִּי אַבָּא אָמַר מִכָּאן, (שמות יט) מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ. וְכָתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא. וְכָתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. וַה' הִמְטִיר - זוֹהִי אֶרֶץ. מֵאֵיזֶה מָקוֹם נָטַל אֶת זֶה? סוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם, מִן הַשָּׁמַיִם מַמָּשׁ. רַבִּי חִיָּיא אָמַר מִכָּאן, וַיְדַבֵּר אֱלֹהִים אֵת כָּל, כָּל - הַכְּלָל שֶׁל הַכֹּל, שֶׁהֲרֵי בָּזֶה תָּלוּי הַכֹּל.</p>"],[9522011649,"<p>לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. רַבִּי יִצְחָק אָמַר, אֱלֹהִים אֲחֵרִים - לְהוֹצִיא שְׁכִינָה. עַל פָּנָי - לְהוֹצִיא פְּנֵי הַמֶּלֶךְ שֶׁבָּהֶם נִרְאֶה הַמֶּלֶךְ הַקָּדוֹשׁ, וְהֵם שְׁמוֹ, וְהוּא הֵם. הוּא שְׁמוֹ, שֶׁכָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי. הוּא וּשְׁמוֹ אֶחָד הוּא. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>שָׁנָה רַבִּי שִׁמְעוֹן, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לָהֶם אָדָם, שֶׁכָּתוּב (יחזקאללד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם. מָה הַטַּעַם קָרָא לָהֶם אָדָם? מִשּׁוּם שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם. אַתֶּם וְלֹא לִשְׁאָר עַמִּים. וּמִשּׁוּם כָּךְ אָדָם אַתֶּם. אַתֶּם קְרוּיִים אָדָם, וְאֵין עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת קְרוּיִים אָדָם.</p>\n<p>שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כֵּיוָן שֶׁאָדָם מִיִּשְׂרָאֵל נִמּוֹל, נִכְנָס לַבְּרִית שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא עִם אַבְרָהָם, שֶׁכָּתוּב (בראשיתכד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְכָתוּב (מיכה ז) חֶסֶד לְאַבְרָהָם. וְהִתְחִיל לְהִכָּנֵס לַמָּקוֹם הַזֶּה. (אדם) כֵּיוָן שֶׁזָּכָה לְקַיֵּם מִצְווֹת הַתּוֹרָה, נִכְנָס לָאָדָם (למקום) וְנִדְבָּק בְּגוּף הַמֶּלֶךְ, וְאָז נִקְרָא אָדָם.</p>\n<p>וְזֶרַע יִשְׂרָאֵל נִקְרְאוּ אָדָם. בֹּא וּרְאֵה, כָּתוּב בְּיִשְׁמָעֵאל וְהוּא יִהְיֶה פֶּרֶא אָדָם. פֶּרֶא אָדָם, וְלֹא אָדָם. פֶּרֶא אָדָם, מִשּׁוּם שֶׁנִּמּוֹל, וְרֵאשִׁיתוֹ שֶׁל אָדָם הָיָה בּוֹ, שֶׁכָּתוּב (בראשית יז) וְיִשְׁמָעֵאל בְּנוֹ בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה בְּהִמֹּלוֹ אֵת בְּשַׂר עָרְלָתוֹ. כֵּיוָן שֶׁנִּמּוֹל נִכְנַס לָרֵאשִׁית הַ את שֶׁנִּקְרֵאת כֹּל. זֶהוּ שֶׁכָּתוּב וְהוּא יִהְיֶה פֶּרֶא אָדָם, וְלֹא אָדָם. יָדוֹ בַכֹּל, יָדוֹ בַכֹּל וַדַּאי - וְלֹא יוֹתֵר, מִשּׁוּם שֶׁלֹּא קִבֵּל מִצְווֹת הַתּוֹרָה. רֵאשִׁית הָיְתָה בּוֹ מִשּׁוּם שֶׁנִּמּוֹל, וְלֹא הִשְׁתַּלֵּם בְּמִצְווֹת הַתּוֹרָה. אֲבָל זֶרַע יִשְׂרָאֵל שֶׁנִּשְׁלְמוּ בַכֹּל, נִקְרְאוּ אָדָם מַמָּשׁ, וְכָתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מִשּׁוּם כָּךְ כָּל הַפַּרְצוּפִים מֻתָּרִים, פְּרָט לְפַרְצוּף אָדָם. רַבִּי יִצְחָק אָמַר, כְּשֶׁנַּעֲשֶׂה, נִרְאֶה שֶׁחָקוּק תּוֹךְ הַחֲקִיקוֹת שֶׁל הַשְּׁלֵמוּת. אָמַר רַבִּי יְהוּדָה, הַיְנוּ מַה שֶּׁאֲנָשִׁים אוֹמְרִים, קְשָׁרָיו בָּרוּחַ מְצוּיִים בַּצּוּרָה.</p>\n<p>רַבִּי יְהוּדָה הָיָה הוֹלֵךְ מִקַּפּוּטְקִיָּא לְלוֹד לִרְאוֹת אֶת רַבִּי שִׁמְעוֹן שֶׁהָיָה שָׁם, וְהָיָה רַבִּי חִזְקִיָּה הוֹלֵךְ עִמּוֹ. אָמַר רַבִּי יְהוּדָה לְרַבִּי חִזְקִיָּה, זֶה שֶּׁשָּׁנִינוּ לִפְנֵי רַבִּי שִׁמְעוֹן וְהוּא יִהְיֶה פֶּרֶא אָדָם - וַדַּאי כָּךְ הוּא. וְזֶהוּ בֵּרוּר הַדָּבָר - סוֹף הַפָּסוּק, שֶׁכָּתוּב וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. מַה זֶּה וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן?</p>\n<p>אָמַר לוֹ, לֹא שָׁמַעְתִּי וְלֹא אֹמַר, שֶׁהֲרֵי לָמַדְנוּ, כָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. אֲשֶׁר שָׂם מֹשֶׁה - אַתָּה יָכוֹל לוֹמַר. אֲבָל שֶׁלֹּא שָׂם מֹשֶׁה - אֵינְךְ יָכוֹל לוֹמַר.</p>\n<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (שם) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ. מִי שֶׁזּוֹכֶה בַּתּוֹרָה וְלֹא נִפְרָד מִמֶּנָּה, זוֹכֶה לִשְׁנֵי חַיִּים - אֶחָד בָּעוֹלָם הַזֶּה, וְאֶחָד בָּעוֹלָם הַבָּא, שֶׁכָּתוּב חַיֶּיךְ, שְׁנַיִם. וְכָל מִי שֶׁנִּפְרָד מִמֶּנָּה, כְּמִי שֶׁנִּפְרָד מִן הַחַיִּים, וּמִי שֶׁנִּפְרָד מֵרַבִּי שִׁמְעוֹן, כְּאִלּוּ נִפְרָד מֵהַכֹּל.</p>\n<p>וּמַה בַּפָּסוּק הַזֶּה שֶׁהוּא פּוֹתֵחַ פֶּתַח לֹא יָכֹלְנוּ לְהִכָּנֵס אֵלָיו - דִּבְרֵי תוֹרָה הַנִּסְתָּרִים עַל אַחַת כַּמָּה וְכַמָּה. אוֹי לַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי יִסְתַּלֵּק מִמֶּנּוּ. שֶׁכְּשֶׁאָנוּ עוֹמְדִים לִפְנֵי רַבִּי שִׁמְעוֹן, מַעַיְנוֹת הַלֵּב פְּתוּחִים לְכָל עֵבֶר וְהַכֹּל מִתְגַּלֶּה. וּכְשֶׁנִּפְרָדִים מִמֶּנּוּ, לֹא יוֹדְעִים דָּבָר, וְכָל הַמַּעְיָנוֹת נִסְתָּמִים.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, הַיְנוּ שֶׁכָּתוּב (במדבר יא) וַיָּאצֶל מִן הָרוּחַ אֲשֶׁר עָלָיו וַיִּתֵּן עַל שִׁבְעִים אִישׁ הַזְּקֵנִים. כַּמְּנוֹרָה הַזּוֹ שֶׁמְּאִירִים מִמֶּנָּה כַּמָּה מְנוֹרוֹת, וְהִיא מְצוּיָה בְקִיּוּמָהּ. כָּךְ רַבִּי שִׁמְעוֹן בַּר יוֹחַאי בַּעַל הַמְּנוֹרוֹת הוּא מֵאִיר לַכֹּל, וְהָאוֹר לֹא זָז מִמֶּנּוּ וְנִמְצָא בְקִיּוּמוֹ. הָלְכוּ עַד שֶׁהִגִּיעוּ אֵלָיו.</p>\n<p>כְּשֶׁהִגִּיעוּ אֵלָיו, מְצָאוּהוּ שֶׁהָיָה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, וְהָיָה אוֹמֵר (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף וְלִפְנֵי ה' יִשְׁפֹּךְ שִׂיחוֹ. כָּל תְּפִלַּת יִשְׂרָאֵל הִיא תְפִלָּה, וּתְפִלַּת הֶעָנִי עֶלְיוֹנָה מִכֻּלָּם. מָה הַטַּעַם? מִשּׁוּם שֶׁזּוֹ עוֹלָה עַד כִּסֵּא הַכָּבוֹד שֶׁל הַמֶּלֶךְ וּמִתְעַטֶּרֶת בְּרֹאשׁוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ (מתעטף) בְּאוֹתָהּ תְּפִלָּה וַדַּאי, תְּפִלַּת הֶעָנִי נִקְרֵאת תְּפִלָּה.</p>\n<p>כִּי יַעֲטֹף. עִטּוּף זֶה אֵינוֹ עִטּוּף שֶׁל כִּסּוּי, שֶׁהֲרֵי אֵין לוֹ. אֶלָּא כָּתוּב כָּאן כִּי יַעֲטֹף, וְכָתוּב שָׁם (איכה ב) הָעֲטוּפִים בְּרָעָב. וְלִפְנֵי ה' יִשְׂפֹּךְ שִׂיחוֹ, שֶׁקּוֹבֵל לִפְנֵי רִבּוֹנוֹ. וְזֶה נוֹחַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁהָעוֹלָם מִתְקַּיֵּם בּוֹ כְּשֶׁלֹּא נִמְצָאִים שְׁאָר מְקַיְּמֵי הָעוֹלָם בָּעוֹלָם. אוֹי לְמִי שֶׁאוֹתוֹ הֶעָנִי יִקְבֹּל עָלָיו לְרִבּוֹנוֹ, מִשּׁוּם שֶׁהֶעָנִי קָרוֹב לַמֶּלֶךְ יוֹתֵר מִכֻּלָּם, שֶׁכָּתוּב (שמות כב) וְהָיָה כִּי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי.</p>\n<p>וְלִשְׁאָר בְּנֵי הָעוֹלָם - לִפְעָמִים שֶׁשּׁוֹמֵעַ וְלִפְעָמִים שֶׁלֹּא שׁוֹמֵעַ. מָה הַטַּעַם? מִשּׁוּם שֶׁדִּיּוּר הַמֶּלֶךְ הוּא בַּכֵּלִים הַשְּׁבוּרִים הַלָּלוּ, שֶׁכָּתוּב (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וְכָתוּב (תהלים לד) קָרוֹב ה' לְנִשְׁבְּרֵי לֵב. (שם נה) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה.</p>\n<p>מִכָּאן שָׁנִינוּ, מִי שֶׁנּוֹזֵף בְּעָנִי - נוֹזֵף בַּשְּׁכִינָה, שֶׁכָּתוּב וְאֶת דַּכָּא וּשְׁפַל רוּחַ, וְכָתוּב (משלי כב) כִּי ה' יָרִיב רִיבָם וְגוֹ'. מִשּׁוּם שֶׁהָאַפּוֹטְרוֹפּוֹס שֶׁלָּהֶם חָזָק וְשׁוֹלֵט עַל הַכֹּל, שֶׁלֹּא צָרִיךְ עֵדִים וְלֹא צָרִיךְ דַּיָּן אַחֵר, וְלֹא נוֹטֵל מַשְׁכּוֹן כִּשְׁאָר הַדַּיָּנִים. וְאֵיזֶה מַשְׁכּוֹן נוֹטֵל? נִשְׁמוֹת בְּנֵי אָדָם, שֶׁכָּתוּב וְקָבַע אֶת קבְעֵיהֶם נָפֶשׁ.</p>\n<p>עוֹד אָמַר, תְּפִלָּה לְעָנִי - כָּל מָקוֹם שֶׁנִּקְרָא תְפִלָּה, דָּבָר עֶלְיוֹן הוּא, שֶׁהוּא עוֹלֶה לְמָקוֹם (שהקדוש ברוך הוא) עֶלְיוֹן. תְּפִלַּת הָרֹאשׁ הֵן הַתְּפִלִּין שֶׁל הַמֶּלֶךְ שֶׁמֵּנִיחַ אוֹתָם.</p>\n<p>רַבִּי שִׁמְעוֹן סוֹבֵב רֹאשׁוֹ, וְרָאָה אֶת רַבִּי יְהוּדָה וְאֶת רַבִּי חִזְקִיָּה שֶׁהִגִּיעוּ אֵלָיו. אַחַר שֶׁסִּיֵּם, הִסְתַּכֵּל בָּהֶם. אָמַר לָהֶם, אוֹצָר הָיָה לָכֶם וְאָבַד מִכֶּם. אָמְרוּ לוֹ, וַדַּאי שֶׁפֶּתַח עֶלְיוֹן פָּתַח מוֹרֵנוּ, וְלֹא יָכֹלְנוּ לְהִכָּנֵס בּוֹ.</p>\n<p>אָמַר, מַה הוּא? אָמְרוּ לוֹ, (בראשית טז) וְהוּא יִהְיֶה פֶּרֶא אָדָם. וְסוֹף הַפָּסוּק אָנוּ רוֹצִים לָדַעַת, שֶׁכָּתוּב וְעַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. מַה זֶּה עַל פְּנֵי כָל אֶחָיו? שֶׁהֲרֵי בֵּרוּר שֶׁל כָּל הַפָּסוּק יָדַעְנוּ, וְאֶת זֶה לֹא יָדַעְנוּ, שֶׁסּוֹף הַכָּתוּב לֹא נִרְאֶה כְרֹאשׁוֹ.</p>\n<p>אָמַר לָהֶם, חַיֵּיכֶם, הַכֹּל הוּא דָּבָר אֶחָד, וּבְדַרְגָּה אַחַת עוֹלֶה. שָׁנִינוּ, כַּמָּה פָנִים לַפָּנִים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא: פָּנִים הַמְּאִירִים. פָּנִים שֶׁלֹּא מְאִירִים. פָּנִים תַּחְתּוֹנִים. פָּנִים רְחוֹקִים. פָּנִים קְרוֹבִים. פָּנִים שֶׁלְּפָנִים. פָּנִים שֶׁלַּחוּץ. פָּנִים שֶׁל יָמִין. פָּנִים שֶׁל שְׂמֹאל.</p>\n<p>בֹּא וּרְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֲחוּזִים בַּפָּנִים הָעֶלְיוֹנִים שֶׁל הַמֶּלֶךְ בְּאוֹתָם פָּנִים שֶׁהוּא וּשְׁמוֹ אֲחוּזִים בָּהֶם, וְהֵם וּשְׁמוֹ אֶחָד הוּא, וּשְׁאָר הָעַמִּים אֲחוּזִים בְּאוֹתָם פָּנִים רְחוֹקִים, בְּאוֹתָם פָּנִים תַּחְתּוֹנִים, וְלָכֵן הֵם רְחוֹקִים מִגּוּף הַמֶּלֶךְ, שֶׁהֲרֵי רָאִינוּ כָּל אוֹתָם שֶׁל מִצְרַיִם, קְרוֹבֵי יִשְׁמָעֵאל, כְּמוֹ אַחִים וּקְרוֹבִים הָיוּ לוֹ, וְכֻלָּם הָיוּ בְּפָנִים תַּחְתּוֹנִים וּבְאוֹתָם פָּנִים רְחוֹקִים.</p>\n<p>וּבִגְלַל אַבְרָהָם, כְּשֶׁנִּמּוֹל יִשְׁמָעֵאל, זָכָה שֶׁשָּׂם מְדוֹרוֹ וְחֶלְקוֹ בְּמָקוֹם שֶׁשּׁוֹלֵט עַל כָּל אוֹתָם פָּנִים רְחוֹקִים וְתַחְתּוֹנִים, עַל כָּל אוֹתָם פָּנִים שֶׁל שְׁאָר הָעַמִּים. זֶהוּ שֶׁכָּתוּב יָדוֹ בַכֹּל. וּמִשּׁוּם כָּךְ עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. כְּלוֹמַר, יָשִׂים מְדוֹרוֹ וְחֶלְקוֹ לְמַעְלָה מִכֻּלָּם, שֶׁכָּתוּב יָדוֹ בַכֹּל, שֶׁשּׁוֹלֵט עַל כָּל שְׁאָר הַפָּנִים שֶׁלְּמַטָּה, וּמִשּׁוּם כָּךְ עַל פְּנֵי כָל אֶחָיו וַדַּאי, שֶׁלֹּא זָכוּ כְמוֹתוֹ.</p>\n<p>בָּאוּ רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה וְנָשְׁקוּ יָדוֹ. אָמַר רַבִּי יְהוּדָה, הַיְנוּ מַה שֶּׁאֲנָשִׁים אוֹמְרִים, יַיִן בִּשְׁמָרָיו וּנְבִיעַת הַבְּאֵר, בְּקֶשֶׁר שֶׁל קְיָמָא מִתְעַטֵּר. אוֹי לָעוֹלָם כְּשֶׁיִּסְתַּלֵּק מִמֶּנּוּ מוֹרֵנוּ! אוֹי לַדּוֹר כְּשֶׁזֶּה יֶאֱרַע בְּאוֹתוֹ הַזְּמַן! אַשְׁרֵי הַדּוֹר שֶׁמַּכִּירִים אֶת מוֹרֵנוּ! אַשְׁרֵי הַדּוֹר שֶׁהוּא שָׁרוּי בְּתוֹכוֹ!</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, הֲרֵי שָׁנִינוּ, כְּשֶׁגֵּר נִמּוֹל נִקְרָא גֵּר צֶדֶק, וְלֹא יוֹתֵר. וְכָאן אָמַר מוֹרֵנוּ יָדוֹ בַכֹּל. אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל נִקְשָׁר בְּאֶחָד. אֲבָל שָׁנִינוּ שֶׁהַגֵּר, שׁוֹנֶה יִשְׁמָעֵאל, שֶׁאֵינוֹ גֵר. בֶּן אַבְרָהָם הוּא הָיָה, בְּנוֹ שֶׁל קָדוֹשׁ הָיָה. וְכָתוּב בּוֹ בְּיִשְׁמָעֵאל, (בראשית יז) הִנֵּה בֵּרַכְתִּי אֹתוֹ. כָּתוּב כָּאן בֵּרַכְתִּי אֹתוֹ, וְכָתוּב שָׁם (שםכד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְעַל כָּךְ כָּתוּב יָדוֹ בַכֹּל.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. שֶׁאִם שְׁאָר קְרוֹבָיו נִמּוֹלוּ (התגירו), נִקְרָאִים גֵּרֵי צֶדֶק וְלֹא יוֹתֵר, וְהוּא יוֹתֵר וְעֶלְיוֹן מִכֻּלָּם. כָּל שֶׁכֵּן הֵם שֶׁלֹּא נִמּוֹלוּ שֶׁעוֹמְדִים בְּאוֹתָם פָּנִים רְחוֹקִים, בְּאוֹתָם פָּנִים תַּחְתּוֹנִים. וְהוּא מְדוֹרוֹ לְמַעְלָה מִכָּל הַפָּנִים שֶׁלָּהֶם, וּמִכָּל הַפָּנִים שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. זֶהוּ שֶׁכָּתוּב עַל פְּנֵי כָל אֶחָיו יִשְׁכֹּן. אָמַר רַבִּי יְהוּדָה, מִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הִכְרִיז וְאָמַר, לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי, שֶׁזּוֹהִי הָאֱמוּנָה שֶׁלּוֹ.</p>"],[9522011650,"<p>לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה. הֲרֵי נִתְבָּאֵר. וְאָמַר רַבִּי יוֹסֵי, כָּל הַפַּרְצוּפִים מֻתָּרִים, פְּרָט לְפַרְצוּף אָדָם, שֶׁהֲרֵי פַּרְצוּף זֶה שׁוֹלֵט בַּכֹּל.</p>\n<p>דָּבָר אַחֵר לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה - רַבִּי יִצְחָק פָּתַח, אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ. כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִזָּהֵר עַל דִּבְרֵי הַתּוֹרָה, כַּמָּה יֵשׁ לוֹ לְהִזָּהֵר שֶׁלֹּא יִטְעֶה בָהֶם, וְשֶׁלֹּא יוֹצִיא מֵהַתּוֹרָה מַה שֶּׁלֹּא יוֹדֵעַ וְלֹא קִבֵּל מֵרַבּוֹ. שֶׁכָּל מִי שֶׁאוֹמֵר דִּבְרֵי תוֹרָה מַה שֶּׁלֹּא יוֹדֵעַ וְלֹא קִבֵּל מֵרַבּוֹ, עָלָיו כָּתוּב לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהִפָּרַע מִמֶּנּוּ בָּעוֹלָם הַבָּא, בִּזְמַן שֶׁנִּשְׁמָתוֹ תִּרְצֶה לְהִכָּנֵס לִמְקוֹמָהּ, דּוֹחִים אוֹתָהּ הַחוּצָה, וְתֻשְׁמַד מֵאוֹתוֹ מָקוֹם שֶׁצְּרוּרָה בִּצְרוֹר חַיֵּי שְׁאָר הַנְּשָׁמוֹת.</p>\n<p>(רבי יהודה אומר מכאן) כְּמוֹ שֶׁשָּׁנִינוּ, לָמָּה יִקְצֹף הָאֱלֹהִים עַל קוֹלֶךְ. קוֹלֶךְ - זוֹהִי נִשְׁמָתוֹ שֶׁל הָאָדָם. אָמַר רַבִּי חִיָּיא, עַל זֶה כָּתוּב כִּי ה' אֱלֹהֶיךְ אֵל קַנָּא. מָה הַטַּעַם? מִשּׁוּם שֶׁמְּקַנֵּא לִשְׁמוֹ בַּכֹּל. אִם מִשּׁוּם הַפַּרְצוּפִים מְקַנֵּא לִשְׁמוֹ, מִשּׁוּם שֶׁמְּשַׁקֵּר בִּשְׁמוֹ, אוֹ מִשּׁוּם הַתּוֹרָה.</p>\n<p>שָׁנִינוּ, כָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ, שֶׁאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא כָלוּל בַּשֵּׁם הַקָּדוֹשׁ, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִזָּהֵר שֶׁלֹּא יִטְעֶה בִּשְׁמוֹ הַקָּדוֹשׁ וְלֹא יְשַׁקֵּר בּוֹ. וּמִי שֶׁמְּשַׁקֵּר בַּמֶּלֶךְ הָעֶלְיוֹן, לֹא מַכְנִיסִים אוֹתוֹ לַפַּלְטֵרִין שֶׁל הַמֶּלֶךְ, וְיֻשְׁמַד מִן הָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּתוּב כָּאן לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְמוּנָה, וְכָתוּב שָׁם (שמות לד) פְּסָל לְךְ שְׁנֵי לֻחֹת אֲבָנִים. כְּלוֹמַר, לֹא תַעֲשֶׂה לְךְ פֶסֶל - לֹא תַעֲשֶׂה לְךְ תּוֹרָה אַחֶרֶת שֶׁלֹּא יָדַעְתָּ וְלֹא אָמַר לְךְ רַבְּךְ. מָה הַטַּעַם? כִּי אָנֹכִי ה' אֱלֹהֶיךְ אֵל קַנָּא. אֲנִי הוּא שֶׁעָתִיד לְהִפָּרַע מִמְּךְ בָּעוֹלָם הַבָּא בְּשָׁעָה שֶׁהַנְּשָׁמָה רוֹצָה לְהִכָּנֵס לְפָנַי, כַּמָּה מְזֻמָּנִים לְשַׁקֵּר בָּהּ וּלְהַכְנִיסָהּ לַגֵּיהִנֹּם.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, לֹא תַעֲשֶׂה לְךְ וְגוֹ' - שֶׁצָּרִיךְ הָאָדָם שֶׁלֹּא לְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (דבראחרלאתעשהלךפסלוגו' שצריך האדם שלא לשקר בשמו של הקדוש ברוך הוא, ומהו, 'זובריתאותהקיוםהקדושה. שמישמשקר בברית הזו, משקר בשמו של הקדוש ברוך הוא) שֶׁל הַקֶּשֶׁר הָרִאשׁוֹן שֶׁנִּקְשְׁרוּ יִשְׂרָאֵל בַּקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנִּמּוֹלוּ, וְזֶהוּ הַקִּיּוּם הָרִאשׁוֹן שֶׁל הַכֹּל - לְהִכָּנֵס בִּבְרִית אַבְרָהָם, שֶׁהוּא קֶשֶׁר הַשְּׁכִינָה. וְצָרִיךְ אָדָם שֶׁלֹּא לְשַׁקֵּר בַּבְּרִית הַזּוֹ, שֶׁמִּי שֶׁמְּשַׁקֵּר בַּבְּרִית הַזּוֹ, מְשַׁקֵּר בַּקָּדוֹשׁ בָּרוּךְ הוּא. מָה הַשֶּׁקֶר? הוּא שֶׁלֹּא יַכְנִיס בְּרִית זוֹ לְרָשׁוּת אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר וּבָעַל בַּת אֵל נֵכָר.</p>\n<p>רַבִּי יְהוּדָה אָמַר מִכָּאן, (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ - מִי שֶׁמְּשַׁקֵּר בַּבְּרִית הַזּוֹ, מְשַׁקֵּר בַּקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁבְּרִית זוֹ אֲחוּזָה בַּקָּדוֹשׁ בָּרוּךְ הוּא, וְכָתוּב לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה אֲשֶׁר בַּשָּׁמַיִם מִמַּעַל וְגוֹ'.</p>"],[9522011651,"<p>לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם. רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיָה עִמּוֹ רַבִּי חִיָּיא. אָמַר רַבִּי חִיָּיא, כָּתוּב וְרָאִיתָ בַּשִּׁבְיָה אֵשֶׁת יְפַת תֹּאַר. מָה הַטַּעַם, וַהֲרֵי כָּתוּב לֹא תִתְחַתֵּן בָּם? אָמַר לוֹ, בְּעוֹדּ שֶׁהֵן קַיָּמוֹת בִּרְשׁוּתָם.</p>\n<p>וּבֹא רְאֵה, אֵין לְךְ אִשָּׁה בָּעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת כְּשֵׁרָה כָּרָאוּי, שֶׁשָּׁנִינוּ, לָמָּה סָמַךְ פָּרָשַׁה זוֹ לְבֵן סוֹרֵר וּמוֹרֶה? אֶלָּא בְּוַדַּאי מִי שֶׁנּוֹשֵׂא אִשָּׁה זוֹ, יוֹרֵשׁ מִמֶּנָּה בֵּן סוֹרֵר וּמוֹרֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁקָּשֶׁה לְהַעֲבִיר מִמֶּנּוּ זֻהֲמָה, וְכָל שֶׁכֵּן אוֹתָהּ שֶׁנִּשְּׂאָה בַּתְּחִלָּה, שֶׁדִּין בְּדִין נִדְבָּק וְנִטְמֵאת בָּהּ, וְקָשֶׁה לְהַעֲבִיר מִמֶּנָּה הַזֻּהֲמָה, וְהַיְנוּ מַה שֶּׁאָמַר מֹשֶׁה בִּנְשׁוֹת מִדְיָן, (במדבר לא) וְכָל אִשָּׁה יֹדַעַת אִישׁ לְמִשְׁכַּב זָכָר הֲרֹגוּ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁיּוֹרֵשׁ נַחֲלָה זוֹ וְשׁוֹמֵר אוֹתָהּ, שֶׁבְּאוֹתָהּ יְרֻשָּׁה קְדוֹשָׁה נִדְבָּק הָאָדָם בַּקָּדוֹשׁ בָּרוּךְ הוּא. כָּל שֶׁכֵּן אִם זוֹכֶה לְמִצְווֹת הַתּוֹרָה, שֶׁהֲרֵי פּוֹשֵׁט הַמֶּלֶךְ יְמִינוֹ כְּנֶגְדּוֹ וְנִדְבָּק בַּגּוּף הַקָּדוֹשׁ. וְעַל זֶה כָּתוּב בָּהֶם בְּיִשְׂרָאֵל, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם, וְכָתוּב (שם יד) בָּנִים אַתֶּם לַה'. בָּנִים אַתֶּם מַמָּשׁ, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וְכָתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522011652,"<p>לֹא תִשָּׂא אֶת שֵׁם וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח, (מלכים ב ד) וַיֹּאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָּךְ הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. אָמַר לָהּ אֱלִישָׁע, כְּלוּם יֵשׁ לָךְ עַל מַה שֶּׁתִּשְׁרֶה בִּרְכַּת הַקָּדוֹשׁ בָּרוּךְ הוּא? שֶׁשָּׁנִינוּ, אָסוּר לְאָדָם לְבָרֵךְ עַל שֻׁלְחָן רֵיק, מָה הַטַּעַם? מִשּׁוּם שֶׁהַבְּרָכָה שֶׁלְּמַעְלָה לֹא שׁוֹרָה בְּמָקוֹם רֵיק.</p>\n<p>וּמִשּׁוּם כָּךְ צָרִיךְ אָדָם לְסַדֵּר עַל שֻׁלְחָנוֹ לֶחֶם אֶחָד אוֹ יוֹתֵר לְבָרֵךְ עָלָיו. וְאִם לֹא יָכוֹל, צָרִיךְ לְהַשְׁאִיר מֵאוֹתוֹ מָזוֹן שֶׁאָכַל עַל מַה שֶּׁיְּבָרֵךְ, וְלֹא יִמָּצֵא שֶׁמְּבָרֵךְ בְּרֵיקָנוּת.</p>\n<p>כֵּיוָן שֶׁאָמְרָה אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן - אָמַר, וַדַּאי הֲרֵי בְּרָכָה שְׁלֵמָה בָּזֶה, שֶׁכָּתוּב (קהלת ז) טוֹב שֵׁם מִשֶּׁמֶן טוֹב. שֶׁשֵּׁם קָדוֹשׁ יוֹצֵא מִשֶּׁמֶן לְהִתְבָּרֵךְ וּלְהַדְלִיק מְנוֹרוֹת קְדוֹשׁוֹת. מַהוּ הַשֶּׁמֶן הַזֶּה? (כמו שגאמר (בראשית ב) ונהר יצא מעדן להשקות את הגן) רַבִּי יִצְחָק אָמַר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ'. רַבִּי אֶלְעָזָר אוֹמֵר, אֵלּוּ הָרֵי אֲפַרְסְמוֹן זַךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, טוֹב שֵׁם - כַּמָּה טוֹב שֵׁם עֶלְיוֹן שֶׁל מְנוֹרוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת כְּשֶׁכֻּלָּן מְאִירוֹת מִשֶּׁמֶן טוֹב, כְּמוֹ שֶׁאָמַרְנוּ. וְאָסוּר לְאָדָם לְהַזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרֵיקָנוּת. שֶׁכָּל מִי שֶׁמַּזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרֵיקָנוּת, טוֹב לוֹ שֶׁלֹּא נִבְרָא.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, לֹא צָרִיךְ לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ, אֶלָּא אַחַר דָּבָר. שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ לֹא נִזְכַּר בַּתּוֹרָה אֶלָּא אַחַר שְׁנֵי דִבּוּרִים (כלומר על דבר), שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, לֹא נִזְכַּר שְׁמוֹ הַקָּדוֹשׁ אֶלָּא עַל עוֹלָם שָׁלֵם, שֶׁכָּתוּב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. מִכָּאן שֶׁלֹּא לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ בְּרֵיקָנוּת. וְכָתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא. (כתוב לא תשא את שם ה' אלהיך לשוא, שלא להזכיר שם הקדוש בריקנות, אלא בברכה או בתפלה. ומי שמזכיר השם הקדוש בריקנות, שלא בברכה או בתפלה, כאשר נשמתו תצא ממגו עתידים להפרע ממגו ולנקם ממגו נקמות, שכתוב כי לא ינקה ה' את אשר ישא את שמו לשוא).</p>\n<p>וְשָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מַהִי בְּרָכָה? הַשֵּׁם הַקָּדוֹשׁ. מִשּׁוּם שֶׁמִּמֶּנּוּ נִמְצֵאת הַבְּרָכָה לְכָל הָעוֹלָם, וְהַבְּרָכָה לֹא נִמְצֵאת עַל מָקוֹם רֵיק וְלֹא שׁוֹרָה עָלָיו. זֶהוּ שֶׁכָּתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא.</p>"],[9522011653,"<p>זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. רַבִּי יִצְחָק אָמַר, כָּתוּב (שם א) וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי, וְכָתוּב בַּמָּן (שמות טז) שֵׁשֶׁת יָמִים תִּלְקְטֻהוּ וּבַיּוֹם הַשְּׁבִיעִי שַׁבָּת לֹא יִהְיֶה בּוֹ. כֵּיוָן שֶׁלֹּא נִמְצָא בּוֹ מְזוֹנוֹת, אֵיזוֹ בְּרָכָה נִמְצֵאת בּוֹ?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַבְּרָכוֹת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה תְּלוּיוֹת בַּיּוֹם הַשְּׁבִיעִי. וְשָׁנִינוּ, לָמָּה לֹא נִמְצָא מָן בַּיּוֹם הַשְּׁבִיעִי? מִשּׁוּם שֶׁמֵּאוֹתוֹ יוֹם מִתְבָּרְכִים כָּל שֵׁשֶׁת הַיָּמִים הָעֶלְיוֹנִים, וְכָל אֶחָד וְאֶחָד נוֹתֵן מְזוֹנוֹ לְמַטָּה, כָּל אֶחָד בְּיוֹמוֹ, מֵאוֹתָהּ בְּרָכָה שֶׁמִּתְבָּרְכִים בַּיּוֹם הַשְּׁבִיעִי.</p>\n<p>וּמִשּׁוּם כָּךְ, מִי שֶׁהוּא בְּדַרְגַּת הָאֱמוּנָה, צָרִיךְ לְסַדֵּר שֻׁלְחָן וּלְתַקֵּן סְעוּדָה בְּלֵיל שַׁבָּת כְּדֵי שֶׁיִּתְבָּרֵךְ שֻׁלְחָנוֹ כָּל אוֹתָם שִׁשָּׁה יָמִים, שֶׁהֲרֵי בְּאוֹתוֹ זְמַן מִזְדַּמֶּנֶת הַבְּרָכָה לְהִתְבָּרֵךְ כָּל שֵׁשֶׁת יְמֵי הַשַּׁבָּת, וְהַבְּרָכָה לֹא נִמְצֵאת בְּשֻׁלְחָן רֵיק, וְעַל כָּךְ צָרִיךְ לְסַדֵּר שֻׁלְחָנוֹ בְּעֶרֶב שַׁבָּת בִּלְחָמִים וּמְזוֹנוֹת.</p>\n<p>רַבִּי יִצְחָק אָמַר, אֲפִלּוּ בְּיוֹם הַשַּׁבָּת גַּם. רַבִּי יְהוּדָה אָמַר, צָרִיךְ לְהִתְעַנֵּג בַּיּוֹם הַזֶּה וְלֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, כְּדֵי שֶׁיִּמָּצְאוּ שּׁבַע וְעֹנֶג בַּיּוֹם הַזֶּה בָּעוֹלָם.</p>\n<p>רַבִּי אַבָּא אָמַר, לְהַזְמִין בְּרָכָה בְּאוֹתָם יָמִים שֶׁלְּמַעְלָה שֶׁמִּתְבָּרְכִים מִן הַיּוֹם הַזֶּה, וּבַיּוֹם הַזֶּה מָלֵא רֹאשׁוֹ שֶׁל זְעֵיר אַנְפִּין מִטַּל שֶׁנּוֹחֵת מֵהָעַתִּיק הַקָּדוֹשׁ הַנִּסְתָּר שֶׁל הַכֹּל, וּמַטִּיל לִשְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים שָׁלֹשׁ פְּעָמִים מִשֶּׁנִּכְנֶסֶת שַׁבָּת, שֶׁכֻּלָּם יִתְבָּרְכוּ כְּאֶחָד.</p>\n<p>וְעַל זֶה צָרִיךְ אָדָם לְהִתְעַנֵּג שְׁלֹשׁ הַפְּעָמִים הַלָּלוּ, שֶׁהֲרֵי בָּזֶה תְּלוּיָה הָאֱמוּנָה הָעֶלְיוֹנָה - בָּעַתִּיק הַקָּדוֹשׁ, וּבִזְעֵיר אַנְפִּין, וּבִשְׂדֵה הַתַּפּוּחִים. וְצָרִיךְ אָדָם לְהִתְעַנֵּג בָּהֶם וְלִשְׂמֹחַ בָּהֶם. וּמִי שֶׁגּוֹרֵעַ סְעוּדָה מֵהֶם, מַרְאֶה פְּגָם לְמַעְלָה, וְעָנְשׁוֹ שֶׁל הָאָדָם הַהוּא גָּדוֹל.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ לְסַדֵּר שֻׁלְחָנוֹ שָׁלֹשׁ פְּעָמִים מִשֶּׁנִּכְנֶסֶת שַׁבָּת, וְלֹא יִמָּצֵא שֻׁלְחָנוֹ רֵיק, וְתִשְׁרֶה עָלָיו הַבְּרָכָה כָּל שְׁאָר יְמוֹת הַשַּׁבָּת, וּבַדָּבָר הַזֶּה מַרְאֶה וְתוֹלֶה אֶת הָאֱמוּנָה הָעֶלְיוֹנָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, זֶה מִי שֶׁמַּשְׁלִים שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, קוֹל יוֹצֵא וּמַכְרִיז עָלָיו: (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. זוֹ סְעוּדָה אַחַת כְּנֶגֶד הָעַתִּיק הַקָּדוֹשׁ שֶׁל כָּל הַקְּדוֹשִׁים. וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ - זוֹ סְעוּדָה שְׁנִיָּה כְּנֶגֶד שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים. וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ - זוֹהִי הַשְּׁלֵמוּת שֶׁהִשְׁתַּלְּמָה בִּזְעֵיר אַנְפִּין.</p>\n<p>וּכְנֶגְדָּם צָרִיךְ לְהַשְׁלִים סְעוּדָתוֹ, וְצָרִיךְ לְהִתְעַנֵּג בְּכָל הַסְּעוּדוֹת וְלִשְׂמֹחַ בְּכָל אַחַת וְאַחַת מֵהֶן, מִשּׁוּם שֶׁהִיא הָאֱמוּנָה הַשְּׁלֵמָה, וּמִשּׁוּם כָּךְ הַשַּׁבָּת נִתְכַּבְּדָה מִכָּל שְׁאָר הַזְּמַנִּים וְהַחַגִּים, מִשּׁוּם שֶׁהַכֹּל בָּהּ נִמְצָא, וְלֹא נִמְצָא כָּךְ בְּכָל הַזְּמַנִּים וְהַחַגִּים. אָמַר רַבִּי חִיָּיא, מִשּׁוּם כָּךְ, מִשּׁוּם שֶׁהַכֹּל נִמְצָא בּוֹ, נִזְכַּר שָׁלֹשׁ פְּעָמִים, שֶׁכָּתוּב (בראשית ב) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. וַיִּשְׁבּוֹת בַּיּוֹם הַשְּׁבִיעִי. וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי.</p>\n<p>רַבִּי אַבָּא (רב המנונא סבא), כְּשֶׁהָיָה יוֹשֵׁב בִּסְעוּדַת הַשַּׁבָּת, הָיָה שָׂמֵחַ בְּכָל אַחַת וְאַחַת, וְהָיָה אוֹמֵר: זוֹהִי סְעוּדָה קְדוֹשָׁה שֶׁל הָעַתִּיק הַקָּדוֹשׁ הַנִּסְתָּר שֶׁל הַכֹּל. בַּסְּעוּדָה הָאַחֶרֶת הָיָה אוֹמֵר: זוֹהִי סְעוּדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵן בְּכָל הַסְּעוּדוֹת. וְהָיָה שָׂמֵחַ בְּכָל אַחַת וְאַחַת. כְּשֶׁהָיָה מַשְׁלִים אֶת הַסְּעוּדוֹת, אוֹמֵר: נִשְׁלְמוּ סְעוּדוֹת הָאֱמוּנָה.</p>\n<p>כְּשֶׁרַבִּי שִׁמְעוֹן הָיָה בָּא לַסְּעוּדָה, הָיָה אוֹמֵר כָּךְ: הַתְקִינוּ סְעוּדָה שֶׁל הָאֱמוּנָה הָעֶלְיוֹנָה. הַתְקִינוּ סְעוּדַת הַמֶּלֶךְ. וְהָיָה יוֹשֵׁב וְשָׂמֵחַ. כְּשֶׁהִשְׁלִים סְעוּדָה שְׁלִישִׁית, הָיוּ מַכְרִיזִים עָלָיו: (ישעיהנח) אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר לְאָבִיו, אֵיךְ מְתַקְּנִים אֶת הַסְּעוּדוֹת הַלָּלוּ? אָמַר לוֹ, לֵיל שַׁבָּת כָּתוּב וְהִרְכַּבְתִּיךְ עַל בָּמֳתֵי אָרֶץ. בּוֹ בַּלַּיְלָה מִתְבָּרֶכֶת הַגְּבִירָה וְכָל שְׂדֵה הַתַּפּוּחִים, וּמִתְבָּרֵךְ שֻׁלְחָנוֹ שֶׁל אָדָם, וּנְשָׁמָה נוֹסֶפֶת, וְאוֹתוֹ הַלַּיְלָה שִׂמְחַת הַגְּבִירָה הוּא.</p>\n<p>וְצָרִיךְ אָדָם לִשְׂמֹחַ בְּשִׂמְחָה וְלֶאֱכֹל סְעוּדַת הַגְּבִירָה. בְּיוֹם הַשַּׁבָּת, בַּסְּעוּדָה הַשְּׁנִיָּה כָּתוּב אָז תִּתְעַנַּג עַל ה'. עַל ה' וַדַּאי. שֶׁאוֹתָהּ שָׁעָה נִגְלֶה הָעַתִּיק הַקָּדוֹשׁ, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, וְהַשְּׁלֵמוּת וְהַחֶדְוָה שֶׁל הָעַתִּיק אָנוּ עוֹשִׂים, וְזוֹהִי סְעוּדָתוֹ וַדַּאי.</p>\n<p>בַּסְּעוּדָה הַשְּׁלִישִׁית שֶׁל שַׁבָּת כָּתוּב וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ. זוֹהִי הַסְּעוּדָה שֶׁל זְעֵיר אַנְפִּין שֶׁהוּא בִּשְׁלֵמוּת. וְכָל שֵׁשֶׁת הַיָּמִים מֵאוֹתָהּ שְׁלֵמוּת מִתְבָּרְכִים. וְצָרִיךְ אָדָם לִשְׂמֹחַ בִּסְעוּדָתוֹ וּלְהַשְׁלִים הַסְּעוּדוֹת הַלָּלוּ, שֶׁהֵן סְעוּדוֹת הָאֱמוּנָה הַשְּׁלֵמָה שֶׁל זֶרַע קָדוֹשׁ שֶׁל יִשְׂרָאֵל, שֶׁהָאֱמוּנָה הָעֶלְיוֹנָה הִיא שֶׁלָּהֶם וְלֹא שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּמִשּׁוּם כָּךְ אָמַר, (שמות לא) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל.</p>\n<p>בֹּא וּרְאֵה, בַּסְּעוּדוֹת הַלָּלוּ נוֹדָעִים יִשְׂרָאֵל שֶׁהֵם בְּנֵי הַמֶּלֶךְ וְשֶׁהֵם מֵהֵיכַל הַמֶּלֶךְ וְשֶׁהֵם בְּנֵי הָאֱמוּנָה, וּמִי שֶׁפּוֹגֵם סְעוּדָה אַחַת מֵהֶם, מַרְאֶה פְּגָם לְמַעְלָה, וּמַרְאֶה אֶת עַצְמוֹ שֶׁאֵינוֹ מִבְּנֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁאֵינוֹ מִבְּנֵי הֵיכַל הַמֶּלֶךְ, וְשֶׁאֵינוֹ מִזֶּרַע קָדוֹשׁ שֶׁל יִשְׂרָאֵל, וְנוֹתְנִים עָלָיו חֹמֶר שֶׁל שְׁלֹשָׁה דְבָרִים - דִּין הַגֵּיהִנֹּם וְכוּ'.</p>\n<p>וּבֹא רְאֵה, בְּכָל שְׁאָר הַזְּמַנִּים וְהַחַגִּים צָרִיךְ אָדָם לִשְׂמֹחַ וּלְשַׂמֵּחַ אֶת הָעֲנִיִּים, וְאִם הוּא שָׂמֵחַ לְבַדּוֹ וְלֹא נוֹתֵן לַעֲנִיִּים - עָנְשׁוֹ רַב, שֶׁהֲרֵי לְבַדּוֹ שָׂמֵחַ, וְלֹא נוֹתֵן שִׂמְחָה לְאַחֵר. עָלָיו כָּתוּב (מלאכי ב) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם פֶּרֶשׁ חַגֵּיכֶם. וְאִם הוּא שָׂמֵחַ בְּשַׁבָּת, אַף עַל גַּב שֶׁלֹּא נוֹתֵן לְאַחֵר - לֹא נוֹתְנִים עָלָיו עֹנֶשׁ כְּבִשְׁאָר הַזְּמַנִּים וְהַחַגִּים, שֶׁכָּתוּב פֶּרֶשׁ חַגֵּיכֶם. אָמַר פֶּרֶשׁ חַגֵּיכֶם, וְלֹא פֶּרֶשׁ שַׁבַּתְּכֶם. וְכָתוּב (ישעיה א) חָדְשֵׁיכֶם וּמוֹעֲדֵיכֶם שָׂנְאָה נַפְשִׁי. וְאִלּוּ שַׁבָּת לֹא אָמַר.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וּמִשּׁוּם שֶׁכָּל הָאֱמוּנָה נִמְצֵאת בְּשַׁבָּת, נוֹתְנִים לָאָדָם נְשָׁמָה אַחֶרֶת, נְשָׁמָה עֶלְיוֹנָה, נְשָׁמָה שֶׁכָּל הַשְּׁלֵמוּת בָּהּ, כְּדֻגְמַת הָעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ נִקְרֵאת שַׁבָּת. מַה זֶּה שַׁבָּת? שֵׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֵׁם שֶׁהוּא שָׁלֵם מִכָּל צְדָדָיו.</p>\n<p>אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא. אוֹי לָאָדָם שֶׁלֹּא מַשְׁלִים אֶת שִׂמְחַה הַמֶּלֶךְ הַקָּדוֹשׁ. וּמַהִי שִׂמְחָתוֹ? אֵלּוּ שְׁלֹשׁ הַסְּעוּדוֹת שֶׁל הָאֱמוּנָה, סְעוּדוֹת שֶׁאַבְרָהָם יִצְחָק וְיַעֲקֹב כְּלוּלִים בָּהֶם, וְכֻלָּם שִׂמְחָה עַל שִׂמְחָה, אֱמוּנָה שְׁלֵמָה מִכָּל צְדָדָיו.</p>\n<p>שָׁנִינוּ, בַּיּוֹם הַזֶּה מִתְעַטְּרִים הָאָבוֹת, וְכָל הַבָּנִים יוֹנְקִים, מַה שֶּׁאֵין כֵּן בְּכָל שְׁאָר הַחַגִּים וְהַזְּמַנִּים. בַּיּוֹם הַזֶּה רִשְׁעֵי הַגֵּיהִנֹּם נָחִים. בַּיּוֹם הַזֶּה כָּל הַדִּינִים נִכְפִּים וְלֹא מִתְעוֹרְרִים בָּעוֹלָם. בַּיּוֹם הַזֶּה הַתּוֹרָה מִתְעַטֶּרֶת בַּעֲטָרוֹת שְׁלֵמוֹת. בַּיּוֹם הַזֶּה שִׂמְחָה וְתַפְנוּק נִשְׁמָעִים בְּמָאתַיִם וַחֲמִשִּׁים עוֹלָמוֹת.</p>\n<p>בֹּא וּרְאֵה, בְּכָל שֵׁשֶׁת יְמֵי הַשַּׁבָּת, כְּשֶׁמַּגִּיעָה שְׁעַת תְּפִלַּת הַמִּנְחָה, הַדִּין הַקָּשֶׁה שׁוֹלֵט וְכָל הַדִּינִים מִתְעוֹרְרִים, אֲבָל בְּיוֹם הַשַּׁבָּת, כְּשֶׁמַּגִּיעַ זְמַן תְּפִלַּת הַמִּנְחָה, נִמְצָא רְצוֹן הָרְצוֹנוֹת, וְהָעַתִּיק הַקָּדוֹשׁ מְגַלֶּה רְצוֹנוֹ, וְכָל הַדִּינִים נִכְפִּים, וְנִמְצָא רָצוֹן וְשִׂמְחָה בַּכֹּל.</p>\n<p>וּבָרָצוֹן הַזֶּה הִסְתַּלֵּק מֹשֶׁה, הַנָּבִיא הַנֶּאֱמָן הַקָּדוֹשׁ מִן הָעוֹלָם, כְּדֵי לְהוֹדִיעַ שֶׁלֹּא בְדִין הִסְתַּלֵּק, וְאוֹתָהּ שָׁעָה בְּרָצוֹן שֶׁל הָעַתִּיק הַקָּדוֹשׁ יָצְאָה נִשְׁמָתוֹ וְנִטְמְנָה בּוֹ. מִשּׁוּם כָּךְ וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ כָּתוּב. מָה הָעַתִּיק הַקָּדוֹשׁ טָמִיר שֶׁל כָּל הַטְּמִירִים, וְלֹא יוֹדְעִים עֶלְיוֹנִים וְתַחְתּוֹנִים - אַף כָּאן נְשָׁמָה זוֹ שֶׁנִּטְמְנָה בָּרָצוֹן הַזֶּה שֶׁהִתְגַּלָּה בִּשְׁעַת תְּפִלַּת מִנְחַת הַשַּׁבָּת, כָּתוּב וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ, וְהוּא טָמִיר מִכָּל הַטְּמִירִים שֶׁל הָעוֹלָם, וְהַדִּין לֹא שׁוֹלֵט בּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה!</p>\n<p>שָׁנִינוּ, בַּיּוֹם הַזֶּה שֶׁהַתּוֹרָה מִתְעַטֶּרֶת בּוֹ, מִתְעַטֶּרֶת בַּכֹּל, בְּכָל אוֹתָן מִצְווֹת, בְּכָל אוֹתָן גְּזֵרוֹת וָעֳנָשִׁים, בְּשִׁבְעִים עֲנָפִים שֶׁל אוֹר שֶׁזּוֹהֲרִים מִכָּל צַד וְצַד. מִי רָאָה הָעֲנָפִים שֶׁיּוֹצְאִים מִכָּל עָנָף וְעָנָף, חֲמִשָּׁה עוֹמְדִים בְּתוֹךְ הָאִילָן, וְכָל הַפָּנִים אֲחוּזִים בָּהֶם? מִי רָאָה אוֹתָם שְׁעָרִים שֶׁנִּפְתָּחִים בְּכָל צַד וְצַד, וְכֻלָּם זוֹהֲרִים וּמְאִירִים בִּאוֹתוֹ הָאוֹר שֶׁיּוֹצֵא וְלֹא פוֹסֵק?</p>\n<p>קֹוֹל הַכָּרוֹז יוֹצֵא: הִתְעוֹרְרוּ קְדוֹשִׁים עֶלְיוֹנִים, הִתְעוֹרְרוּ הָעָם הַקָּדוֹשׁ שֶׁנִּבְחָר לְמַעְלָה וּלְמַטָּה, עוֹרְרוּ שִׂמְחָה כְּנֶגֶד רִבּוֹנְכֶם, הִתְעוֹרְרוּ בְשִׂמְחָה שְׁלֵמָה, הִזְדַּמְּנוּ לְשָׁלֹשׁ שְׂמָחוֹת שֶׁל שְׁלֹשֶׁת הָאָבוֹת, הִזְדַּמְּנוּ לִקְרַאת הָאֱמוּנָה שֶׁל שִׂמְחַת כָּל הַשְּׂמָחוֹת. אַשְׁרֵי חֶלְקְכֶם, יִשְׂרָאֵל קְדוֹשִׁים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא! זוֹהִי יְרֻשָּׁה לָכֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב בֵּינֵי וּבֵין בְּנֵי יִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּךְ הוּא וַדַּאי. וְעַל זֶה כָּתוּב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְכָתוּב (ויקרא יט) קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה'. וְכָתוּב (ישעיה נח) וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ ה' מְכֻבָּד.</p>\n<p>שָׁנִינוּ, בַּיּוֹם הַזֶּה כָּל נִשְׁמוֹת הַצַּדִּיקִים מִתְעַדְּנִים בְּתַפְנוּקֵי הָעַתִּיק הַקָּדוֹשׁ, נִסְתַּר כָּל הַנִּסְתָּרִים, וְרוּחַ אַחַת מֵהָעֹנֶג שֶׁל אוֹתוֹ הָעַתִּיק הַקָּדוֹשׁ מִתְפַּשֶּׁטֶת (ההואמתפשט) בְּכָל הָעוֹלָמוֹת, וְעוֹלָה וְיוֹרֶדֶת, וּמִתְפַּשֶּׁטֶת לְכָל הַבָּנִים הַקְּדוֹשִׁים לְכָל שׁוֹמְרֵי הַתּוֹרָה, וְנָחִים בִּמְנוּחָה שְׁלֵמָה, נִשְׁכָּחִים מִכֻּלָּם כָּל הָרְגָזִים, כָּל הַדִּינִים וְכָל הָעֲבוֹדוֹת הַקָּשׁוֹת. זֶהוּ שֶׁכָּתוּב (שם יד) בְּיוֹם הָנִיחַ ה' לְךְ מֵעָצְבְּךְ וּמִרָגְזֶךְ וּמִן הָעֲבֹדָה הַקָּשָׁה.</p>\n<p>מִשּׁוּם כָּךְ שְׁקוּלָה שַׁבָּת כְּנֶגֶד הַתּוֹרָה, וְכָל מִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שׁוֹמֵר אֶת כָּל הַתּוֹרָה. וְכָתוּב (ישעיה נו) אַשְׁרֵי אֱנוֹשׁ יעֲשֶׂה את וּבֶן אָדָם יַחֲזִיק בָּהּ שמֵר שַׁבָּת מֵחַלְּלוֹ וְשֹׁמֵר יָדוֹ מֵעֲשׂוֹת כָּל רָע. נִשְׁמָע, שֶׁמִּי שֶׁשּׁוֹמֵר אֶת הַשַּׁבָּת כְּמִי שֶׁשּׁוֹמֵר כָּל הַתּוֹרָה.</p>\n<p>רַבִּי יוּדַאי שָׁאַל אֶת רַבִּי שִׁמְעוֹן יוֹם אֶחָד שֶׁנִּפְגַּשׁ עִמּוֹ בַּדֶּרֶךְ, אָמַר לוֹ, רַבִּי, הֲרֵי כָּתוּב (בפרשת השבת) בְּפָרָשָׁה זוֹ שַׁבָּת שֶׁאָמַר יְשַׁעְיָה, שֶׁכָּתוּב כֹּה אָמַר ה' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וְגוֹ', וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי וְגוֹ'. מַה זֶּה אוֹמֵר?</p>\n<p>אָמַר לוֹ, קַפּוּטְקָאִי, קְשֹׁר אֶת חֲמוֹרְךְ בַּגָּדֵר וְרֵד, שֶׁדְּבַר תּוֹרָה צָרִיךְ צַחוּת, אוֹ הֲפֹךְ לַאֲחוֹרֶיךְ וְלֵךְ אַחֲרַי וּתְכַוֵּן לִבְּךְ. אָמַר לוֹ, מִשּׁוּם מוֹרִי עָשִׂיתִי אֶת הַדֶּרֶךְ, וְאַחֲרֵי מוֹרִי אֶסְתַּכֵּל בַּשְּׁכִינָה.</p>\n<p>אָמַר לוֹ, בֹּא וּרְאֵה, דָּבָר זֶה הֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים וְלֹא פֵרְשׁוּ דָבָר. כֹּה אָמַר ה' לַסָּרִיסִים, מִי הֵם הַסָּרִיסִים? אֵלּוּ הֵם הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וּמְסָרְסִים עַצְמָם כָּל שֵׁשֶׁת יְמֵי הַשַּׁבָּת וְעוֹסְקִים בַּתּוֹרָה, וּבְלֵיל הַשַּׁבָּת מְזָרְזִים אֶת עַצְמָם בְּזִוּוּגָם מִשּׁוּם שֶׁיּוֹדְעִים הַסּוֹד הָעֶלְיוֹן בְּשָׁעָה שֶׁהַגְּבִירָה מִזְדַּוֶּגֶת בַּמֶּלֶךְ.</p>\n<p>וְאוֹתָם חֲבֵרִים שֶׁיּוֹדְעִים סוֹד זֶה, מְכַוְּנִים לִבָּם לֶאֱמוּנַת רִבּוֹנָם, וּמִתְבָּרְכִים בִּפְרִי מְעֵיהֶם בְּאוֹתוֹ הַלַּיְלָה. וְזֶהוּ שֶׁכָּתוּב אֲשֶׁר יִשְׁמְרוּ, כְּמוֹ שֶׁנֶּאֱמַר וְאָבִיו שָׁמַר אֶת הַדָּבָר.</p>\n<p>וְנִקְרָאִים סָרִיסִים וַדַּאי, בִּשְׁבִיל לְחַכּוֹת לְשַׁבָּת לִמְצֹא אֶת רְצוֹן רִבּוֹנָם, שֶׁכָּתוּב וּבָחֲרוּ בַּאֲשֶׁר חָפָצְתִּי. מַה זֶּה בַּאֲשֶׁר חָפָצְתִּי? זֶה זִוּוּג הַגְּבִירָה. וּמַחֲזִיקִים בִּבְרִיתִי, הַכֹּל אֶחָד. בִּבְרִיתִי סְתָם. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְקַדֵּשׁ בַּקְּדֻשָּׁה הַזּוֹ וְיוֹדֵעַ הַסּוֹד הַזֶּה.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב שֵׁשֶׁת יָמִים תַּעֲבֹד וְעָשִׂיתָ כָּל מְלַאכְתֶּךְ וְיוֹם הַשְּׁבִיעִי שַׁבָּת לַה' אֱלֹהֶיךְ וְגוֹ'. כָּל מְלַאכְתֶּךְ - בְּאוֹתָם שֵׁשֶׁת הַיָּמִים מְלֶאכֶת בְּנֵי הָאָדָם, וּמִשּׁוּם הַדָּבָר הַזֶּה לֹא מִזְדַּוְּגִים הַחֲבֵרִים, רַק בִּזְמַן שֶׁלֹּא נִמְצָא מִמַּעֲשֵׂי בְּנֵי אָדָם, אֶלָּא מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַה מַּעֲשֵׂהוּ? זִוּוּג הַגְּבִירָה לְהוֹצִיא נְשָׁמוֹת קְדוֹשׁוֹת לָעוֹלָם.</p>\n<p>וּמִשּׁוּם כָּךְ בַּלַּיְלָה הַזֶּה הַחֲבֵרִים מִתְקַדְּשִׁים בִּקְדֻשַּׁת רִבּוֹנָם וּמְכַוְּנִים לִבָּם, וְיוֹצְאִים בָּנִים מְעֻלִּים, בָּנִים קְדוֹשִׁים, שֶׁלֹּא סוֹטִים יָמִינָה וּשְׂמֹאלָה, בְּנֵי הַמֶּלֶךְ וְהַגְּבִירָה, וְעַל אֵלֶּה כָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. לַה' אֱלֹהֵיכֶם וַדַּאי. מִשּׁוּם שֶׁאֵלֶּה נִקְרָאִים בָּנִים שֶׁלּוֹ, בָּנִים לַמֶּלֶךְ וְלַגְּבִירָה.</p>\n<p>וְזוֹ דַעַת הַחֲבֵרִים שֶׁיּוֹדְעִים סוֹד זֶה, בָּזֶה נִדְבָּקִים, וּמִשּׁוּם כָּךְ נִקְרָאִים בָּנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וְאֵלֶּה הֵם שֶׁהָעוֹלָם מִתְקַיֵּם בִּשְׁבִילָם. וּכְשֶׁעוֹלֶה הָעוֹלָם בְּדִין, מִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּבָּנִים הַלָּלוּ וּמְרַחֵם עַל הָעוֹלָם, וְעַל זֶה כָּתוּב כֻּלֹּה זֶרַע אֱמֶת. זֶרַע אֱמֶת וַדַּאי. מַה זֶּה אֱמֶת? טַבַּעַת קְדוֹשָׁה שְׁלֵמָה, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב. (אמת זה הקדוש ברוך הוא) וְהַכֹּל אֶחָד. וּמִשּׁוּם כָּךְ זֶרַע אֱמֶת וַדַּאי.</p>\n<p>אָמַר לוֹ רַבִּי יוּדַאי, בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן. בָּרוּךְ הָרַחֲמָן, שֶׁהֲרֵי דָּבָר זֶה שָׁמַעְתִּי מִפִּיךְ. בָּכָה רַבִּי יוּדַאי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, לָמָּה בָּכִיתָ? אָמַר לוֹ, בָּכִיתִי, שֶׁאָמַרְתִּי אוֹי לְאוֹתָם בְּנֵי הָעוֹלָם שֶׁדַּרְכֵיהֶם כַּבְּהֵמוֹת וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים, שֶׁטּוֹב לָהֶם שֶׁלֹּא נִבְרְאוּ. אוֹי לָעוֹלָם כְּשֶׁיָּצָא מוֹרֵנוּ מִמֶּנּוּ, שֶׁמִּי יָכוֹל לְגַלּוֹת סוֹדוֹת, וּמִי יוֹדֵעַ אוֹתָם, וּמִי יִסְתַּכֵּל בְּדַרְכֵי הַתּוֹרָה?</p>\n<p>אָמַר לוֹ, חַיֶּיךְ, אֵין עוֹלָם אֶלָּא לְאוֹתָם חֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים נִסְתְּרוֹת הַתּוֹרָה. וַדַּאי בֶּאֱמֶת גָּזְרוּ הַחֲבֵרִים עַל עַמֵּי הָאֲרָצוֹת שֶׁמַּשְׁחִיתִים דַּרְכָּם וְלֹא יוֹדְעִים בֵּין יָמִין לִשְׂמֹאל, שֶׁהֲרֵי הֵם כִּבְהֵמוֹת שֶׁנָּאֶה לַעֲשׂוֹת בָּהֶם דִּין אֲפִלּוּ בְּיוֹם הַכִּפּוּרִים. וְעַל בְּנֵיהֶם כָּתוּב (הושעב) כִּי בְנֵי זְנוּנִים הֵמָּה. בְּנֵי זְנוּנִים מַמָּשׁ.</p>\n<p>אָמַר לוֹ, רַבִּי, פָּסוּק זֶה צָרִיךְ לְהִתְיַשֵּׁב בְּדַרְכּוֹ. כָּתוּב וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֶּן לוֹ. אֶתֶּן לָהֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶתֶּן לוֹ?</p>\n<p>אָמַר לוֹ, בֹּא וּרְאֵה, וְנָתַתִּי לָהֶם בְּבֵיתִי, מַה זֶּה בְּבֵיתִי? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא. (שמו של הקדוש ברוך הוא נקרא בית) וּבְחוֹמֹתַי, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סב) עַל חוֹמֹתַיִךְ יְרוּשָׁ לם הִפְקַדְתִּי שֹׁמְרִים. יָד וָשֵׁם, כְּלוֹמַר, שֶׁיֵּצְאוּ נְשָׁמוֹת קְדוֹשׁוֹת מִמָּקוֹם זֶה. וְאוֹתָהּ יָד, חֵלֶק הַשְּׁלֵמוּת, טוֹב מָלֵא מִבָּנִים וּמִבָּנוֹת. שֵׁם עוֹלָם אֶתֶּן לוֹ, לְאוֹתוֹ חֵלֶק שָׁלֵם, אֲשֶׁר לֹא יִכָּרֵת לְדוֹרֵי דוֹרוֹת. דָּבָר אַחֵר אֶתֶּן לוֹ - לְאוֹתוֹ שֶׁיּוֹדֵעַ סוֹד הַדָּבָר וְיִתְכַּוֵּן בְּמַה שֶּׁצָּרִיךְ לְכַוֵּן.</p>\n<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבתֵיכֶם בְּיוֹם הַשַּׁבָּת. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא יֵרָאֶה דִין בַּיּוֹם הַזֶּה. וְאִם תֹּאמַר, הֲרֵי לְגָבוֹהַּ עוֹלֶה? בְּכֹל מֹשְׁבתֵיכֶם אָמַר, וְלֹא לְגָבוֹהַּ. וְאוֹתוֹ שֶׁעוֹלֶה לְגָבוֹהַּ, עוֹלֶה לִכְפּוֹת דִּין אַחֵר. שֶׁשָּׁנִינוּ, יֵשׁ אֵשׁ אוֹכֵל אֵשׁ, וְאֵשׁ הַמִּזְבֵּחַ אוֹכֵל אֵשׁ אַחֵר.</p>\n<p>וּמִשּׁוּם כָּךְ מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ בַּיּוֹם הַזֶּה מִכָּל שְׁאָר הַיָּמִים. וּבִזְמַן שֶׁמִּתְגַּלֶּה הָעַתִּיק, לֹא נִרְאֶה דִין כְּלָל, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים נִמְצָאִים בְּשִׂמְחָה שְׁלֵמָה, וְהַדִּין לֹא שׁוֹלֵט.</p>\n<p>שָׁנִינוּ, כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. שֵׁשֶׁת יָמִים וַדַּאי, וְלֹא בְּשֵׁשֶׁת. וְהַיָּמִים הַקְּדוֹשִׁים הָעֶלְיוֹנִים הַלָּלוּ נִקְרָאִים יָמִים שֶׁהַשֵּׁם הַקָּדוֹשׁ נִכְלָל בָּהֶם, וְהֵם נִכְלָלִים בּוֹ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, עֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011654,"<p>כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. רַבִּי חִיָּיא פָּתַח, (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן וְגוֹ'. וְנָהָר - זוֹ נְבִיעַת הַמַּעְיָן שֶׁיּוֹצֵא תָמִיד וְלֹא פוֹסֵק, וּמִנְּהַר הַמַּעְיָן הַזֶּה נִשְׁקָה כָּל גַּן הָעֵדֶן. וְאוֹתוֹ נָהָר שֶׁל הַמַּעְיָן הַקָּדוֹשׁ נִקְרָא אָ\"ב. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נוֹבֵעַ לָזוּן אֶת הַגָּן.</p>\n<p>רַבִּי אַבָּא אָמַר, עֵדֶן מַמָּשׁ נִקְרָא אָב, מִשּׁוּם שֶׁעֵדֶן זֶה נִמְצָא מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אַיִן, וּמִשּׁוּם כָּךְ נִקְרָא אָב. וַהֲרֵי בֵּאַרְנוּ, מִמָּקוֹם שֶׁמַּתְחִיל לְהִמָּשֵׁךְ הַכֹּל נִקְרָא אַתָּה, וְנִקְרָא אָב, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) כִּי אַתָּה אָבִינוּ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, כַּבֵּד אֶת אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אֶת אָבִיךְ, אֶת דַּוְקָא, לְהַכְלִיל שְׁכִינָה (עליונה). רַבִּי יְהוּדָה אָמַר, כַּבֵּד אֶת אָבִיךְ - סְתָם. וְאֶת אִמֶּךְ - סְתָם. שֶׁהֲרֵי הַכֹּל הָיָה בְּמִנְיָן. אֶת - לְרַבּוֹת כָּל מַה שֶּׁלְּמַעְלָה וָמַטָּה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, זֶה שֶׁאָמַר רַבִּי אַבָּא, מִמָּקוֹם שֶׁמַּתְחִיל לְהִמָּשֵׁךְ הַכֹּל, נִקְרָא אַתָּה, יָפֶה. שֶׁהֲרֵי לָמַדְנוּ שֶׁאוֹתוֹ הַנִּסְתָּר וְאֵין בּוֹ הַתְחָלָה נִקְרָא הוּא. מִמָּקוֹם שֶׁהָרֵאשִׁית נִמְצֵאת נִקְרָא אַתָּה. וְנִקְרָא אָב. וְהַכֹּל אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, וַדַּאי הַכֹּל אֶחָד. כַּבֵּד אֶת אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶת אִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. שֶׁהֲרֵי שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם - אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּנִים. וּמִשּׁוּם כָּךְ הַסְּתִימוּת שֶׁל הַדָּבָר, כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, לְהַכְלִיל אֶת הַכֹּל שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. רַבִּי יִצְחָק אָמַר, לְהַכְלִיל בּוֹ אֶת רַבּוֹ, שֶׁהוּא מַכְנִיס אוֹתוֹ לָעוֹלָם הַבָּא. אָמַר רַבִּי יְהוּדָה, הוּא בִּכְלַל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>שָׁנִינוּ, בַּחֲמֵשׁ הָאֲמִירוֹת הַלָּלוּ כָּלוּל הַכֹּל. בַּחֲמֵשׁ הָאֲמִירוֹת הַלָּלוּ נֶחְקְקוּ חָמֵשׁ אֲחֵרוֹת, וַדַּאי חָמֵשׁ תּוֹךְ הֶחָמֵשׁ. הָכֵיצַד? אָנֹכִי ה' אֱלֹהֶיךְ - כְּנֶגֶד לֹא תִרְצַח. שֶׁשָּׁנִינוּ, (אמר רבי יצחק אמר רבי יהודה) שְׁנֵי אֵלֶּה בִּכְלַל אֶחָד נִכְלְלוּ, שֶׁמִּי שֶׁהוֹרֵג מַקְטִין הַדְּמוּת וְצֶלֶם שֶׁל רִבּוֹנוֹ, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּתוּב (בראשית ט) שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ וְגוֹ'. (שפך דם האדם) מִי שֶׁשּׁוֹפֵךְ דָּם כְּאִלּוּ מַקְטִין הַדְּמוּת וְהַצֶּלֶם שֶׁלְּמַעְלָה. כְּלוֹמַר, לֹא הִקְטִין דְּמוּת זוֹ, אֶלָּא דְּמוּת אַחֶרֶת, מַשְׁמָע שֶׁכָּתוּב שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ. בָּאָדָם הָעֶלְיוֹן מַגִּיעַ הַפְּגָם הַזֶּה מֵאוֹתוֹ דָּם שֶׁשָּׁפַךְ. מָה הַטַּעַם? מִשּׁוּם כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וּמִשּׁוּם כָּךְ זֶה בָּזֶה תָּלוּי.</p>\n<p>לֹא יִהְיֶה לְךְ - כְּנֶגֶד לֹא תִנְאָף. זֶה מְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּרְשָׁם בָּאָדָם. וּבָזֶה כַמָּה וְכַמָּה חֲטָאִים וּגְזֵרוֹת וָעֳנָשִׁים תְּלוּיִים. וּמִי שֶׁמְּשַׁקֵּר בָּזֶה, מְשַׁקֵּר בּוֹ בַּמֶּלֶךְ, שֶׁכָּתוּב (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ. וְכָתוּב לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם, וְזֶה בָּזֶה תָּלוּי.</p>\n<p>לֹא תִשָּׂא - כְּנֶגֶד לֹא תִגְנֹב. וְכָתוּב (משלי כט) חוֹלֵק עִם גַּנָּב שׂוֹנֵא נַפְשׁוֹ אָלָה יִשְׁמַע וְלֹא יַגִּיד. וַדַּאי זֶה בָּזֶה תָּלוּי, שֶׁהֲרֵי הַגַּנָּב לָזֶה מִזְדַּמֵּן, לְהִשָּׁבַע בְּשֶׁקֶר. מִי שֶׁעוֹשֶׂה זֶה, עוֹשֶׂה זֶה.</p>\n<p>זָכוֹר אֶת יוֹם הַשַּׁבָּת - כְּנֶגֶד לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. שֶׁאָמַר רַבִּי יוֹסֵי, שַׁבָּת נִקְרֵאת עֵדוּת, וְצָרִיךְ הָאָדָם לְהָעִיד עַל זֶה, שֶׁכָּתוּב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' וְגוֹ'. וְשַׁבָּת כְּלָל (עדות) שֶׁל הַכֹּל. וְאָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וּמִי שֶׁמֵּעִיד שֶׁקֶר - מְשַׁקֵּר בַּשַּׁבָּת, שֶׁהִיא עֵדוּת אֱמֶת. וּמִי שֶׁמְּשַׁקֵּר בַּשַּׁבָּת - מְשַׁקֵּר בְּכָל הַתּוֹרָה. וּמִשּׁוּם כָּךְ זֶה בָּזֶה תָּלוּי.</p>\n<p>כַּבֵּד אֶת אָבִיךְ - כְּנֶגֶד לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ. וְאָמַר רַבִּי יִצְחָק, כַּבֵּד אֶת אָבִיךְ - אָבִיךְ מַמָּשׁ. שֶׁהֲרֵי מִי שֶׁחוֹמֵד אִשָּׁה וּמוֹלִיד בֵּן, הַהוּא מְכַבֵּד אֶת הָאַחֵר שֶׁאֵינוֹ אָבִיו, וְכָתוּב כַּבֵּד אֶת אָבִיךְ וְגוֹ', לֹא תַחְמֹד בֵּית רֵעֶךְ שָׂדֵהוּ. וְכָתוּב כָּאן, עַל הָאֲדָמָה אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ. אוֹתוֹ שֶׁנָּתַן לְךְ יִהְיֶה שֶׁלְּךְ, וְלֹא תַחְמֹד אַחֵר. וַדַּאי שֶׁזֶּה תָּלוּי בָּזֶה.</p>\n<p>וְאֵלּוּ הֶחָמֵשׁ הָרִאשׁוֹנוֹת כּוֹלְלוֹת חָמֵשׁ אַחֲרוֹנוֹת, וּמִשּׁוּם כָּךְ, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. שֶׁהַכֹּל נַעֲשֶׂה יָמִין. וְעַל זֶה בַּחֲמִשָּׁה קוֹלוֹת נִתְּנָה הַתּוֹרָה. אָמַר רַבִּי יְהוּדָה, כֻּלָּם הָיוּ חָמֵשׁ בְּתוֹךְ חָמֵשׁ, כְּנֶגְדָּם חֲמִשָּׁה חֻמְשֵׁי תוֹרָה.</p>\n<p>שָׁנָה רַבִּי אֶלְעָזָר, בְּעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ נֶחְקְקוּ כָּל מִצְווֹת הַתּוֹרָה, גְּזֵרוֹת וָעֳנָשִׁים, טָהוֹר וְטָמֵא, עֲנָפִים וְשָׁרָשִׁים, אִילָנוֹת וּנְטָעִים, שָׁמַיִם וָאָרֶץ, יָם וּתְהוֹמוֹת, שֶׁהֲרֵי הַתּוֹרָה הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נֶחְקַק בְּעֶשֶׂר אֲמִירוֹת - אַף הַתּוֹרָה נֶחְקְקָה בְּעֶשֶׂר אֲמִירוֹת. עֶשֶׂר הָאֲמִירוֹת הַלָּלוּ הֵם שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל הַתּוֹרָה הִיא שֵׁם אֶחָד, שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה בָּהּ. מִי שֶׁזּוֹכֶה בַּתּוֹרָה זוֹכֶה בַּשֵּׁם הַקָּדוֹשׁ (של הקדושברוך הוא). רַבִּי יוֹסֵי אוֹמֵר, זוֹכֶה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא מַמָּשׁ (וכנסת ישראל), שֶׁהֲרֵי הוּא וּשְׁמוֹ אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן.</p>"],[9522011655,"<p>לֹא תַעֲשׂוּן אִתִּי אֱלֹהֵי כֶסֶף וֵאלֹהֵי זָהָב. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב. אַף עַל גַּב שֶׁלִּי הַכֶּסֶף וְלִי הַזָּהָב - לֹא תַעֲשׂוּן אִתִּי. אִתִּי, כְּלוֹמַר אוֹתִי.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּתוּב (ירמיה י) מֵאֵין כָּמוֹךְ ה' גָּדוֹל אַתָּה וְגָדוֹל שִׁמְךְ בִּגְבוּרָה וְגוֹ'. (גדול אתה וגדול שמך) גָּדוֹל אַתָּה - הַיְנוּ לִי הַכֶּסֶף. וְגָדוֹל שִׁמְךְ בִּגְבוּרָה - הַיְנוּ וְלִי הַזָּהָב. שְׁנֵי הַגְּוָנִים הַלָּלוּ לֹא נִרְאִים וְלֹא מִתְפָּאֲרִים, פְּרָט לִכְשֵׁהֶם חֲקוּקִים בְּמָקוֹם אֶחָד. בְּאֵיזֶה מָקוֹם נֶחְקְקוּ? בְּיִשְׂרָאֵל. כָּאן נִרְאִים הַגְּוָנִים לְהִתְפָּאֵר, כַּכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>רַבִּי יְהוּדָה פָּתַח, (שם סא) שׂוֹשׂ אָשִׂישׂ בַּה' תָּגֵל נַפְשִׁי בֵּאלֹהַי וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהַשִּׂמְחָה וְהַתַּפְנוּק שֶׁלָּהֶם בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב שׂוֹשׂ אָשִׂישׂ בַּה'. כֵּיוָן שֶׁאָמַר בַּה', לָמָּה כָּתוּב בֵּאלֹהַי? אֶלָּא כָּךְ אָמְרוּ יִשְׂרָאֵל: אִם בְּרַחֲמִים בָּא עָלֵינוּ - שׂוֹשׂ אָשִׂישׂ בַּה', וְאִם בְּדִין - תָּגֵל נַפְשִׁי בֵּאלֹהַי.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאֵלֶּה נֶחְקְקוּ בוֹ, שֶׁכָּתוּבּ כִּי הִלְבִּישַׁנִי בִּגְדֵי יֶשַׁע. מַה זֶּה בִּגְדֵי יֶשַׁע? גְּוָנִים שֶׁנֶּחְקְקוּ לְהִסְתַּכֵּל בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר יִשְׁעוּ וְגוֹ' אֶל ה'. יֶשַׁע הוּא הִסְתַּכְּלוּת. מִי שֶׁרוֹצֶה לְהִסְתַּכֵּל בִּי, יִסְתַּכֵּל בַּגְּוָנִים שֶׁלִּי. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב מְעִיל צְדָקָה יְעָטָנִי, צְדָקָה מַמָּשׁ, שֶׁהַגְּוָנִים נֶחְקְקוּ בוֹ. כֶּחָתָן יְכַהֵן פְּאֵר, זֶה גָּוֶן אֶחָד. וְכַכַּלָּה תַּעְדֶּה כֵלֶיהָ, זֶה גָּוֶן אַחֵר. וּכְשֶׁהַגְּוָנִים מִתְחַבְּרִים, בְּאוֹתָהּ שָׁעָה נִרְאִים, וְכֻלָּם מִשְׁתּוֹקְקִים לִרְאוֹת וּלְהִסְתַּכֵּל בּוֹ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, שׂוֹשׂ אָשִׂישׂ בַּה' - שְׁתֵּי חֶדְווֹת. בַּה' - בְּרַחֲמִים. תָּגֵל נַפְשִׁי - הֲרֵי (אחת בחדוה) בְּדִין. אָמַר רַבִּי יְהוּדָה, בַּכֹּל שִׂמְחָה שֶׁל שִׂמְחָה. וְחֶדְוָה שֶׁל צִיּוֹן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ אֶת יִשְׂרָאֵל בְּשִׂמְחָה יְתֵרָה מֵהַכֹּל, שֶׁכָּתוּב (שם לה) וּפְדוּיֵי ה' יְשֻׁבוּן וּבָאוּ צִיּוֹן בְּרִנָּה וְגוֹ'. וּפְדוּיֵי ה' יְשֻׁבוּן - הֲרֵי אַחַת. וּבָאוּ צִיּוֹן בְּרִנָּה - הֲרֵי שְׁתַּיִם. וְשִׂמְחַת עוֹלָם עַל רֹאשָׁם - הֲרֵי שָׁלֹשׁ. שָׂשׂוֹן וְשִׂמְחָה יַשִּׂיגוּ - הֲרֵי אַרְבַּע. כְּנֶגְדָּם שֶׁל אַרְבַּע פְּעָמִים שֶׁהִתְפַּזְּרוּ יִשְׂרָאֵל בֵּין הָעַמִּים, וְאָז כָּתוּב (שם יב) וַאֲמַרְתֶּם בַּיּוֹם הַהוּא הוֹדוּ לַה' קִרְאוּ בִשְׁמוֹ וְגוֹ'.</p>"],[9522011656,"<p>וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה. כָּל הַדְּבָרִים - כְּלָל זֶה הוּא כְּלָל שֶׁל הַכֹּל, כְּלָל שֶׁל מַעְלָה וּמַטָּה.</p>\n<p>אָנֹכִי, סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ יה\"ו. אָנֹכִי, נִגְלֶה וְנִגְנָז, נִגְלֶה בְּסוֹד קָדוֹשׁ שֶׁל הַכִּסֵּא, שֶׁהַלְּבָנָה עוֹמֶדֶת בִּשְׁלֵמוּת כְּאֶחָד, כְּשֶׁהַשֶּׁמֶשׁ שׁוֹלֵט וְהַלְּבָנָה מְאִירָה, וְאֵין לָהּ שֶׁבַח פְּרָט לַשֶּׁבַח שֶׁל הָאוֹר שֶׁמֵּאִיר עָלֶיהָ.</p>\n<p>אָנֹכִי, בְּהַשְׁלָמַת סוֹדוֹת שֶׁל שְׁלֵמוּת שֶׁל הַכִּסֵּא לְמַטָּה, וְהִתְעַלּוּ הַחַיּוֹת הַקְּדוֹשׁוֹת, וְהִיא הִתְתַּקְּנָה בְּתִקּוּנֶיהָ. וּכְשֶׁהִיא יָפָה לְמַרְאֶה וּבַעְלָהּ בָּא אֵלֶיהָ, אָז נִקְרֵאת אָנֹכִי.</p>\n<p>אָנֹכִי, סוֹד שֶׁל הַכֹּל כְּאֶחָד, בַּכְּלָל שֶׁל כָּל הָאוֹתִיּוֹת בִּשְׁבִילֵי הַתּוֹרָה שֶׁיָּצְאוּ מִתּוֹךְ סוֹד עֶלְיוֹן. בָּאָנֹכִי הַזֶּה תְּלוּיִים עֶלְיוֹנִים וְתַחְתּוֹנִים. אָנֹכִי, סוֹד לָתֵת שָׂכָר טוֹב לַצַּדִּיקִים שֶׁמְּחַכִּים לוֹ וְשׁוֹמְרִים אֶת מִצְווֹת הַתּוֹרָה, בָּזֶה יֵשׁ לָהֶם בִּטָּחוֹן כָּרָאוּי לָעוֹלָם הַבָּא, וְסִימָנְךְ - אֲנִי פַרְעֹה.</p>\n<p>אָנֹכִי וְלֹא יִהְיֶה לְךְ נֶאֱמַר בְּסוֹד הַתּוֹרָה, וְזֶהוּ זָכוֹר וְשָׁמוֹר. אָנֹכִי, סוֹד נִסְתָּר וְגָנוּז בְּכָל אוֹתָן דְּרָגוֹת שֶׁל הָעוֹלָם הָעֶלְיוֹן בִּכְלָל אֶחָד. וְכֵיוָן שֶׁנֶּאֱמַר אָנֹכִי, הִתְחַבֵּר הַכֹּל כְּאֶחָד, בְּסוֹד אֶחָד.</p>\n<p>אָנֹכִי, סוֹד שֶׁל שְׁנֵי כִּסְאוֹת. אֲנִי ה' - שֶׁל כִּסֵּא אַחֵר. (אני כסא אחד. כ' כסא אחר עליון).</p>\n<p>אָנֹכִי, שֶׁכְּשֶׁנִּטְהָר הַמִּקְדָּשׁ וְנָכְרִי לֹא יִקְרַב אֵלָיו וְהַמִּקְדָּשׁ מֵאִיר לְבַדּוֹ, שֶׁהֲרֵי הִתְבַּטֵּל בְּאוֹתָהּ שָׁעָה יֵצֶר הָרָע מִן הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְעַלָּה בִּכְבוֹדוֹ לְבַדּוֹ, וְאָז נֶאֱמַר אָנֹכִי ה' אֱלֹהֶיךְ. סוֹד שָׁלֵם בַּשֵּׁם הַקָּדוֹשׁ. א' - לְיַחֵד סוֹד הַשֵּׁם הַקָּדוֹשׁ בְּדַרְגוֹתָיו לִהְיוֹת אֶחָד, מִשּׁוּם שֶׁסּוֹדוֹ הוּא ו'. נ' - סוֹד לִירָא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא וְלָדַעַת שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן, וְיֵשׁ שָׂכָר טוֹב לַצַּדִּיקִים וּפֻרְעָנוּת לָרְשָׁעִים, מִשּׁוּם שֶׁהַסּוֹד שֶׁלּוֹ ה' תַּחְתּוֹנָה.</p>\n<p>כ', ' לְקַדֵּשׁ אֶת הַשֵּׁם הַקָּדוֹשׁ בְּכָל יוֹם, וּלְהִתְקַדֵּשׁ בִּדְרָגוֹת קְדוֹשׁוֹת, וּלְהִתְפַּלֵּל אֵלָיו תְּפִלָּה בְּכָל זְמַן לְהַעֲלוֹת הַכֶּתֶר הָעֶלְיוֹן, סוֹד שֶׁל הַכִּסֵּא הָעֶלְיוֹן עַל גַּבֵּי הַחַיּוֹת הָעֶלְיוֹנוֹת כָּרָאוּי, וְהַסּוֹד שֶׁלּוֹ ה' עֶלְיוֹנָה.</p>\n<p>י', ' לְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, וְלָמוּל מִילָה בְּסוֹד לִשְׁמֹנָה יָמִים, וּלְקַדֵּשׁ הַבְּכוֹר, וּלְהָנִיחַ תְּפִלִּין וְצִיצִית וּמְזוּזָה, וְלִמְסֹר אֶת הַנֶּפֶשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וּלְהִדָּבֵק בּוֹ. אֵלֶּה הֵן שְׁתֵּים עֶשְׂרֵה מִצְווֹת עֶלְיוֹנוֹת שֶׁכּוֹלְלוֹת מָאתַיִם שְׁלֹשִׁים וְשֵׁשׁ מִצְווֹת אֲחֵרוֹת שֶׁהֵן בַּסּוֹד שֶׁל אָנֹכִי, כְּלָל שֶׁל זָכוֹר. וְאוֹת זוֹ לֹא מִתְחַלֶּפֶת בְּמָקוֹם אַחֵר, זֶה מִשּׁוּם שֶׁהִיא י', סוֹד עֶלְיוֹן, כְּלָל שֶׁל הַתּוֹרָה, וּבִשְׁתֵּים עֶשְׂרֵה הַלָּלוּ יֵשׁ שְׁתֵּים עֶשְׂרֵה מִדּוֹת הָרַחֲמִים שֶׁתְּלוּיוֹת מֵהֶם, וְאַחַת שֶׁשּׁוֹלֶטֶת לִהְיוֹת שְׁלֹשׁ עֶשְׂרֵה.</p>\n<p>לֹא יִהְיֶה לְךְ, סוֹד שֶׁל שָׁמוֹר בִּשְׁלֹשׁ מֵאוֹת שִׁשִּׁים וְחָמֵשׁ מִצְווֹת הַתּוֹרָה. ל' - סוֹד שֶׁלֹּא לָתֵת כָּבוֹד וּגְדֻלָּה לֵאלוֹהַּ אַחֵר, ל' - מִגְדָּל שֶׁפּוֹרֵחַ וְעוֹלֶה בָּאֲוִיר, שֶׁלֹּא יִסְטֶה הַלֵּב לִבְנוֹת לֵאלוֹהַּ אַחֵר, כְּמוֹ שֶׁיֵּשׁ סוֹד שֶׁל בּוֹנֵה מִגְדָּל (לאלוה אחר). ל' - שֶׁלֹּא לִפְנוֹת בִּדְיוֹקָן שֶׁל עֲבוֹדָה זָרָה, שֶׁלֹּא לְהַרְהֵר אַחֲרֶיהָ, שֶׁלֹּא לְהִשְׁתַּחֲווֹת וְלֹא לִכְפּוֹת עַצְמוֹ לֵאלוֹהַּ אַחֵר.</p>\n<p>שֶׁלֹּא לִסְטוֹת אַחַר אוֹב וְיִדְּעוֹנִי בְּסוֹד שֶׁל דְּמוּת אָדָם, וְלֹא בִּדְמוּת אַחֶרֶת. א': שֶׁלֹּא לִשְׁאֹל מִן הַמֵּתִים וְלֹא לַעֲשׂוֹת כְּשָׁפִים. א': שֶׁלֹּא יִשָּׁבַע בְּפִיו בְּשֵׁם שֶׁל אֱלוֹהַּ אַחֵר. עַד כָּאן שְׁתֵּים עֶשְׂרֵה אֲחֵרוֹת שֶׁהֵם מִצְווֹת שָׁמוֹר, וּבַשְּׁתֵּים עֶשְׂרֵה הַלָּלוּ תְּלוּיוֹת שְׁלֹשׁ מֵאוֹת חֲמִשִּׁים וְשָׁלֹשׁ מִצְווֹת שֶׁל שָׁמוֹר אֲחֵרוֹת שֶׁכְּלוּלוֹת בַּשְּׁתֵּים עֶשְׂרֵה הַלָּלוּ, וְסוֹד זֶה אָנֹכִי.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, עוֹד שָׁנִינוּ, אָנֹכִי - כְּלָל שֶׁל מַעְלָה וּמַטָּה, כְּלָל שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּלָל שֶׁל חַיּוֹת הַקְּדוֹשׁוֹת שֶׁכְּלוּלוֹת בּוֹ, הַכֹּל הוּא בְּסוֹד שֶׁל אָנֹכִי. לֹא יִהְיֶה לְךְ - לְמַטָּה, סוֹד שֶׁל שְׁתֵּים עֶשְׂרֵה הַחַיּוֹת הַתַּחְתּוֹנוֹת.</p>\n<p>לֹא תַעֲשֶׂה לְךְ פֶסֶל. נִפְסְלוּ מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, מֵאוֹתוֹ מָקוֹם קָדוֹשׁ. פֶּסֶל - פְּסֹלֶת שֶׁל קְדֻשָּׁה, שֶׁהוּא סוֹד שֶׁל אֱלִיל אַחֵר, וְסוֹד זֶה כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. וְכָל תְּמוּנָה, זֶהוּ שֶׁכָּתוּב (שמות ט) וְאֵשׁ מִתְלַקַּחַת. כִּי אָנֹכִי ה' אֱלֹהֶיךְ, כְּדֵי לְעוֹרֵר אֶת הַלֵּב לְמַעְלָה וְלֹא לָרֶדֶת לְמַטָּה, וְלֹא לִקְרַב לְשַׁעַר הַבַּיִת אֵל קַנָּא, שֶׁהַקִּנְאָה הִיא בְּאוֹתוֹ מָקוֹם.</p>\n<p>וְסוֹד זֶה - (משליל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ. וְהוּא, לֹא תַעֲשֶׂה לְךְ - אֶחָד. פֶסֶל - שְׁנַיִם. וְכָל תְּמוּנָה - שָׁלֹשׁ. וִאֶרֶץ זוֹ עַל זֶה הִיא הִתְרַגְּזָה.</p>\n<p>פֹּקֵֹד עֲון אָבוֹת עַל בָּנִים עַל שִׁלֵּשִׁים וְעַל רִבֵּעִים. אִילָן אֶחָד שֶׁנִּנְטַע פַּעַם וּפַעֲמַיִם וְשָׁלֹשׁ פְּעָמִים וְאַרְבַּע פְּעָמִים, וְנִפְקַד עַל חֲטָאִים רִאשׁוֹנִים אָב וּבֵן. שְׁלִישִׁי וּרְבִיעִי אֶחָד הוּא כְּשֶׁלֹּא הִתְתַּקֵּן וְלֹא חָשַׁשׁ לְהִתְתַּקֵּן, וְכֵן בַּהִפּוּךְ שֶׁל זֶה, לְאִילָן שֶׁהִתְתַּקֵּן כָּרָאוּי וְעוֹמֵד עַל קִיּוּמוֹ (אז) וְעוֹשֶׂה חֶסֶד וְגוֹ'.</p>"],[9522011657,"<p>לֹא תִשָּׂא. אֶת הַסּוֹד הַזֶּה הֲרֵי בֵּאֲרוּ הַחֲבֵרִים, מִשּׁוּם שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁתַל אֶת הָעוֹלָם, הִטְבִּיעַ בְּתוֹךְ הַתְּהוֹמוֹת צְרוֹר אֶחָד חָקוּק בַּשֵּׁם הַקָּדוֹשׁ, וְהִטְבִּיעַ אוֹתוֹ בְּתוֹךְ הַתְּהוֹם, וּכְשֶׁהַמַּיִם רוֹצִים לַעֲלוֹת, הֵם רוֹאִים אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ חָקוּק עַל אוֹתוֹ צְרוֹר, וְשָׁבִים וְנִשְׁקָעִים וְחוֹזְרִים לְאָחוֹר, וְהַשֵּׁם הַזֶּה עוֹמֵד עַד הַיּוֹם הַזֶּה בְּתוֹךְ הַתְּהוֹם.</p>\n<p>וּבְשָׁעָה שֶׁנִּשְׁבָּעִים בְּנֵי אָדָם עַל אֱמֶת, בְּקִיּוּם שֶׁל אֱמֶת, אוֹתוֹ הַצְּרוֹר עוֹלֶה וּמְקַבֵּל אֶת אוֹתָהּ שְׁבוּעָה, וְחוֹזֵר וּמִתְקַיֵּם עַל הַתְּהוֹם וְהָעוֹלָם מִתְקַיֵּם, וְאוֹתָהּ שְׁבוּעַת אֱמֶת עוֹמֶדֶת לְעוֹלָם.</p>\n<p>וּבְשָׁעָה שֶׁנִּשְׁבָּעִים בְּנֵי אָדָם שְׁבוּעָה לַשֶּׁקֶר, אוֹתוֹ הַצְּרוֹר עוֹלֶה לְקַבֵּל אֶת אוֹתָהּ שְׁבוּעָה. כֵּיוָן שֶׁרוֹאֶה שֶׁהוּא שֶׁקֶר, אָז אוֹתוֹ צְרוֹר שֶׁהָיָה עוֹלֶה שָׁב לְאָחוֹר, וְהַמַּיִם הוֹלְכִים וְשָׁטִים, וְהָאוֹתִיּוֹת שֶׁל אוֹתוֹ צְרוֹר פּוֹרְחוֹת לְתוֹךְ הַתְּהוֹמוֹת וּמִתְפַּזְּרוֹת, וְרוֹצִים הַמַּיִם לְכַסּוֹת אֶת הָעוֹלָם וּלְהַחֲזִירוֹ כְּמוֹ מִקֹּדֶם.</p>\n<p>עֵד שֶׁמַּזְמִין (שרומז) הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְמֻנֶּה אֶחָד, יְעַזְרִיאֵ\"ל, שֶׁמְּמֻנֶּה עַל שִׁבְעִים מַפְתְּחוֹת בַּסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְנִכְנָס לְאוֹתוֹ צְרוֹר, וְחוֹקֵק בּוֹ אוֹתִיּוֹת כְּמוֹ מִקֹּדֶם, וְאָז מִתְקַיֵּם הָעוֹלָם וְחוֹזְרִים הַמַּיִם לִמְקוֹמָם, (שאותו צרור ומרגיש את האותיות של השם הקדוש וחוקק אותן כבתחלה, וחוזרים המים למקומם, ואז מתקים העולם) וְעַל זֶה כָּתוּב לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא.</p>\n<p>מִצְוָה י\"ב - לְהִשָּׁבַע בִּשְׁמוֹ בְּדֶרֶךְ אֱמֶת. וּמִי שֶׁנִּשְׁבָּע שְׁבוּעָה הוּא כּוֹלֵל אֶת עַצְמוֹ בְּאוֹתָן שֶׁבַע דְּרָגוֹת עֶלְיוֹנוֹת שֶׁהַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְלָל בָּהֶן. וַהֲרֵי הֵם שֵׁשׁ. אוֹתוֹ אָדָם שֶׁנִּשְׁבָּע שְׁבוּעַת אֱמֶת עַל פִּי בֵּית דִּין, כּוֹלֵל אֶת עַצְמוֹ בָּהֶן, וְהוּא שְׁבִיעִי לְקַיֵּם אֶת הַשֵּׁם הַקָּדוֹשׁ בִּמְקוֹמוֹ, וְעַל כֵּן כָּתוּב וּבִשְׁמוֹ תִּשָּׁבֵעַ. וּמִי שֶׁנִּשְׁבָּע שְׁבוּעָה לְחִנָּם וְלַשֶּׁקֶר, גּוֹרֵם לְאוֹתוֹ מָקוֹם שֶׁלֹּא יִתְקַיֵּם בִּמְקוֹמוֹ.</p>\n<p>שְׁבוּעָה לְקַיֵּם מִצְוַת רִבּוֹנוֹ - זוֹהִי שְׁבוּעַת אֱמֶת, כְּשֶׁאוֹתוֹ יֵצֶר הָרָע מְקַטְרֵג לָאָדָם וּמְפַתֶּה אוֹתוֹ לַעֲבֹר עַל מִצְוַת רִבּוֹנוֹ. זוֹהִי שְׁבוּעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ, וְצָרִיךְ לָאָדָם לְהִשָּׁבַע בְּרִבּוֹנוֹ עַל זֶה, וְהוּא שִׁבְחוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ, כְּמוֹ בֹּעַז, שֶׁכָּתוּב חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁהֲרֵי יֵצֶר הָרָע הָיָה מְקַטְרֵג לוֹ, וְנִשְׁבַּע עַל זֶה.</p>\n<p>נֶדֶר הוּא לְמַעְלָה, וְהֵם חַיֵּי הַמֶּלֶךְ, סוֹד שֶׁל רמ\"ח אֵיבָרִים וּשְׁנֵים עָשָׂר קְשָׁרִים כְּחֶשְׁבּוֹן וְנֶדֶ\"ר. וְעַל זֶה חָמוּר מִשְּׁבוּעָה. חַיֵּי הַמֶּלֶךְ אֵלֶּה, שֶׁנּוֹתֵן חַיִּים לְכָל הָאֵיבָרִים הַלָּלוּ, וְנִקְרָאִים כָּךְ בִּשְׁבִיל אוֹתָם חַיִּים, וְאוֹתָם חַיִּים יוֹרְדִים מִמַּעְלָה לְמַטָּה, לְאוֹתוֹ מְקוֹר הַחַיִּים, וּמֵאוֹתוֹ מָקוֹר יוֹרְדִים לְמַטָּה לְכָל אוֹתָם אֵיבָרִים.</p>\n<p>שְׁבוּעָה לְקַיֵּם דַּרְגָּה שֶׁלְּמַטָּה, סוֹד הַשֵּׁם הַקָּדוֹשׁ. וְזֶה נִקְרָא מֶלֶךְ עַצְמוֹ, שֶׁל רוּחַ עֶלְיוֹנָה וְגוּף שֶׁלּוֹ, לִשְׁרוֹת בְּתוֹכוֹ וְלָדוּר בּוֹ כְּמוֹ הָרוּחַ שֶׁשּׁוֹרָה בְּתוֹךְ הַגּוּף, וְעַל זֶה נִקְרָא מֶלֶךְ עַצְמוֹ, שֶׁרוּחַ עֶלְיוֹנָה הִשְׁתּוֹקְקוּת שֶׁלָּהּ לִשְׁרוֹת בְּתוֹכוֹ עַצְמוֹ שֶׁל הַהוּא הַנִּסְתָּר לְמַעְלָה. וּמִשּׁוּם כָּךְ מִי שֶׁנִּשְׁבָּע בֶּאֱמֶת, הוּא מְקַיֵּם אֶת אוֹתוֹ מָקוֹם, וּכְשֶׁעוֹמֵד הַמָּקוֹם הַזֶּה מְקֻיָּם, מְקַיֵּם אֶת כָּל הָעוֹלָם. הַנֶּדֶר שׁוֹרֶה עַל הַכֹּל, עַל מִצְוָה, וְעַל רְשׁוּת שֶׁלֹּא כָּךְ בִּשְׁבוּעָה, וְכָךְ פֵּרְשׁוּהָ הַחֲבֵרִים.</p>"],[9522011658,"<p>זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, זֶהוּ סוֹד שֶׁל הַבְּרִית הַקָּדוֹשׁ. וּמִשּׁוּם שֶׁבִּבְרִית זוֹ עוֹמְדִים כָּל הַמְּקוֹרוֹת שֶׁל אֵיבְרֵי הַגּוּף וְהוּא כְּלַל הַכֹּל, כְּמוֹ זֶה שַׁבָּת הִיא כְּלָל שֶׁל הַתּוֹרָה, וְכָל סוֹדוֹת הַתּוֹרָה תְּלוּיִים בָּהּ, וְקִיּוּם שֶׁל הַשַּׁבָּת כְּמוֹ קִיּוּם שֶׁל כָּל הַתּוֹרָה. מִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה.</p>\n<p>מִצְוָה כ\"ד - לִהְיוֹת זוֹכֵר אֶת יוֹם הַשַּׁבָּת, כְּמוֹ שֶׁנֶּאֱמַר זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. סוֹד שֶׁל שַׁבָּת, הֲרֵי בֵּאַרְנוּ בְּכָל אוֹתָם מְקוֹמוֹת, יוֹם זִכָּרוֹן שֶׁל מְנוּחָה שֶׁל הָעוֹלָם, וְהוּא כְּלָל שֶׁל הַתּוֹרָה. וּמִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר כָּל הַתּוֹרָה. וַהֲרֵי נִתְבָּאֵר, זִכָּרוֹן שֶׁל שַׁבָּת לְקַדֵּשׁ אוֹתָהּ בְּכָל מִינֵי קִדּוּשִׁים. מִי שֶׁמַּזְכִּיר אֶת הַמֶּלֶךְ, צָרִיךְ לְבָרֵךְ אוֹתוֹ. מִי שֶׁמַּזְכִּיר שַׁבָּת, צָרִיךְ לְבָרֵךְ אוֹתָהּ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>זָכוֹר הוּא לְזָכָר. שָׁמוֹר הוּא לִנְקֵבָה. (וזהבליפרוד) יוֹם שַׁבָּת הַסּוֹד שֶׁל כָּל הָאֱמוּנָה, שֶׁתְּלוּיָה מֵהָרֹאשׁ הָעֶלְיוֹן עַד סוֹף כָּל הַדְּרָגוֹת, שַׁבָּת הִיא הַכֹּל.</p>\n<p>שָׁלש דְּרָגוֹת הֵן, וְכֻלָּן נִקְרָאוֹת שַׁבָּת. שַׁבָּת עֶלְיוֹנָה. שַׁבַּת שֶׁל הַיּוֹם. שַׁבָּת שֶׁל הַלַּיְלָה. וְכֻלָּן אַחַת, וְהַכֹּל נִקְרָא שַׁבָּת. וְכָל אַחַת כְּשֶׁהִיא שׁוֹלֶטֶת, לוֹקַחַת אֶת חַבְרוֹתֶיהָ וּמַזְמִינָה אוֹתָן עִמָּהּ בְּאוֹתוֹ הַשִּׁלְטוֹן שֶׁלָּהּ. וּכְשֶׁזֶּה בָּא לָעוֹלָם, כֻּלָּם בָּאִים וּמְזֻמָּנִים עִמּוֹ.</p>\n<p>כְּשֶׁבָּא הַלַּיְלָה, מַזְמִין עִמּוֹ שַׁבָּת שֶׁל הַיּוֹם, וּמַזְמִין אוֹתוֹ לְהֵיכָלוֹ וּמִסְתַּתֵּר עִמּוֹ. כֵּיוָן שֶׁזֶּה בָּא, שַׁבָּת הָעֶלְיוֹנָה נִמְשֶׁכֶת עָלֶיהָ, וְכֻלָּם גְּנוּזִים בַּהֵיכָל שֶׁל הַלַּיְלָה, וּמִשּׁוּם כָּךְ סְעוּדַת הַלַּיְלָה חֲמוּרָה מִבַּיּוֹם (כמו של היום).</p>\n<p>כְּשֶׁבָּא הַיּוֹם, מַזְמִין עִמּוֹ אֶת שְׁתֵּי הָאֲחֵרוֹת הַלָּלוּ - דַּרְגָּה עֶלְיוֹנָה וְדַרְגָּה תַּחְתּוֹנָה, זוֹ שֶׁמְּאִירָה לָהּ וְזוֹ שֶׁנְּאוֹרָה מִמֶּנָּה, וְכֻלָּן כְּאַחַת נִקְרָאוֹת שַׁבָּת, וְשׁוֹלְטוֹת בְּיוֹם שַׁבָּת. וּשְׁלֹשׁ הַדְּרָגוֹת הַלָּלוּ הֵן כְּלָל וְסוֹד שֶׁל כָּל הַתּוֹרָה, תּוֹרָה שֶׁבִּכְתָב, נְבִיאִים וּכְתוּבִים. מִי שֶׁשּׁוֹמֵר שַׁבָּת, שׁוֹמֵר אֶת כָּל הַתּוֹרָה.</p>"],[9522011659,"<p>שְׁתֵּי מַרְגָּלִיּוֹת הֵן, וְיָתֵד אֶחָד עִמָּן בְּתוֹכָן שֶׁעוֹמֵד בֵּין זוֹ וּבֵין זוֹ. הַמַּרְגָּלִית הָעֶלְיוֹנָה אֵין בָּהּ גָּוֶן, וְאֵין בָּהּ מַרְאֶה בְּהִתְגַּלּוּת.</p>\n<p>הַמַּרְגָּלִית הַזּוֹ, כְּשֶׁמַּתְחִילָה לְהִתְגַּלּוֹת, מְאִירוֹת שֶׁבַע אוֹתִיּוֹת חֲקוּקוֹת בּוֹלְטוֹת וְנוֹצְצוֹת, וּבוֹקְעוֹת בְּקָעִים וְהֵיכָלוֹת וּמְאִירִים כָּל אֶחָד וְאֶחָד, וְאוֹתָן שֶׁבַע הָאוֹתִיּוֹת הֵן שְׁנֵי שֵׁמוֹת חֲקוּקִים בְּאוֹתָהּ הַמַּרְגָּלִית, וּבְיוֹם הַשַּׁבָּת נוֹצְצִים וּמְאִירִים, וּפוֹתְחִים פְּתָחִים וְיוֹצְאִים וְשׁוֹלְטִים. וְאוֹתָם אהי\"ה יה\"ו, מִתְנוֹצְצוֹת הָאוֹתִיּוֹת, וּבָאוֹתִיּוֹת שֶׁלָּהֶן נִכְנָסוֹת זוֹ בָּזוֹ וּמְאִירוֹת זוֹ בָּזוֹ.</p>\n<p>וּכְשֶׁנִּכְנָסוֹת זוֹ בָּזוֹ, הֵן מְאִירוֹת זוֹ מִתּוֹךְ זוֹ בִּשְׁנֵי גְוָנִים. גָּוֶן אֶחָד לָבָן וְגָוֶן אֶחָד אָדם. וּמֵאוֹתָם שְׁנֵי גְוָנִים נַעֲשִׂים שְׁנֵי שֵׁמוֹת אֲחֵרִים, עַד שֶׁעוֹלוֹת הָאוֹתִיּוֹת לְשִׁבְעָה שֵׁמוֹת.</p>\n<p>א' יּוצּא וְנוֹצֵץ, וְנִכְנַס בָּאוֹת ו', וּמְאִירִים שְׁנֵיהֶם בִּשְׁנֵי גְוָנִים. וְאוֹתָם שְׁנֵי שֵׁמוֹת, אֶחָד נִקְרָא יְהֹוָ\"ה, וְאֶחָד נִקְרָא אֵ\"ל, וּמְאִירִים כְּאֶחָד. ה' יוֹצֵאת וְנוֹצֶצֶת, וְנִכְנֶסֶת בָּאוֹת ה', וּמְאִירוֹת שְׁתֵּיהֶם בִּשְׁנֵי גְוָנִים, וְאוֹתָם שְׁנֵי שֵׁמוֹת, אֶחָד נִקְרָא יֶהֹוִה, סוֹד שֶׁל אֱלֹהִים, וְאֶחָד נִקְרָא אֱלֹהִים, וּמְאִירִים כְּאֶחָד. י' נִכְנֶסֶת בְּי', וּמְאִירוֹת וְנוֹצְצוֹת כְּאַחַת, וְנִכְנָסוֹת זוֹ בָּזוֹ וּמְאִירוֹת שְׁתֵּיהֶן, חֲקִיקוֹת חֲקוּקוֹת כְּאַחַת, וְהֵן זוֹקְפוֹת רֹאשׁ, מְאִירוֹת וְנוֹצְצוֹת, הָעֲנָפִים עוֹלִים מִן הַצַּד הַזֶּה וּמִן הַצַּד הַזֶּה, וְהֵם אַחַד עָשָׂר עֲנָפִים.</p>\n<p>וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ שֶׁמְּאִירוֹת, מִתְחַבְּקוֹת זוֹ בָּזוֹ, הֵן יְהֹוָ\"ה יְהֹוָ\"ה מצפץ מצפץ, בְּסוֹד שֶׁל שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים. וּשְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ, כְּשֶׁהֵן נִכְנָסוֹת זוֹ בָּזוֹ וּכְשֶׁמִּתְחַבְּקוֹת זוֹ בָּזוֹ, (וכשגדבקות זו בזו) זוֹקְפוֹת רֹאשָׁן וּמְאִירוֹת וְנוֹצְצוֹת עַל הַכֹּל בְּאוֹתָם אַחַד עָשָׂר הָעֲנָפִים שֶׁיּוֹצְאִים בְּכָל צַד.</p>\n<p>ה' שֶׁנִּשְׁאֲרָה, הִיא עוֹלָה בְּשֵׁם אֶחָד לְהִתְחַבֵּר עִמָּם, וְהִיא אֲדנָי. וְכָל הַשֵּׁמוֹת הַלָּלוּ בּוֹלְטִים וְנוֹצְצִים וְיוֹצְאִים וְשׁוֹלְטִים בַּיּוֹם הַזֶּה. כֵּיוָן שֶׁאֵלֶּה שׁוֹלְטִים, יוֹצֵאת אוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה בּוֹלֶטֶת נוֹצֶצֶת, וּמִתּוֹךְ הַהִתְנוֹצְצוּת שֶׁלָּהּ לֹא נִרְאֶה בָּהּ גָּוֶן.</p>\n<p>כְּשֶׁיּוֹצֵאת, מַכָּה בַּשֵּׁמוֹת הַלָּלוּ. שֵׁם אֶחָד מֵהֶם אֲדנָ\"י, שֶׁהוּא שְׁבִיעִי, מִתְעַטֵּר וְנִכְנָס לַמַּרְגָּלִית הַתַּחְתּוֹנָה, וּמִתְיַשֵּׁב שֵׁם אַחֵר תַּחְתָּיו, וְהוּא י\"ה. וּמֻקֶּפֶת בּוֹ אוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה, וּמִתְעַטֶּרֶת אוֹתָהּ הַהִתְנוֹצְצוּת שֶׁנּוֹצֶצֶת בַּשֵּׁם הַזֶּה.</p>\n<p>אַחַר שֶׁהִתְכַּנְּסָה בַּשֵּׁמוֹת הַלָּלוּ, יוֹצְאִים מֵהֶם שִׁבְעִים עֲנָפִים לְכָל צַד, וּמִתְחַבְּרִים כֻּלָּם כְּאֶחָד, וְנַעֲשֵׂית מֶרְכָּבָה וְכִסֵּא אֶחָד לְאוֹתָהּ הַמַּרְגָּלִית הָעֶלְיוֹנָה, וְשׁוֹלֶטֶת בְּעַטְרוֹתֶיהָ, מֶלֶךְ בְּכִסֵּא בַּיּוֹם הַזֶּה, וְהַכֹּל שְׂמֵחִים. כֵּיוָן שֶׁכֻּלָּם שְׂמֵחִים, יוֹשֵׁב הַמֶּלֶךְ עַל הַכִּסֵּא, וְעוֹלֶה בְּשִׁבְעִים עֲנָפִים הַכִּסֵּא, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>וְאוֹתָן שְׁתֵּי הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, וּמְאִירוֹת וּמִתְעַטְּרוֹת כ\"ב אוֹתִיּוֹת (בכ\"ב אותיות), כְּלָל שֶׁל הַתּוֹרָה, מַכּוֹת בִּשְׁתֵּי הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת וְעוֹלוֹת לְאֶחָד בְּשִׁשָּׁה שְׁבָטִים, וּלְאֶחָד בְּשִׁשָּׁה שְׁבָטִים אֲחֵרִים, וְאֵלֶּה הֵם שְׁנֵים עָשָׂר שִׁבְטֵי יִשְׂרָאֵל הָעֶלְיוֹן.</p>\n<p>עוֹד, שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ (ראשונותעולות) עוֹלוֹת וְיוֹרְדוֹת וּמַכּוֹת בִּשְׁתֵּי אוֹתִיּוֹת שֶׁל סוֹף כ\"ב הָאוֹתִיּוֹת. וְעוֹלוֹת אַחַת בְּחָמֵשׁ דְּרָגוֹת, וְאַחַת בְּחָמֵשׁ דְּרָגוֹת. וְעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ (לתקן) לִכְלֹל לְכ\"ב אוֹתִיּוֹת. י\"ב שְׁבָטִים בִּשְׁתֵּי אוֹתִיּוֹת (ראשונות), כְּלָל שֶׁל הַתּוֹרָה וְעֶשֶׂר אֲמִירוֹת שֶׁל שְׁתֵּי הָאוֹתִיּוֹת שֶׁבַּסּוֹף - הֲרֵי כ\"ב אוֹתִיּוֹת שֶׁל סוֹף הַתּוֹרָה. וְסוֹד זֶה יוֹרֶשֶׁת הַמַּרְגָּלִית הָעֶלְיוֹנָה בְּאוֹתוֹ כִּסֵּא שֶׁל ע\"ב, וּמְאִירוֹת כ\"ב אוֹתִיּוֹת.</p>\n<p>הַמַּרְגָּלִית הַתַּחְתּוֹנָה, בְּשָׁעָה שֶׁיּוֹשֶׁבֶת הַמַּרְגָּלִית הָעֶלְיוֹנָה בְּאוֹתוֹ הַכִּסֵּא שֶׁל ע\"ב וּמְאִירוֹת כ\"ב אוֹתִיּוֹת, אָז אוֹתָהּ הַמַּרְגָּלִית הַתַּחְתּוֹנָה שֶׁהִיא בַּחֲשֵׁכָה מִסְתַּכֶּלֶת בְּאוֹתוֹ הָאוֹר, בְּכֹחַ שֶׁל תֹּקֶף שֶׁל אוֹתָן הָאוֹתִיּוֹת שֶׁנִּרְשְׁמָה בָהֶן, שֶׁנִּקְרְאוּ אֲדנָי, וְאָז מֵאִיר וְעוֹלֶה אוֹתוֹ הָאוֹר, וְנוֹטֵל כָּל אוֹתָן כ\"ב אוֹתִיּוֹת עֶלְיוֹנוֹת, וְשׁוֹאֶבֶת אוֹתָן אוֹתָהּ הַמַּרְגָּלִית לְתוֹכָהּ, וּמֵאִיר אוֹר שֶׁנּוֹצֵץ לְע\"ב עֲבָרִים.</p>\n<p>כֵּיוָן שֶׁהַמַּרְגָּלִית הַזּוֹ נוֹצֶצֶת וְשׁוֹאֶבֶת אֶת אוֹתָן הָאוֹתִיּוֹת עִמָּהּ, אָז הַמַּרְגָּלִית הָעֶלְיוֹנָה נִמְשֶׁכֶת עִמָּם, וְנִדְבֶּקֶת מַרְגָּלִית בְּמַרְגָּלִית, וְנִהְיָה הַכֹּל אֶחָד. וְזֶהוּ סוֹד אֶחָד שֶׁל הַתִּשְׁבַּחַת, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>כְּשֶׁהָאוֹתִיּוֹת נוֹצְצוֹת מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה, זֶהוּ הַיָּתֵד שֶׁבֵּינֵיהֶם, בֵּין מַרְגָּלִית לְמַרְגָּלִית, אָז נַעֲשׂוֹת סוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁל מ\"ב אוֹתִיּוֹת. וּבְכָל הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁל ע\"ב אוֹתִיּוֹת שֶׁל הַמֶּרְכָּבָה הָעֶלְיוֹנָה, וְהַכֹּל - זֶה וָזֶה - נִקְרֵאת שַׁבָּת, וְזֶהוּ סוֹד הַשַּׁבָּת. (ע\"כ רעיא מהימנא)</p>\n<p>זָכוֹר - הוּא סוֹד שֶׁל זָכָר, סוֹד שֶׁל הַזָּכָר שֶׁלּוֹקֵחַ אֶת כָּל אֵיבְרֵי הָעוֹלָם הָעֶלְיוֹן. אֶת יוֹם הַשַּׁבָּת - לְרַבּוֹת עֶרֶב שַׁבָּת, שֶׁהוּא לַיְלָה. וְזֶהוּ אֶת. לְקַדְּשׁוֹ - שֶׁצָּרִיךְ קְדֻשָּׁה מִתּוֹךְ הָעָם הַקָּדוֹשׁ, וּלְהִתְעַטֵּר בָּהֶם כָּרָאוּי.</p>\n<p>זָכוֹר - מָקוֹם שֶׁאֵין בּוֹ שִׁכְחָה וְלֹא עוֹמֶדֶת בּוֹ שִׁכְחָה, שֶׁהֲרֵי אֵין שִׁכְחָה בַּמָּקוֹם שֶׁל הַבְּרִית הָעֶלְיוֹן, וְכָל שֶׁכֵּן לְמַעְלָה. וּלְמַטָּה יֵשׁ שִׁכְחָה, מָקוֹם שֶׁצָּרִיךְ לְהַזְכִּיר, וְעַל זֶה כָּתוּב (תהלים קט) יִזָּכֵר עֲוֹן אֲבתָיו וְגוֹ'. וְיֵשׁ שָׁם מְמֻנִּים שֶׁמַּזִכִּירִים זְכֻיּוֹת הָאָדָם וַחֲטָאָיו.</p>\n<p>וְאֵיןֹ שִׁכְחָה לִפְנֵי הַכִּסֵּא הַקָּדוֹשׁ מַה שֶּׁהוּא לְפָנָיו. וּמַה הוּא לְפָנָיו? זָכוֹר. וְכָל שֶׁכֵּן לְמַעְלָה. מִשּׁוּם שֶׁהַכֹּל הוּא סוֹד שֶׁל זָכָר, וְשָׁם נֶחְקָק סוֹד הַשֵּׁם הַקָּדוֹשׁ יה\"ו. וּלְמַטָּה צָרִיךְ לְהִתְקַדֵּשׁ. וּבַמָּה הִתְקַדֵּשׁ? בְּזָכוֹר, שֶׁהֲרֵי מִמֶּנּוּ נוֹטֵל כָּל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת. וְזֶה כְּשֶׁמִּתְעַטְּרִים עֶרֶב שַׁבָּת עַל הָעָם הַקָּדוֹשׁ כָּרָאוּי בִּתְפִלּוֹת וּבְבַקָּשׁוֹת וּבְסִדּוּר שֶׁל שִׂמְחָה.</p>\n<p>וְאִם תֹּאמַר, זָכוֹר לֹא צָרִיךְ לְהִתְקַדֵּשׁ, שֶׁהֲרֵי מִמֶּנּוּ יוֹצְאִים שֶׁל הַקְּדֻשּׁוֹת שֶׁל הָעוֹלָם - לֹא כָּךְ! שֶׁהֲרֵי זֶה צָרִיךְ לְהִתְקַדֵּשׁ בַּיּוֹם, וְזֶה צָרִיךְ לְהִתְקַדֵּשׁ בַּלַּיְלָה, וְכָל הַקִּדּוּשִׁים נוֹטְלִים אוֹתָם יִשְׂרָאֵל אַחַר כָּךְ, וּמִתְקַדְּשִׁים בַּקְּדֻשּׁוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011660,"<p>כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, בְּכָל מִינֵי כָבוֹד, לְשַׂמְּחָם בְּמַעֲשִׂים כְּשֵׁרִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי כג) גִּיל יָגִיל אֲבִי צַדִּיק. וְזֶהוּ כְּבוֹד אָבִיו וְאִמּוֹ.</p>\n<p>כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. כַּבְּדֵהוּ בִּכְסוּת נְקִיָּה, דְּהַיְנוּ כַּנְפֵי מִצְוָה, כַּבֵּד אֶת ה' מֵהוֹנֶךְ, זוֹ תוֹרָה וּמִצְווֹת. זֶהוּ שֶׁכָּתוּב אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ וְגוֹ'. שֶׁאֵין אָדָם עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְווֹת. נוֹדָע, אַחַר שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, אֵין עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְווֹת, שֶׁעָשְׁרוֹ שֶׁל אָדָם תּוֹרָה וּמִצְווֹת. וּמִשּׁוּם כָּךְ כַּבֵּד אֶת אָבִיךְ מֵהוֹנֶךְ,</p>\n<p>וּבְגִין דָּא, פַבֵּד אֶת יְיָ' מֵהוֹנֶךָ, וְלָא תִשְׁתַּדֵּל בְּאוֹדַיְיתָא, פְדֵי לְהִתְגַּדֵּל בָּהּ. פְמָה דְאוּקְמוּהָ וְאַל תִּשְׁתַּדֵּל בַּתּוֹרָה כְּדֵי לְהִתְגַּדֵּל בָּהּ, כְּמוֹ שֶׁבֵּאֲרוּהָ הַחֲבֵרִים, וְאַל תַּעֲשֵׂם עֲטָרָה לְהִתְגַּדֵּל בָּהֶם, וְלֹא תֹאמַר אֶקְרָא בַּעֲבוּר שֶׁיִּקְרְאוּנִי רַבִּי, אֶלָּא (תהליםלד) גַּדְּלוּ לַה' אִתִּי. כַּבֵּד אֶת ה' מֵהוֹנֶךְ, כְּבֵן שֶׁחַיָּב בִּכְבוֹד אָבִיו וְאִמּוֹ.</p>\n<p>מִשּׁוּם שֶׁהוּא מְשֻׁתָּף מִשְּׁתֵּי טִפּוֹת שֶׁמֵּהֶן נוֹצָר הָאָדָם. מֵהַטִּפָּה שֶׁל אָבִיו לֹבֶן הָעֵינַיִם, וַעֲצָמוֹת וְאֵיבָרִים. וּמִטִּפָּה שֶׁל אִמּוֹ הַשָּׁחֹר שֶׁבָּעַיִן, וְשֵׂעָר וְעוֹר וּבָשָׂר. וּמְגַדְּלִים אוֹתוֹ בַּתּוֹרָה וּמַעֲשִׂים טוֹבִים.</p>\n<p>שֶׁאָדָם חַיָּב לְלַמֵּד בְּנוֹ תּוֹרָה, שֶׁכָּתוּב (דברים ו) וְשִׁנַּנְתָּם לְבָנֶיךְ. וְאִם לֹא לִמֵּד אוֹתוֹ תּוֹרָה וּמִצְווֹת, כְּאִלּוּ עָשָׂה לוֹ פֶּסֶל, וּמִשּׁוּם כָּךְ לֹא תַעֲשֶׂה לְךְ פֶסֶל. וְעָתִיד לִהְיוֹת בֵּן סוֹרֵר וּמוֹרֶה וּמְבַזֶּה אָבִיו וְאִמּוֹ וְגוֹזֵל מִמֶּנּוּ כַּמָּה בְרָכוֹת. שֶׁהוֹאִיל וְהוּא עַם הָאָרֶץ, הוּא חָשׁוּד עַל הַכֹּל, וַאֲפִלּוּ עַל שְׁפִיכוּת דָּמִים וְגִלּוּי עֲרָיוֹת וַעֲבוֹדָה זָרָה. שֶׁמִּי שֶׁהוּא עַם הָאָרֶץ וְהוֹלֵךְ לְמָקוֹם שֶׁאֵין מַכִּירִים אוֹתוֹ וְלֹא יוֹדֵעַ לְבָרֵךְ, חוֹשְׁדִים אוֹתוֹ שֶׁהוּא עוֹבֵד עֲבוֹדָה זָרָה. (ע\"כ רעיא מהימנא)</p>\n<p>כַּבֵּד אֶת אָבִיךְ, כְּמוֹ שֶׁנֶּאֱמַר כַּבֵּד אֶת ה' מֵהוֹנֶךְ. מֵהוֹנֶךְ - מִמָּמוֹנְךְ. מֵהוֹנֶךְ - מֵחִנְּךְ. בְּשִׂמְחַת הַנִּגּוּן לְשַׂמֵּחַ הַלֵּב, שֶׁהֲרֵי זוֹ שִׂמְחַת הַלֵּב, כְּמוֹ זֶה הַנִּגּוּן שֶׁל כָּל הָעוֹלָם. מַעֲשִׂים כְּשֵׁרִים שֶׁל אוֹתוֹ בֵּן מְשַׂמֵּחַ לֵב אָבִיו וְאִמּוֹ. מֵהוֹנֶךְ - מִמָּמוֹנְךְ לְכָל מַה שֶּׁצְּרִיכִים.</p>\n<p>כְּמוֹ שֶׁהָאָדָם מְכַבֵּד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּךְ צָרִיךְ לְכַבֵּד אָב וָאֵם, מִשּׁוּם שֶׁיֵּשׁ לָהֶם שֻׁתָּפוּת אַחַת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו. וּכְמוֹ שֶׁצָּרִיךְ לִפְחֹד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, כָּךְ צָרִיךְ לִירָא מֵאָבִיו וְאִמּוֹ וּלְכַבְּדָם כְּאֶחָד בְּכָל מִינֵי כָבוֹד.</p>\n<p>לְמַעַן יַאֲרִיכוּן יָמֶיךְ, מִשּׁוּם שֶׁיֵּשׁ יָמִים לְמַעְלָה שֶׁתְּלוּיִים בָּהֶם חַיֵּי הָאָדָם בָּעוֹלָם הַזֶּה. וּבֵאַרְנוּ עַל אוֹתָם יָמִים שֶׁל אָדָם לְמַעְלָה בְּאוֹתוֹ הָעוֹלָם, וְכֻלָּם עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָהֶם נוֹדָעִים חַיֵּי הָאָדָם.</p>\n<p>עַל הָאֲדָמָה אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לָךְ. הַבְטָחָה לֵהָנוֹת בְּאַסְפַּקְלַרְיָה הַמְּאִירָה, וְסוֹד זֶה עַל הָאֲדָמָה, זוֹ אַסְפַּקְלַרְיָה הַמְּאִירָה, בְּאוֹתָם הַיָּמִים הָעֶלְיוֹנִים שֶׁמְּאִירִים מִתּוֹךְ הַמַּעְיָן שֶׁל הַכֹּל.</p>\n<p>מַה שּׁוֹנֶה בִּשְׁתֵּי הַמִּצְווֹת הַלָּלוּ שֶׁל הַתּוֹרָה שֶׁכָּתוּב בָּהֶן לְמַעַן יַאֲרִיכוּן יָמֶיךְ, בָּזֶה וּבְשִׁלּוּחַ הַקֵּן? אֶלָּא שְׁתֵּי מִצְווֹת אֵלֶּה כֻּלָּן תְּלוּיוֹת לְמַעְלָה. אָב וָאֵם, סוֹד שֶׁל זָכוֹר וְשָׁמוֹר כְּאֶחָד, וּמִשּׁוּם כָּךְ כָּתוּב לְמַעַן יַאֲרִיכוּן יָמֶיךְ. וּבְשִׁלּוּחַ הַקֵּן, שֶׁכָּתוּב (שם כב) שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם וְאֶת הַבָּנִים תִּקַּח לָךְ לְמַעַן יִיטַב לָךְ וְגוֹ'. הַסּוֹד שֶׁל עוֹלָם הָעֶלְיוֹן שֶׁלֹּא נִתְּנָה רְשׁוּת לְהִסְתַּכֵּל בּוֹ, וְצָרִיךְ לְשַׁלֵּחַ מִתּוֹךְ שְׁאֵלָה וְהִתְבּוֹנְנוּת בּוֹ.</p>\n<p>וְאֶת הַבָּנִים תִּקַּח לָךְ, שֶׁכָּתוּב (שם ד) כי שאל נא לימים ראשנים וגו' (ול) מקצה השמים ועד קצה השמים. אבל למעלה מקצה השמים, שלח תשלח מרעיוניך לשאל.</p>\n<p>וּבָזְהִ כָּתוּב לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים. לֹא כָתוּב לְמַעַן אֵיטִיב לָךְ, אֶלָּא לְמַעַן יִיטַב לָךְ. וְלֹא כָתוּב יַאֲרִיכוּן יָמֶיךְ, אֶלָּא וְהַאֲרַכְתָּ יָמִים. לְמַעַן יִיטַב לָךְ - אוֹתוֹ הַמָּקוֹם שֶׁמֵּיטִיב לָכֹּל, וְהוּא הָעוֹלָם הַגָּנוּז וְהַנִּסְתָּר. וְהַאֲרַכְתָּ יָמִים - כְּמוֹ שֶׁכָּתוּב תִּקַּח לָךְ, זֶהוּ בִּרְשׁוּתוֹ שֶׁל הָאָדָם.</p>\n<p>וְאִם יִזְדַּמֵּן לוֹ מַעֲשֶׂה וִיכַוֵּן בּוֹ, צַדִּיק הוּא. וְאַף עַל גַּב שֶׁלֹּא מְכַוֵּן בּוֹ, צַדִּיק הוּא, שֶׁעוֹשֶׂה מִצְוַת אֲדוֹנוֹ. אֲבָל לֹא נֶחְשָׁב כְּמִי שֶׁעָשָׂה רְצוֹנוֹ לִשְׁמָהּ, וִיכַוֵּן בּוֹ בְּרָצוֹן שֶׁל הִסְתַּכְּלוּת בִּכְבוֹד רִבּוֹנוֹ, כְּמִי שֶׁלֹּא יוֹדֵעַ לִסְבֹּר סְבָרָא, שֶׁהֲרֵי בְּרָצוֹן תָּלוּי הַדָּבָר לִשְׁמוֹ. וּבְמַעֲשֶׂה שֶׁלְּמַטָּה לִשְׁמוֹ, מִתְעַלֶּה הַמַּעֲשֶׂה לְמַעְלָה וּמִתְתַּקֵּן כָּרָאוּי.</p>\n<p>כְּמוֹ זֶה בְּמַעֲשֶׂה שֶׁל הַגּוּף נִתְקָן מַעֲשֵׂה הַנֶּפֶשׁ בְּאוֹתוֹ הָרָצוֹן, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה אֶת הַלֵּב וְהָרָצוֹן שֶׁל הָאָדָם, וַאֲפִלּוּ כָּךְ, אִם אֵין שָׁם רָצוֹן שֶׁל הַלֵּב, שֶׁהוּא עִקַּר הַכֹּל, עַל זֶה הִתְפַּלֵּל דָּוִד וְאָמַר, (תהליםצא) וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ וְגוֹ'. שֶׁהֲרֵי אֵין כָּל אָדָם חָכָם לָשִׂים רָצוֹן וְלֵב לְתַקֵּן הַכֹּל וְיַעֲשֶׂה מַעֲשֶׂה שֶׁל מִצְוָה. עַל זֶה הִתְפַּלֵּל תְּפִלָּה זוֹ - וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנָה עָלֵינוּ.</p>\n<p>מַה זֶּה כּוֹנְנָה עָלֵינוּ? כּוֹנְנָה וְהַתְקֵן תִּקּוּנְךְ לְמַעְלָה כָּרָאוּי. עָלֵינוּ, אַף עַל גַּב שֶׁאֵינֶנּוּ יוֹדְעִים לָשִׂים הָרָצוֹן, אֶלָּא הַמַּעֲשֶׂה לְבַדּוֹ. מַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ, לְמִי? לְאוֹתָהּ דַּרְגָּה שֶׁצָּרִיךְ לְהִתַּקֵּן. כּוֹנְנֵהוּ, אֶת מִי? בְּחִבּוּר אֶחָד בָּאָבוֹת, לִהְיוֹת מְתֻקָּן בָּהֶם בַּמַּעֲשֶׂה הַזֶּה כָּרָאוּי.</p>"],[9522011661,"<p>לֹא תִרְצַח. לֹא תִנְאָף. לֹא תִגְנֹב. לֹא - יֵשׁ טַעַם מַפְסִיק בְּכָל שְׁלֹשֶׁת אֵלֶּה. וְאִם לֹא הָיָה טַעַם מַפְסִיק, לֹא הָיָה תִקּוּן לָעוֹלָמוֹת, וְיִהְיֶה אָסוּר לָנוּ לַהֲרֹג נֶפֶשׁ בָּעוֹלָם, אַף עַל גַּב שֶׁיַּעֲבֹר עַל הַתּוֹרָה. אֲבָל בְּמַה שֶּׁיֵּשׁ הֶפְסֵק טַעַם - אָסוּר וּמֻתָּר.</p>\n<p>לֹא תִנְאָף - אִם לֹא טַעַם מַפְסִיק, אָסוּר אֲפִלּוּ לְהוֹלִיד אוֹ לִשְׂמֹחַ בְּאִשְׁתּוֹ שִׂמְחַת מִצְוָה, וּבְמַה שֶּׁהַטַּעַם מַפְסִיק - אָסוּר וּמֻתָּר. לֹא תִגְנֹב - אִם לֹא הָיָה טַעַם מַפְסִיק, הָיָה אָסוּר אֲפִלּוּ לִגְנֹב דַּעַת שֶׁל רַבּוֹ בַּתּוֹרָה אוֹ דַעַת שֶׁל חָכָם כְּדֵי לְהִתְבּוֹנֵן בָּהּ, אוֹ דַיָּן שֶׁדָּן דִּין לְפִי טַעֲנָה שֶׁצָּרִיךְ לִגְנֹב אֶת דַּעַת הָרַמַּאי, וְלִגְנֹב אֶת דַּעַת שְׁנֵיהֶם כְּדֵי לְהוֹצִיא אֶת הַדִּין לָאוֹר. וּבְמַה שֶּׁמַּפְסִיק הַטַּעַם - אָסוּר וּמֻתָּר.</p>\n<p>לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. כָּאן לֹא מַפְסִיק טַעַם, מִשּׁוּם שֶׁזֶּה אָסוּר כְּלָל וּכְלָל, וּבְכָל דִּבְרֵי הַתּוֹרָה שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא סוֹדוֹת עֶלְיוֹנִים, וְלִמֵּד בְּנֵי אָדָם דֶּרֶךְ לְהִתְתַּקֵּן בָּהּ וְלָלֶכֶת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מח) אֲנִי ה' אֱלֹהֶיךְ מְלַמֶּדְךְ לְהוֹעִיל מַדְרִיכְךְ בְּדֶרֶךְ תֵּלֵךְ.</p>\n<p>אַף כָּאן לֹא תַחְמֹד, לֹא מַפְסִיק טַעַם כְּלָל. וְאִם תֹּאמַר, אֲפִלּוּ חִמּוּד שֶׁל הַתּוֹרָה אָסוּר, כֵּיוָן שֶׁלֹּא מַפְסִיק הַטַּעַם? בֹּא וּרְאֵה, בְּכֻלָּם עָשְׂתָה הַתּוֹרָה כְּלָל, וּבָזֶה עָשְׂתָה פְּרָט. בֵּית רֵעֶךְ שָׂדֵהוּ וְעַבְדּוֹ וְגוֹ', בְּכָל דִּבְרֵי הָעוֹלָם. אֲבָל הַתּוֹרָה הִיא תָּמִיד חוֹמְדִים אוֹתָהּ, שַׁעֲשׁוּעִים, גִּנְזֵי חַיִּים, אֹרֶךְ הַיָּמִים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>עָשֶׂר הָאֲמִירוֹת הַלָּלוּ שֶׁל הַתּוֹרָה הֵן כְּלָל שֶׁל כָּל מִצְווֹת הַתּוֹרָה, כְּלָל שֶׁל מַעְלָה וְשֶׁל מַטָּה, כְּלָל שֶׁל כָּל עֶשֶׂר הָאֲמִירוֹת שֶׁל בְּרֵאשִׁית. אֵלֶּה נֶחְקְקוּ עַל לוּחוֹת אֲבָנִים, וְכָל הַגְּנָזִים שֶׁהָיוּ בָהֶם נִרְאוּ לְעֵינֵי כֹל, לָדַעַת וּלְהִסְתַּכֵּל בַּסּוֹד שֶׁל תַּרְיַ\"ג הַמִּצְווֹת שֶׁל הַתּוֹרָה שֶׁכְּלוּלִים בָּהֶם, הַכֹּל נִרְאֶה לָעֵינַיִם, הַכֹּל הוּא בִּתְבוּנָה, לְהִתְבּוֹנֵן בַּלֵּב שֶׁל כָּל יִשְׂרָאֵל, וְהַכֹּל הָיָה מֵאִיר לְעֵינֵיהֶם.</p>\n<p>בְּאוֹתָהּ שָׁעָה כָּל סוֹדוֹת הַתּוֹרָה וְכָל הַסּוֹדוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים לֹא זָזוּ מֵהֶם, מִשּׁוּם שֶׁהָיוּ רוֹאִים עַיִן בְּעַיִן אֶת זִיו כְּבוֹד רִבּוֹנָם - מַה שֶּׁלֹּא הָיָה כְּמוֹ אוֹתוֹ הַיּוֹם מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה בִּכְבוֹדוֹ עַל הַר סִינַי.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, יָכוֹל כְּמוֹ אוֹתוֹ יוֹם שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי? לֹא כָּךְ! מִשּׁוּם שֶׁאוֹתוֹ הַיּוֹם שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, עָבְרָה מֵהֶם הַזֻּהֲמָה, וְכָל הַגּוּפִים הָיוּ מְצֻחְצָחִים כְּצִחְצוּחַ שֶׁל מַלְאָכִים עֶלְיוֹנִים כְּשֶׁמִּתְלַבְּשִׁים בִּלְבוּשִׁים מְצֻחְצָחִים לַעֲשׂוֹת אֶת שְׁלִיחוּת רִבּוֹנָם.</p>\n<p>וּבְאוֹתוֹ מַלְבּוּשׁ מְצֻחְצָח נִכְנָסִים לָאֵשׁ וְלֹא פוֹחֲדִים. כְּמוֹ אוֹתוֹ הַמַּלְאָךְ שֶׁל מָנוֹחַ, כְּשֶׁנִּרְאָה לוֹ וְנִכְנַס בְּשַׁלְהֶבֶת וְעָלָה לַשָּׁמַיִם, שֶׁכָּתוּב (שופטים יג) וַיַּעַל מַלְאַךְ ה' בְּלַהַב הַמִּזְבֵּחַ. וּכְשֶׁעָבְרָה מֵהֶם אוֹתָהּ זֻהֲמָה, נִשְׁאֲרוּ יִשְׂרָאֵל גּוּפִים מְצֻחְצָחִים בְּלִי טִנּוּף כְּלָל, וְהַנְּשָׁמוֹת בִּפְנִים כְּזהַר הָרָקִיעַ לְקַבֵּל אֶת הָאוֹר.</p>\n<p>כָּךָ הָיוּ יִשְׂרָאֵל, שֶׁהָיוּ רוֹאִים וּמִסְתַּכְּלִים לְתוֹךְ כְּבוֹד רִבּוֹנָם, מַה שֶּׁלֹּא הָיָה כָּךְ עַל הַיָּם, שֶׁלֹּא עָבְרָה מֵהֶם הַזֻּהֲמָה בְּאוֹתוֹ זְמַן. וְכָאן בְּסִינַי, שֶׁפָּסְקָה הַזֻּהֲמָה מִן הַגּוּף, אֲפִלּוּ עֻבָּרִים בִּמְעֵי אִמּוֹתֵיהֶם הָיוּ רוֹאִים וּמִסְתַּכְּלִים בִּכְבוֹד רִבּוֹנָם, וְכֻלָּם קִבְּלוּ כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>וְאוֹתוֹ יוֹם הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מִן הַיּוֹם שֶׁנִּבְרָא הָעוֹלָם, מִשּׁוּם שֶׁהַיּוֹם שֶׁנִּבְרָא הָעוֹלָם לֹא הָיָה בְּקִיּוּם עַד שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה, שֶׁכָּתוּב (ירמיהלג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>\n<p>כֵּיוָן שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה עַל הַר סִינַי, אָז הִתְבַּשֵּׂם הָעוֹלָם, וְהִתְקַיְּמוּ שָׁמַיִם וָאָרֶץ, וְנוֹדַע הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה, וְהִתְעַלָּה בִּכְבוֹדוֹ עַל הַכֹּל. וְעַל אוֹתוֹ יוֹם כָּתוּב, (תהלים צג) ה' מָלָךְ גֵּאוּת לָבֵשׁ לָבֵשׁ ה' עֹז הִתְאַזָּר. וְאֵין עֹז אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (שם כט) ה' עֹז לְעַמּוֹ יִתֵּן ה' יְבָרֵךְ אֶת עַמּוֹ בַשָּׁלוֹם. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011662,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, וְאֵלֶּה הַמִּשְׁפָּטִים אֲשֶׁר תָּשִׂים לִפְנֵיהֶם. תַּרְגּוּם: וְאִלֵּין דִּינַיָּא דִּי תַסְדַּר קֳדָמֵיהוֹן. אֵלֶּה אוֹתָם סִדּוּרִים שֶׁל הַגִּלְגּוּל, דִּינֵי הַנְּשָׁמוֹת שֶׁנִּדּוֹנוּ כָּל אֶחָד וְאֶחָד לְקַבֵּל עָנְשׁוֹ. כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. חֲבֵרִים, הַזְּמַן כָּעֵת לְגַלּוֹת כַּמָּה סוֹדוֹת נִסְתָּרִים שֶׁל הַגִּלְגּוּל.</p>"],[9522011663,"<p>כִּי תִקְנֶה עֶבֶד עִבְרִי שֵׁשׁ שָׁנִים יַעֲבֹד, כְּשֶׁהַנְּשָׁמָה הִתְחַיְּבָה בְּגִלְגּוּל, אִם הִיא מִצַּד אוֹתוֹ הָעֶבֶד מטטרו\"ן, שֶׁהוּא כּוֹלֵל שִׁשָּׁה צְדָדִים, כָּתוּב בּוֹ שֵׁשׁ שָׁנִים יַעֲבֹד. גִּלְגּוּלִים שֶׁלָּהּ לֹא מִתְחַיֶּבֶת אֶלָּא שֵׁשׁ שָׁנִים, עַד שֶׁמַּשְׁלִימָה שֵׁשׁ דְּרָגוֹת מֵאוֹתוֹ הַמָּקוֹם שֶׁנִּלְקְחָה.</p>\n<p>אֲבָל אִם הַנְּשָׁמָה הִיא מִצַּד הַשְּׁכִינָה שֶׁהִיא שְׁבִיעִית, וַדַּאי מַה כָּתוּב? וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם. שֶׁצַּדִּיק וַדַּאי אֵין בּוֹ מְלָאכָה, וְכֵיוָן שֶׁאֵין בּוֹ מְלָאכָה, אֵין בּוֹ שִׁעְבּוּד. וְהַנְּשָׁמָה שֶׁהִיא מִשָּׁם, נֶאֱמַר בָּהּ וּבַשְּׁבִיעִית יֵצֵא לַחָפְשִׁי חִנָּם, אֵין בָּהּ שִׁעְבּוּד.</p>\n<p>בֵּין כָּךְ יָרַד הַזָּקֵן אֵלָיו, אָמַר לוֹ, אִם כָּךְ רַבִּי, מַה תּוֹסֶפֶת לַנְּשָׁמָה שֶׁהִיא מִמֶּנָּה, שֶׁנֶּאֱמַר בָּהּ (שמות כ) לֹא תַעֲשֶׂה כָל מְלָאכָה אַתָּה וּבִנְךְ וּבִתֶּךְ עַבְדְּךְ וְגוֹ'?</p>\n<p>אָמַר לוֹ, זָקֵן זָקֵן, וְאַתָּה שׁוֹאֵל אֶת זֶה? שֶׁוַּדַּאי זֶה נֶאֱמַר עַל נִשְׁמַת הַצַּדִּיק, שֶׁאַף עַל גַּב שֶׁהִתְחַיֵּב לָרֶדֶת בְּגִלְגּוּל בְּכָל אֵלֶּה, אֲפִלּוּ בְּעֶבֶד וְאָמָה, וּבְהֵמוֹת שֶׁהֵם אוֹפַנִּים, אוֹ בְכָל הַחַיּוֹת שֶׁמֵּהֶם נִשְׁמוֹת בְּנֵי אָדָם, כָּתוּב בָּהּ לֹא תַעֲשֶׂה כָל מְלָאכָה, וְזֶהוּ (ויקרא כה) לא תעבד בו עבדת עבד. בצדיק, שהוא יום השבת, לא תעבד בו עבדת עבד, שהוא יום של חל.</p>\n<p>אֲבָל זָקֵן זָקֵן, שַׁבָּת (הגשמה) שֶׁהִיא בַּת יְחִידָה, וְהִיא בַּת זוּגוֹ שֶׁל צַדִּיק שֶׁהוּא שַׁבָּת. מַה זֶּה אִם אַחֶרֶת יִקַּח לוֹ? אָמַר לוֹ, הֲרֵי וַדַּאי הַבְדָּלָה חֻלּוֹ שֶׁל שַׁבָּת, שֶׁיֵּשׁ אַחֵר שֶׁלֹּא נִקְרָא חֻלּוֹ שֶׁל שַׁבָּת, אֶלָּא חֻלּוֹ שֶׁל טֻמְאָה שִׁפְחָה. אָמַר לוֹ, וַהֲרֵי חֻלּוֹ שֶׁל שַׁבָּת מַה זֶּה? אָמַר לוֹ, זוֹ אָמָה, שֶׁהִיא גּוּף שֶׁל בַּת יְחִידָה, שֶׁעָלֶיהָ נֶאֱמַר אִם אַחֶרֶת יִקַּח לוֹ.</p>\n<p>בֹּא וּרְאֵה, נְשָׁמָה יֵשׁ שֶׁנִּקְרֵאת אָמָה, וְיֵשׁ (נשמה) שְׁכִינָה שֶׁנִּקְרֵאת שִׁפְחָה, (ונשמה) וּשְׁכִינָה יֵשׁ שֶׁנִּקְרֵאת בַּת הַמֶּלֶךְ. כָּאן יֵשׁ אִישׁ שֶׁנֶּאֱמַר בּוֹ (שמות טו) ה' אִישׁ מִלְחָמָה. וְיֵשׁ אִישׁ שֶׁנֶּאֱמַר בּוֹ (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל.</p>\n<p>וְלָכֵן, נְשָׁמָה שֶׁמְּחֻיֶּבֶת בְּגִלְגּוּל, אִם הִיא בִּתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם תֹּאמַר שֶׁתִּמָּכֵר לְגוּף נָכְרִי שֶׁשָּׁם שִׁלְטוֹן יֵצֶר הָרָע שֶׁהוּא מִצַּד סָמָאֵ\"ל - חַס וְשָׁלוֹם, שֶׁהֲרֵי כָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן, שֶׁהוּא יֵצֶר הָרָע.</p>\n<p>וְאוֹתוֹ הַגּוּף שֶׁשָּׁם שׁוֹרָה בַּת הַמֶּלֶךְ, אִם תֹּאמַר שֶׁנִּמְכָּר בִּכְתָרִים תַּחְתּוֹנִים שֶׁנִּטְמְאוּ - חָלִילָה וְחַס. עָלָיו נֶאֱמַר (ויקרא כה) וְהָאָרֶץ לֹא תִמָּכֵר לִצְמִתֻת כִּי לִי הָאָרֶץ. מִי גוּף שֶׁל בַּת הַמֶּלֶךְ? זֶה מטטרו\"ן, וְגוּף זֶה הוּא אָמָה שֶׁל הַשְּׁכִינָה, אַף עַל גַּב שֶׁהִיא נְשָׁמָה שֶׁהִיא בַּת הַמֶּלֶךְ, שְׁבוּיָה שָׁם, בְּגִלְגּוּל בָּאָה, שֶׁבָּאִים גִּלְגּוּלִים מִשּׁוּם שֶׁבָּאָה שָׁם. מַה כָּתוּב בָּהּ? וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה לֹא תֵצֵא כְּצֵאת הָעֲבָדִים.</p>\n<p>וְעוֹד, וְכִי יִמְכֹּר אִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֶת בִּתּוֹ - אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם מִצַּד שֶׁל בַּת יְחִידָה נִקְרְאוּ בִּתּוֹ. וְאִם תֹּאמַר שֶׁיֵּצְאוּ, כְּמוֹ שֶׁאֵלֶּה מִצַּד שֶׁל הָעֶבֶד שֶׁהוּא מטטרו\"ן, שֶׁיָּצְאוּ בִּמְנוּסָה מִמִּצְרַיִם, לֹא תֵצֵא כְּצֵאת הָעֲבָדִים. זֶהוּ שֶׁכָּתוּב (ישעיה נב) כִּי לֹא בְחִפָּזוֹן תֵּצֵאוּ וּבִמְנוּסָה לֹא תֵלֵכוּן.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁנּוֹלָד אִישׁ, נוֹתְנִים לוֹ נֶפֶשׁ מִצַּד הַבְּהֵמָה מִצַּד שֶׁל טֹהַר, מִצַּד אֵלֶּה שֶׁנִּקְרָאִים אוֹפַנֵּי הַקֹּדֶשׁ. זָכָה יוֹתֵר - נוֹתְנִים לוּ רוּחַ מִצַּד שֶׁל חַיּוֹת הַקֹּדֶשׁ. זָכָה יוֹתֵר - נוֹתְנִים לוֹ נְשָׁמָה מִצַּד שֶׁל הַכִּסֵּא. וּשְׁלֹשֶׁת אֵלּוּ הֵם אָמָה, עֶבֶד וְשִׁפְחָה שֶׁל בַּת הַמֶּלֶךְ.</p>\n<p>אִם זָכָה יוֹתֵר - נוֹתְנִים לוֹ נֶפֶשׁ בְּדֶרֶךְ אֲצִילוּת, מִצַּד שֶׁל בַּת יְחִידָה, וְנִקְרֵאת בַּת מֶלֶךְ. זָכָה יוֹתֵר - נוֹתְנִים לוֹ רוּחַ שֶׁל אֲצִילוּת מִצַּד הָעַמּוּד הָאֶמְצָעִי, וְנִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. זָכָה יוֹתֵר - נוֹתְנִים לוֹ נְשָׁמָה מִצַּד שֶׁל אַבָּא וְאִמָּא. זֶהוּ שֶׁכָּתוּב (בראשיתב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. אֵיזֶה חַיִּים? אֶלָּא אוֹתָם י\"ה שֶׁעֲלֵיהֶם נֶאֱמַר (תהלים קנ) כָּל הַנְּשָׁמָה תְּהַלֵּל יָהּ, וְנִשְׁלְמָה בָּהּ יהו\"ה.</p>\n<p>זָכָה יוֹתֵר - נוֹתְנִים לוֹ יהו\"ה בִּשְׁלֵמוּת הָאוֹתִיּוֹת - יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, שֶׁהוּא אָדָם, בְּאֹרַח אֲצִילוּת לְמַעְלָה. וְנִקְרָא בִּדְמוּת רִבּוֹנוֹ. וְעָלָיו נֶאֱמַר (בראשית א) וּרְדוּ בִּדְגַת הַיָּם וְגוֹ'. וְזֶהוּ שִׁלְטוֹנוֹ בְּכָל הָרְקִיעִים וּבְכָל הָאוֹפַנִּים וְהַשְּׂרָפִים וְהַחַיוֹת וּבְכָל הַחֲיָלוֹת וְהַכֹּחוֹת שֶׁלְּמַעְלָה וּלְמַטָּה. וְלָכֵן, כְּשֶׁבֶּן אָדָם זוֹכֶה בְּנֶפֶשׁ מִצַּד שֶׁל בַּת יְחִידָה, נֶאֱמַר בּוֹ לֹא תֵצֵא כְּצֵאת הָעֲבָדִים.</p>"]]});
